// Package tollgate provides pure, deterministic accounting, x402 invoice memo
// binding, tiered metering math, and cryptographic receipt commitments for the
// Tollgate on-chain HTTP 402 payment and metered pass protocol.
package tollgate

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strconv"
	"strings"
)

const (
	// ProtocolVersion identifies the canonical commitment and memo format.
	ProtocolVersion = "tollgate-v1"
	// ReceiptDomain separates receipt commitment hashes from other hashes.
	ReceiptDomain = "tollgate-receipt-v1"
	// MemoPrefix binds x402 extra.memo invoices to a Tollgate service and nonce.
	MemoPrefix = "tollgate:v1:"
	// MaxMemoBytes matches the gnolang/x402 facilitator memo limit.
	MaxMemoBytes = 256
	// MinChallengeBlocks is the minimum dispute window for metered settlements.
	MinChallengeBlocks int64 = 10
	// MaxChallengeBlocks caps the dispute window to prevent permanent lockups.
	MaxChallengeBlocks int64 = 100000

	maxInt64 int64 = 1<<63 - 1
)

var (
	ErrInvalidPrice   = errors.New("tollgate: unit price must be positive")
	ErrInvalidUnits   = errors.New("tollgate: units must be positive")
	ErrOverflow       = errors.New("tollgate: arithmetic overflow")
	ErrInvalidBalance = errors.New("tollgate: invalid balance accounting")
	ErrInvalidMemo    = errors.New("tollgate: invalid invoice memo or nonce")
	ErrInvalidHash    = errors.New("tollgate: invalid hex digest")
)

// ChargeBreakdown describes the deterministic cost of a metered batch.
type ChargeBreakdown struct {
	Units       int64
	UnitPrice   int64
	GrossUgnot  int64
	DiscountBps int64
	Discount    int64
	NetUgnot    int64
}

// TierDiscountBps returns the deterministic volume discount in basis points
// (1 bps = 0.01%) for a settled batch size.
func TierDiscountBps(units int64) int64 {
	switch {
	case units >= 1000:
		return 2000 // 20%
	case units >= 250:
		return 1500 // 15%
	case units >= 50:
		return 1000 // 10%
	case units >= 10:
		return 500 // 5%
	default:
		return 0
	}
}

// ComputeCharge calculates gross, volume discount, and net ugnot charge using
// overflow-checked integer arithmetic. Net charge is always at least 1 ugnot
// whenever unitPrice > 0 and units > 0.
func ComputeCharge(unitPrice int64, units int64) (ChargeBreakdown, error) {
	if unitPrice <= 0 {
		return ChargeBreakdown{}, ErrInvalidPrice
	}
	if units <= 0 {
		return ChargeBreakdown{}, ErrInvalidUnits
	}
	if units > maxInt64/unitPrice {
		return ChargeBreakdown{}, ErrOverflow
	}
	gross := unitPrice * units
	bps := TierDiscountBps(units)

	var discount int64
	if bps > 0 {
		if gross > maxInt64/bps {
			discount = (gross / 10000) * bps
		} else {
			discount = (gross * bps) / 10000
		}
	}
	net := gross - discount
	if net < 1 {
		net = 1
		discount = gross - net
	}
	return ChargeBreakdown{
		Units:       units,
		UnitPrice:   unitPrice,
		GrossUgnot:  gross,
		DiscountBps: bps,
		Discount:    discount,
		NetUgnot:    net,
	}, nil
}

// ComputeAvailable returns deposit - spent - pending with strict invariant checks.
func ComputeAvailable(deposit, spent, pending int64) (int64, error) {
	if deposit < 0 || spent < 0 || pending < 0 {
		return 0, ErrInvalidBalance
	}
	if spent > deposit || pending > deposit-spent {
		return 0, ErrInvalidBalance
	}
	return deposit - spent - pending, nil
}

// ValidateSlug checks that a service slug is 2..40 chars of [a-z0-9-] with
// alphanumeric start and end (no consecutive hyphens).
func ValidateSlug(slug string) bool {
	n := len(slug)
	if n < 2 || n > 40 {
		return false
	}
	prevHyphen := false
	for i := 0; i < n; i++ {
		c := slug[i]
		isAlphaNum := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
		if isAlphaNum {
			prevHyphen = false
			continue
		}
		if c == '-' && i > 0 && i < n-1 && !prevHyphen {
			prevHyphen = true
			continue
		}
		return false
	}
	return true
}

// ValidateNonce checks that a client/invoice nonce uses safe ASCII tokens
// [a-zA-Z0-9._-] with length 1..96.
func ValidateNonce(nonce string) bool {
	n := len(nonce)
	if n < 1 || n > 96 {
		return false
	}
	for i := 0; i < n; i++ {
		c := nonce[i]
		ok := (c >= 'a' && c <= 'z') ||
			(c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') ||
			c == '.' || c == '_' || c == '-'
		if !ok {
			return false
		}
	}
	return true
}

// IsValidHexDigest returns true iff s is a lowercase 64-character hex SHA-256 string.
func IsValidHexDigest(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < 64; i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return false
		}
	}
	return true
}

// FormatInvoiceMemo builds the canonical x402 extra.memo string binding an
// HTTP 402 payment offer to a specific Tollgate service ID and nonce.
func FormatInvoiceMemo(serviceID uint64, nonce string) (string, error) {
	if serviceID == 0 || !ValidateNonce(nonce) {
		return "", ErrInvalidMemo
	}
	memo := MemoPrefix + strconv.FormatUint(serviceID, 10) + ":" + nonce
	if len(memo) > MaxMemoBytes {
		return "", ErrInvalidMemo
	}
	return memo, nil
}

// ParseInvoiceMemo parses a canonical x402 extra.memo created by FormatInvoiceMemo.
func ParseInvoiceMemo(memo string) (serviceID uint64, nonce string, ok bool) {
	if len(memo) > MaxMemoBytes || !strings.HasPrefix(memo, MemoPrefix) {
		return 0, "", false
	}
	rest := memo[len(MemoPrefix):]
	sep := strings.IndexByte(rest, ':')
	if sep <= 0 || sep >= len(rest)-1 {
		return 0, "", false
	}
	id, err := strconv.ParseUint(rest[:sep], 10, 64)
	if err != nil || id == 0 {
		return 0, "", false
	}
	n := rest[sep+1:]
	if !ValidateNonce(n) {
		return 0, "", false
	}
	return id, n, true
}

func appendLP(b *strings.Builder, s string) {
	b.WriteString(strconv.Itoa(len(s)))
	b.WriteByte(':')
	b.WriteString(s)
	b.WriteByte('|')
}

// ReceiptCommitment computes the canonical, length-prefixed, domain-separated
// SHA-256 hex digest of a Tollgate usage or x402 payment receipt.
// Identical implementations exist in the Go and TypeScript SDKs.
func ReceiptCommitment(
	chainID string,
	serviceID uint64,
	passID uint64,
	buyer string,
	provider string,
	units int64,
	amountUgnot int64,
	nonce string,
	resourceHash string,
) string {
	var b strings.Builder
	b.WriteString(ReceiptDomain)
	b.WriteByte('|')
	appendLP(&b, chainID)
	b.WriteString(strconv.FormatUint(serviceID, 10))
	b.WriteByte('|')
	b.WriteString(strconv.FormatUint(passID, 10))
	b.WriteByte('|')
	appendLP(&b, buyer)
	appendLP(&b, provider)
	b.WriteString(strconv.FormatInt(units, 10))
	b.WriteByte('|')
	b.WriteString(strconv.FormatInt(amountUgnot, 10))
	b.WriteByte('|')
	appendLP(&b, nonce)
	appendLP(&b, resourceHash)

	sum := sha256.Sum256([]byte(b.String()))
	return hex.EncodeToString(sum[:])
}

// VerifyReceiptCommitment performs a constant-time check of expectedHex against
// the recomputed canonical receipt commitment.
func VerifyReceiptCommitment(
	expectedHex string,
	chainID string,
	serviceID uint64,
	passID uint64,
	buyer string,
	provider string,
	units int64,
	amountUgnot int64,
	nonce string,
	resourceHash string,
) bool {
	if !IsValidHexDigest(expectedHex) {
		return false
	}
	got := ReceiptCommitment(
		chainID, serviceID, passID, buyer, provider,
		units, amountUgnot, nonce, resourceHash,
	)
	if len(got) != len(expectedHex) {
		return false
	}
	var diff byte
	for i := 0; i < len(got); i++ {
		diff |= got[i] ^ expectedHex[i]
	}
	return diff == 0
}

// HashResource computes the lowercase SHA-256 hex digest of a canonical HTTP
// resource descriptor (for example, "GET /v1/inference?model=fast").
func HashResource(descriptor string) string {
	sum := sha256.Sum256([]byte(descriptor))
	return hex.EncodeToString(sum[:])
}

// Package ironclad provides pure, deterministic threat-class scoring, grading,
// path validation, and content-addressed audit attestation digest verification
// aligned with Gno.land's official Threat-Class Taxonomy (gno-security.md) and
// linter rules (AVL001, GLOBAL001, RENDER001).
package ironclad

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
)

const (
	ProtocolVersion   = "ironclad-v1"
	AttestationDomain = "ironclad-attestation-v1"

	WeightCritical = 30
	WeightHigh     = 15
	WeightMedium   = 6
	WeightLow      = 2
)

// ThreatClass describes an official Gno security threat class or lint family.
type ThreatClass struct {
	Code        string
	Title       string
	Severity    string
	Reference   string
	Remediation string
}

// ComputeScore computes a deterministic 0..100 security score from finding counts.
func ComputeScore(critical, high, medium, low int) int {
	if critical < 0 {
		critical = 0
	}
	if high < 0 {
		high = 0
	}
	if medium < 0 {
		medium = 0
	}
	if low < 0 {
		low = 0
	}
	penalty := critical*WeightCritical + high*WeightHigh + medium*WeightMedium + low*WeightLow
	if penalty >= 100 {
		return 0
	}
	return 100 - penalty
}

// ComputeGrade maps score and severe-finding gates to a letter trust grade.
func ComputeGrade(score, critical, high int) string {
	switch {
	case score == 100 && critical == 0 && high == 0:
		return "A+"
	case score >= 90 && critical == 0 && high == 0:
		return "A"
	case score >= 80 && critical == 0:
		return "B"
	case score >= 65 && critical == 0:
		return "C"
	case score >= 45:
		return "D"
	default:
		return "F"
	}
}

// IsValidHexDigest returns true iff s is a 64-char lowercase SHA-256 hex string.
func IsValidHexDigest(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < 64; i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return false
		}
	}
	return true
}

// ValidatePkgPath ensures targetPkgPath is a well-formed Gno realm or pure
// package path (e.g. gno.land/r/user/pkg or gno.land/p/user/pkg).
func ValidatePkgPath(path string) bool {
	if len(path) < 12 || len(path) > 160 {
		return false
	}
	if !strings.HasPrefix(path, "gno.land/r/") && !strings.HasPrefix(path, "gno.land/p/") {
		return false
	}
	if strings.Contains(path, "..") || strings.Contains(path, "//") || strings.HasSuffix(path, "/") {
		return false
	}
	for i := 0; i < len(path); i++ {
		c := path[i]
		ok := (c >= 'a' && c <= 'z') ||
			(c >= '0' && c <= '9') ||
			c == '/' || c == '.' || c == '_' || c == '-'
		if !ok {
			return false
		}
	}
	return true
}

func appendLP(b *strings.Builder, s string) {
	b.WriteString(strconv.Itoa(len(s)))
	b.WriteByte(':')
	b.WriteString(s)
	b.WriteByte('|')
}

// AttestationDigest computes the canonical length-prefixed SHA-256 commitment
// binding an audit verdict to exact chain, package path, source hash, report
// digest, analyzer version, and finding counts.
func AttestationDigest(
	chainID string,
	targetPkgPath string,
	sourceHash string,
	reportDigest string,
	analyzerVersion string,
	critical int,
	high int,
	medium int,
	low int,
	info int,
) string {
	var b strings.Builder
	b.WriteString(AttestationDomain)
	b.WriteByte('|')
	appendLP(&b, chainID)
	appendLP(&b, targetPkgPath)
	appendLP(&b, sourceHash)
	appendLP(&b, reportDigest)
	appendLP(&b, analyzerVersion)
	b.WriteString(strconv.Itoa(critical))
	b.WriteByte('|')
	b.WriteString(strconv.Itoa(high))
	b.WriteByte('|')
	b.WriteString(strconv.Itoa(medium))
	b.WriteByte('|')
	b.WriteString(strconv.Itoa(low))
	b.WriteByte('|')
	b.WriteString(strconv.Itoa(info))

	sum := sha256.Sum256([]byte(b.String()))
	return hex.EncodeToString(sum[:])
}

// VerifyAttestationDigest performs a constant-time equality check on a digest.
func VerifyAttestationDigest(
	expectedHex string,
	chainID string,
	targetPkgPath string,
	sourceHash string,
	reportDigest string,
	analyzerVersion string,
	critical, high, medium, low, info int,
) bool {
	if !IsValidHexDigest(expectedHex) {
		return false
	}
	got := AttestationDigest(
		chainID, targetPkgPath, sourceHash, reportDigest, analyzerVersion,
		critical, high, medium, low, info,
	)
	if len(got) != len(expectedHex) {
		return false
	}
	var diff byte
	for i := 0; i < len(got); i++ {
		diff |= got[i] ^ expectedHex[i]
	}
	return diff == 0
}

// Taxonomy returns a fresh slice of all official Gno security classes tracked
// by Ironclad (returning a fresh slice guarantees zero shared mutable state).
func Taxonomy() []ThreatClass {
	return []ThreatClass{
		{
			Code:        "GNO-TC1A",
			Title:       "Class-1a: cur-disclosure / impersonate-self",
			Severity:    "CRITICAL",
			Reference:   "docs/resources/gno-security.md#class-1a",
			Remediation: "Never declare interface methods taking cur realm; pass caller address derived under cur.IsCurrent().",
		},
		{
			Code:        "GNO-TC1B",
			Title:       "Class-1b: cur-disclosure / impersonate-caller",
			Severity:    "HIGH",
			Reference:   "docs/resources/gno-security.md#class-1b",
			Remediation: "Never hand live cur realm values into untrusted interface or callback calls.",
		},
		{
			Code:        "GNO-TC2",
			Title:       "Class-2: designation-forgery",
			Severity:    "CRITICAL",
			Reference:   "docs/resources/gno-security.md#class-2",
			Remediation: "Derive caller identity from cur.Previous().Address() guarded by cur.IsCurrent(); never trust address/pkgPath args.",
		},
		{
			Code:        "GNO-TC3",
			Title:       "Class-3: impl-substitution & sealing bypass",
			Severity:    "HIGH",
			Reference:   "docs/resources/gno-security.md#class-3",
			Remediation: "Enforce concrete type-switch or IsCanonical* allowlists; never rely on unexported interface sealing methods.",
		},
		{
			Code:        "GNO-TC4",
			Title:       "Class-4: closed-over-authority callback",
			Severity:    "HIGH",
			Reference:   "docs/resources/gno-security.md#class-4",
			Remediation: "Avoid invoking caller-supplied func() callbacks under realm authority; type callbacks with realm-owned types.",
		},
		{
			Code:        "GNO-SEC02",
			Title:       "Payment guard: IsUser() vs IsUserCall()",
			Severity:    "CRITICAL",
			Reference:   "docs/resources/gno-ai-contract-review.md#2",
			Remediation: "Guard OriginSend payment handlers with cur.Previous().IsUserCall(), never IsUser().",
		},
		{
			Code:        "GNO-SEC03",
			Title:       "Exported pointer to mutable state / /p/ mutator",
			Severity:    "HIGH",
			Reference:   "docs/resources/gno-ai-contract-review.md#3",
			Remediation: "Return value copies or scalar getters; never return *avl.Tree or pointers to realm state.",
		},
		{
			Code:        "GNO-SEC04",
			Title:       "Persisted realm or banker capability",
			Severity:    "CRITICAL",
			Reference:   "docs/resources/gno-ai-contract-review.md#6",
			Remediation: "Store address/pkgPath strings and mint bankers fresh per call; never persist realm or banker.Banker in globals.",
		},
		{
			Code:        "GNO-SEC05",
			Title:       "chain/runtime/unsafe stack-walk alongside cur realm",
			Severity:    "HIGH",
			Reference:   "docs/resources/gno-ai-contract-review.md#9",
			Remediation: "Replace unsafe.PreviousRealm()/CurrentRealm()/OriginCaller() with cur.Previous()/cur.Address().",
		},
		{
			Code:        "GNO-SEC06",
			Title:       "Unsanitized Render(path) Markdown injection",
			Severity:    "MEDIUM",
			Reference:   "docs/resources/gno-ai-contract-review.md#10",
			Remediation: "Escape user strings with gno.land/p/nt/markdown/sanitize/v0 (InlineText, TableCell, URL, Block).",
		},
		{
			Code:        "GNO-SEC07",
			Title:       "Unbounded GetCoins() single-denom lookup DoS",
			Severity:    "MEDIUM",
			Reference:   "docs/resources/gno-ai-contract-review.md#11",
			Remediation: "Use O(1) banker.GetCoin(addr, denom) instead of GetCoins(addr).AmountOf(denom).",
		},
		{
			Code:        "AVL001",
			Title:       "Unbounded avl.Tree iteration DoS",
			Severity:    "MEDIUM",
			Reference:   "gnolang/gno#5068",
			Remediation: "Use IterateByOffset / ReverseIterateByOffset or enforce an explicit row limit in callbacks.",
		},
		{
			Code:        "GLOBAL001",
			Title:       "Exported mutable global variable in realm",
			Severity:    "MEDIUM",
			Reference:   "gnolang/gno#5068",
			Remediation: "Keep realm state unexported and expose controlled read-only getters.",
		},
		{
			Code:        "RENDER001",
			Title:       "State mutation inside Render(path)",
			Severity:    "MEDIUM",
			Reference:   "gnolang/gno#5068",
			Remediation: "Keep Render strictly pure and side-effect free.",
		},
	}
}

// SPDX-License-Identifier: MIT
// Milestone Desk. Payment entitlements are decided by explicit, accepted rules;
// the chain does not decide whether off-chain work is good or truthful.
package milestonedesk

import (
 "chain"
 "chain/banker"
 "chain/runtime"
 "chain/runtime/unsafe"
 "crypto/bech32"
 "strconv"
 "strings"
)

type Milestone struct {
 Amount int64
 State string
 ProofURL string
 ProofHash string
 DeliveredAt int64
 ReviewEnd int64
 DisputeEnd int64
 Reason string
 ContractorPaid int64
 ClientRefund int64
 Outcome string
}
type Event struct { Height int64; Action string; Step int; Actor address; Detail string }
type Agreement struct {
 ID uint64
 Key string
 Fingerprint string
 Title string
 Client address
 Contractor address
 Arbiter address
 TermsHash string
 AcceptBy int64
 DeliverBy int64
 ReviewBlocks int64
 DisputeBlocks int64
 FallbackBPS int64
 State string
 Total int64
 Funded int64
 ClientOwed int64
 ContractorOwed int64
 ClientWithdrawn int64
 ContractorWithdrawn int64
 Steps []*Milestone
 Events []Event
}
var agreements = make(map[uint64]*Agreement)
var requestIDs = make(map[string]uint64)
var nextID uint64 = 1
var held int64
var vault address

func init(cur realm) { vault = cur.Address() }
func require(ok bool, message string) { if !ok { panic(message) } }
func number(n int64) string { return strconv.FormatInt(n,10) }
func idstr(n uint64) string { return strconv.FormatUint(n,10) }
func caller(cur realm, payable bool) address {
 require(cur.Previous().IsUserCall(), "direct wallet call required")
 if !payable { require(len(unsafe.OriginSend()) == 0, "this action accepts no coins") }
 return cur.Previous().Address()
}
func validAddress(s string) address {
 require(len(s)==40 && strings.HasPrefix(s,"g1"),"invalid Gno address")
 prefix, data, err := bech32.Decode(s)
 require(err==nil && prefix=="g" && len(data)==32,"invalid Gno address checksum")
 return address(s)
}
func hashOK(s string) bool {
 if len(s)!=64 { return false }
 for _, c := range s { if !((c>='0' && c<='9') || (c>='a' && c<='f')) { return false } }
 return s != strings.Repeat("0",64)
}
func textOK(s string, limit int) bool {
 if len(s)==0 || len(s)>limit { return false }
 for _,c := range s { if c<32 || c==127 { return false } }
 return true
}
func agreement(id uint64) *Agreement {
 a := agreements[id]; require(a!=nil,"agreement not found"); return a
}
func step(a *Agreement, index int) *Milestone {
 require(index>=0 && index<len(a.Steps),"milestone not found"); return a.Steps[index]
}
func record(a *Agreement, action string, index int, actor address, detail string) {
 a.Events=append(a.Events, Event{runtime.ChainHeight(),action,index,actor,detail})
 chain.Emit("MilestoneDesk", "agreement", idstr(a.ID), "action",action,"milestone",strconv.Itoa(index),"actor",actor.String())
}

// Create pins every economic term. An exact repeated key returns the existing
// agreement; reusing that key with changed terms is refused, even after expiry.
func Create(cur realm, key, title, contractor, arbiter, termsHash string, acceptBy, deliverBy, reviewBlocks, disputeBlocks, fallbackBPS int64, amounts string) uint64 {
 who:=caller(cur,false)
 require(textOK(key,96) && textOK(title,120),"invalid key or title")
 fingerprint:=strconv.Quote(title)+strconv.Quote(contractor)+strconv.Quote(arbiter)+strconv.Quote(termsHash)+":"+number(acceptBy)+":"+number(deliverBy)+":"+number(reviewBlocks)+":"+number(disputeBlocks)+":"+number(fallbackBPS)+":"+strconv.Quote(amounts)
 requestKey:=who.String()+"/"+key
 if old:=requestIDs[requestKey]; old!=0 {
  require(agreements[old].Fingerprint==fingerprint,"request key already has different terms")
  return old
 }
 worker:=validAddress(contractor); reviewer:=validAddress(arbiter)
 require(who!=worker && who!=reviewer && worker!=reviewer,"three distinct parties required")
 require(hashOK(termsHash),"terms hash must be a nonzero SHA-256 digest")
 height:=runtime.ChainHeight()
 require(acceptBy>height && acceptBy-height<=1000000,"acceptance deadline out of range")
 require(deliverBy>acceptBy && deliverBy-acceptBy<=1000000,"delivery deadline out of range")
 require(reviewBlocks>=2 && reviewBlocks<=1000000 && disputeBlocks>=2 && disputeBlocks<=1000000,"review and dispute windows must be 2 to 1000000 blocks")
 require(fallbackBPS>=0 && fallbackBPS<=10000,"fallback share must be 0 to 10000")
 parts:=strings.Split(amounts,","); require(len(parts)>0 && len(parts)<=12,"one to twelve milestones required")
 steps:=make([]*Milestone,0,len(parts)); var total int64
 for _,p:=range parts {
  v,err:=strconv.ParseInt(p,10,64);require(err==nil && v>0 && v<=1000000000,"invalid milestone amount")
  total+=v; require(total<=1000000000,"agreement exceeds 1000 GNOT")
  steps=append(steps,&Milestone{Amount:v,State:"unfunded"})
 }
 id:=nextID; nextID++
 a:=&Agreement{ID:id,Key:key,Fingerprint:fingerprint,Title:title,Client:who,Contractor:worker,Arbiter:reviewer,TermsHash:termsHash,AcceptBy:acceptBy,DeliverBy:deliverBy,ReviewBlocks:reviewBlocks,DisputeBlocks:disputeBlocks,FallbackBPS:fallbackBPS,State:"offered",Total:total,Steps:steps}
 agreements[id]=a; requestIDs[requestKey]=id; record(a,"created",-1,who,termsHash)
 return id
}
func Accept(cur realm,id uint64) {
 who:=caller(cur,false); a:=agreement(id)
 require(who==a.Contractor,"only the named contractor can accept")
 if a.State=="accepted" { return }
 require(a.State=="offered" && runtime.ChainHeight()<=a.AcceptBy,"offer not open for acceptance")
 a.State="accepted";record(a,"accepted",-1,who,a.TermsHash)
}
func CancelOffer(cur realm,id uint64) {
 who:=caller(cur,false);a:=agreement(id)
 require(who==a.Client,"only the client can cancel the offer")
 if a.State=="cancelled" { return }
 require(a.Funded==0 && (a.State=="offered" || a.State=="accepted"),"funded agreements cannot be cancelled")
 a.State="cancelled";record(a,"offer_cancelled",-1,who,"")
}
func Fund(cur realm,id uint64) {
 who:=caller(cur,true);a:=agreement(id)
 require(who==a.Client,"only the client can fund")
 require(a.State=="accepted" && runtime.ChainHeight()<=a.AcceptBy,"agreement not open for funding")
 coins:=unsafe.OriginSend()
 require(len(coins)==1 && coins[0].Denom=="ugnot" && coins[0].Amount==a.Total,"send the exact agreed ugnot amount")
 require(held<=9000000000000000-a.Total,"vault capacity reached")
 a.Funded=a.Total;held+=a.Total;a.State="active"
 for _,s:=range a.Steps {s.State="ready"}
 record(a,"funded",-1,who,number(a.Total))
}
func Deliver(cur realm,id uint64,index int,proofURL,proofHash string) {
 who:=caller(cur,false);a:=agreement(id);s:=step(a,index)
 require(who==a.Contractor,"only the contractor can deliver")
 if s.State=="review" && s.ProofHash==proofHash && s.ProofURL==proofURL {return}
 require(a.State=="active" && s.State=="ready","milestone not open for delivery")
 require(runtime.ChainHeight()<=a.DeliverBy,"delivery deadline passed")
 require(textOK(proofURL,512) && strings.HasPrefix(proofURL,"https://") && len(proofURL)>8,"HTTPS delivery URL required")
 require(hashOK(proofHash),"delivery hash must be a nonzero SHA-256 digest")
 s.ProofURL=proofURL;s.ProofHash=proofHash;s.DeliveredAt=runtime.ChainHeight()
 s.ReviewEnd=s.DeliveredAt+a.ReviewBlocks;s.State="review"
 record(a,"delivered",index,who,proofHash)
}
func settle(a *Agreement,s *Milestone,index int,workerShare int64,outcome string,who address) {
 require(s.State!="settled","milestone already settled")
 require(workerShare>=0 && workerShare<=s.Amount,"invalid settlement")
 s.ContractorPaid=workerShare;s.ClientRefund=s.Amount-workerShare;s.Outcome=outcome;s.State="settled"
 a.ContractorOwed+=workerShare;a.ClientOwed+=s.ClientRefund
 done:=true;for _,m:=range a.Steps {if m.State!="settled" {done=false}}
 if done {a.State="closed"}
 record(a,outcome,index,who,number(workerShare))
}
func Approve(cur realm,id uint64,index int) {
 who:=caller(cur,false);a:=agreement(id);s:=step(a,index)
 require(who==a.Client,"only the client can approve")
 if s.State=="settled" && s.Outcome=="approved" {return}
 require(s.State=="review","milestone is not awaiting review")
 settle(a,s,index,s.Amount,"approved",who)
}
func Dispute(cur realm,id uint64,index int,reason string) {
 who:=caller(cur,false);a:=agreement(id);s:=step(a,index)
 require(who==a.Client,"only the client can dispute delivery")
 if s.State=="disputed" && s.Reason==reason {return}
 require(s.State=="review" && runtime.ChainHeight()<=s.ReviewEnd,"review window closed")
 require(textOK(reason,500),"a bounded dispute reason is required")
 s.Reason=reason;s.DisputeEnd=runtime.ChainHeight()+a.DisputeBlocks;s.State="disputed"
 record(a,"disputed",index,who,reason)
}
func Resolve(cur realm,id uint64,index int,contractorBPS int64) {
 who:=caller(cur,false);a:=agreement(id);s:=step(a,index)
 require(who==a.Arbiter,"only the agreed arbiter can resolve")
 require(s.State=="disputed" && runtime.ChainHeight()<=s.DisputeEnd,"arbitration window closed")
 require(contractorBPS>=0 && contractorBPS<=10000,"invalid settlement share")
 settle(a,s,index,s.Amount*contractorBPS/10000,"arbitrated",who)
}
// Anyone can finalize an eligible milestone. No automated execution is implied:
// block height establishes eligibility; a transaction performs the transition.
func Finalize(cur realm,id uint64,index int) {
 who:=caller(cur,false);a:=agreement(id);s:=step(a,index);height:=runtime.ChainHeight()
 if s.State=="settled" {return}
 if s.State=="ready" {
  require(height>a.DeliverBy,"delivery window still open")
  settle(a,s,index,0,"missed_delivery",who)
 } else if s.State=="review" {
  require(height>s.ReviewEnd,"review window still open")
  settle(a,s,index,s.Amount,"review_expired",who)
 } else if s.State=="disputed" {
  require(height>s.DisputeEnd,"arbitration window still open")
  settle(a,s,index,s.Amount*a.FallbackBPS/10000,"fallback_split",who)
 } else {panic("milestone cannot be finalized")}
}
// Entitlements are recorded before transfers. Each party withdraws only their
// own balance; repeating a withdrawal returns zero instead of paying twice.
func Withdraw(cur realm,id uint64) int64 {
 who:=caller(cur,false);a:=agreement(id);var amount int64
 require(who==a.Client || who==a.Contractor,"only a payment party can withdraw")
 if who==a.Client {amount=a.ClientOwed} else {amount=a.ContractorOwed}
 if amount==0 {return 0}
 require(held>=amount,"vault accounting mismatch")
 if who==a.Client {a.ClientOwed=0;a.ClientWithdrawn+=amount} else {a.ContractorOwed=0;a.ContractorWithdrawn+=amount}
 held-=amount
 banker.NewBanker(banker.BankerTypeRealmSend,cur).SendCoins(cur.Address(),who,chain.Coins{{Denom:"ugnot",Amount:amount}})
 record(a,"withdrawn",-1,who,number(amount));return amount
}

