// Package drand gives every gno.land user and realm verifiable randomness
// from drand, with no trusted party.
//
// Flow:
//
//  1. A user or realm calls Request and gets an id. The request is pinned to
//     a drand round that will be published in the future (at least SafetyGap
//     seconds after the current block time), so nobody, including the
//     requester and the validators, knows its value yet.
//  2. Any relayer submits that round's drand signature with Submit. The realm
//     verifies it on-chain (BN254 pairing), so a relayer can only submit the
//     real beacon. Relayers are permissionless and interchangeable.
//  3. The requester reads its value with Get / MustGet. Each request gets its
//     own value, derived from the beacon, its requester and its id.
//
// Commit before you reveal: freeze whatever the randomness decides (tickets
// sold, bets placed) before calling Request.
package drand

import (
	"chain"
	"encoding/hex"
	"math/rand"
	"strconv"
	"strings"
	"time"

	evmnet "gno.land/p/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/drand/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

// SafetyGap is the minimum number of seconds between the block time of a
// request and the publication of the round it is pinned to. It absorbs
// block-time drift so the round is still unknown when the request lands.
const SafetyGap = int64(5)

// maxPendingList bounds PendingRounds so a qeval always fits its gas cap.
const maxPendingList = 100

type request struct {
	round     uint64
	requester string
}

var (
	ids      seqid.ID
	requests avl.Tree // id -> request
	pending  avl.Tree // roundKey -> true, rounds waiting for a beacon
	beacons  avl.Tree // roundKey -> [32]byte randomness, only rounds someone asked for
)

// Request asks for randomness from the next round that is safely in the
// future and returns the request id.
func Request(cur realm) string {
	return newRequest(cur, nextSafeRound())
}

// RequestAfter asks for randomness from the first round published strictly
// after unix time t (Nois' "randomness after"). If t is too close or in the
// past, the next safe round is used instead.
func RequestAfter(cur realm, t int64) string {
	round := evmnet.RoundAt(t) + 1
	if safe := nextSafeRound(); round < safe {
		round = safe
	}
	return newRequest(cur, round)
}

func newRequest(cur realm, round uint64) string {
	id := ids.Next().String()
	requester := cur.Previous().Address().String()
	requests.Set(id, request{round: round, requester: requester})

	key := roundKey(round)
	if !beacons.Has(key) && !pending.Has(key) {
		pending.Set(key, true)
	}
	chain.Emit("Request", "id", id, "round", strconv.FormatUint(round, 10), "requester", requester)
	return id
}

// nextSafeRound is the first round published at least SafetyGap seconds
// after the current block time.
func nextSafeRound() uint64 {
	return evmnet.RoundAt(time.Now().Unix()+SafetyGap) + 1
}

// Submit stores the drand beacon of a requested round after verifying its
// signature. sigHex is the "signature" field from the drand HTTP API.
// Submitting a round that is already stored is a no-op, so concurrent
// relayers do not fail each other's transactions.
func Submit(cur realm, round uint64, sigHex string) {
	key := roundKey(round)
	if beacons.Has(key) {
		return
	}
	if !pending.Has(key) {
		panic("round not requested")
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil {
		panic("signature is not hex")
	}
	if !evmnet.Verify(round, sig) {
		panic("invalid drand signature")
	}
	beacons.Set(key, evmnet.Randomness(sig))
	pending.Remove(key)
	chain.Emit("Beacon", "round", strconv.FormatUint(round, 10))
}

// Get returns the randomness of a request, and false while its round has
// not been submitted yet (or the id is unknown).
func Get(id string) ([32]byte, bool) {
	r, ok := getRequest(id)
	if !ok {
		return [32]byte{}, false
	}
	b, ok := Beacon(r.round)
	if !ok {
		return [32]byte{}, false
	}
	return evmnet.Derive(b, r.requester+":"+id), true
}

// MustGet is Get that panics while the randomness is not available.
func MustGet(id string) [32]byte {
	v, ok := Get(id)
	if !ok {
		panic("randomness not available yet")
	}
	return v
}

// Rand returns a PRNG seeded with the request's randomness, for drawing as
// many values as needed: drand.Rand(id).IntN(100). It panics while the
// randomness is not available. Each call starts a fresh generator from the
// same seed, so keep the returned value to draw a sequence.
func Rand(id string) *rand.Rand {
	return evmnet.NewRand(MustGet(id))
}

// Status returns the round a request is pinned to and whether its
// randomness is available. round is 0 for an unknown id.
func Status(id string) (round uint64, ready bool) {
	r, ok := getRequest(id)
	if !ok {
		return 0, false
	}
	return r.round, beacons.Has(roundKey(r.round))
}

// Beacon returns the raw drand randomness of a stored round. Prefer Get:
// values from Beacon are shared by everyone who uses the same round.
func Beacon(round uint64) ([32]byte, bool) {
	v := beacons.Get(roundKey(round))
	if v == nil {
		return [32]byte{}, false
	}
	return v.([32]byte), true
}

// PendingRounds lists up to limit requested rounds still waiting for a
// beacon, oldest first, as comma-separated decimals. Relayers poll this.
func PendingRounds(limit int) string {
	if limit <= 0 || limit > maxPendingList {
		limit = maxPendingList
	}
	out := make([]string, 0, limit)
	pending.Iterate("", "", func(k string, _ any) bool {
		out = append(out, strconv.FormatUint(keyRound(k), 10))
		return len(out) >= limit
	})
	return strings.Join(out, ",")
}

func getRequest(id string) (request, bool) {
	v := requests.Get(id)
	if v == nil {
		return request{}, false
	}
	return v.(request), true
}

// roundKey encodes a round as 8 big-endian bytes, so avl order is numeric order.
func roundKey(round uint64) string { return seqid.ID(round).Binary() }

func keyRound(k string) uint64 {
	id, _ := seqid.FromBinary(k)
	return uint64(id)
}

// Render shows the realm state on gnoweb.
func Render(path string) string {
	if strings.HasPrefix(path, "request/") {
		return renderRequest(strings.TrimPrefix(path, "request/"))
	}
	var b strings.Builder
	b.WriteString("# drand randomness\n\n")
	b.WriteString("Verifiable randomness from [drand](https://drand.love) evmnet, checked on-chain.\n\n")
	b.WriteString("```go\nid := drand.Request(cross(cur)) // tx 1: after freezing your inputs\nn := drand.Rand(id).IntN(100)    // tx 2: a few seconds later\n```\n\n")
	b.WriteString("## Status\n\n")
	b.WriteString(ufmt.Sprintf("- chain: `%s`\n", evmnet.ChainHash))
	b.WriteString(ufmt.Sprintf("- requests: %d\n", requests.Size()))
	b.WriteString(ufmt.Sprintf("- pending rounds: %d\n", pending.Size()))
	b.WriteString(ufmt.Sprintf("- stored beacons: %d\n", beacons.Size()))
	b.WriteString(ufmt.Sprintf("- next safe round: %d\n\n", nextSafeRound()))

	if beacons.Size() > 0 {
		b.WriteString("## Latest beacons\n\n| round | randomness |\n|---|---|\n")
		n := 0
		beacons.ReverseIterate("", "", func(k string, v any) bool {
			r := v.([32]byte)
			b.WriteString(ufmt.Sprintf("| %d | `%s` |\n", keyRound(k), hex.EncodeToString(r[:])))
			n++
			return n >= 10
		})
	}
	return b.String()
}

func renderRequest(id string) string {
	r, ok := getRequest(id)
	if !ok {
		return "# request not found\n"
	}
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# request %s\n\n", id)) // id is a known seqid, safe to echo
	b.WriteString(ufmt.Sprintf("- requester: `%s`\n", r.requester))
	b.WriteString(ufmt.Sprintf("- round: %d (published at %d)\n", r.round, evmnet.TimeOf(r.round)))
	if v, ok := Get(id); ok {
		b.WriteString(ufmt.Sprintf("- randomness: `%s`\n", hex.EncodeToString(v[:])))
	} else {
		b.WriteString("- randomness: pending\n")
	}
	return b.String()
}

// Package kylixdemo gives a newcomer something to trade on Kylix within two
// minutes: two GRC20 tokens, Obol and Drachma, registered in grc20reg, and a
// GRC721 collection, Kylix Relics, registered with Kylix. One call to Claim
// hands out some of each.
//
// The tokens have no decimals and no value. Anyone can claim, once per
// ClaimCooldownBlocks per address and at most MaxClaimsPerBlock claims per
// block across everyone.
package kylixdemo

import (
	"chain"
	"chain/runtime"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/kylix"
)

const (
	ClaimTokens         = 1000 // of each token, per claim
	ClaimCooldownBlocks = 720  // about an hour at 5 s blocks
	MaxClaimsPerBlock   = 10

	CollectionName = "Kylix Relics"
)

var (
	obol, drachma       *grc20.Token
	obolLed, drachmaLed *grc20.PrivateLedger
	obolKey, drachmaKey string

	relics    *grc721.Token
	relicsLed *grc721.PrivateLedger
	minted    uint64

	selfPath string

	lastClaim     avl.Tree // address -> int64 height of the last claim
	claimHeight   int64    // height that claimsInBlock counts for
	claimsInBlock int
)

func init(cur realm) {
	selfPath = cur.PkgPath()
	obol, obolLed = grc20.NewToken("Obol", "OBOL", 0, 1, cur)
	drachma, drachmaLed = grc20.NewToken("Drachma", "DRACHMA", 0, 2, cur)
	obolKey = grc20reg.Register(cross(cur), obol, "")
	drachmaKey = grc20reg.Register(cross(cur), drachma, "")

	relics, relicsLed = grc721.NewToken(CollectionName, "RELIC", 1, cur)
	kylix.RegisterItem(cross(cur), CollectionName, MoveRelic, RelicOwner)
	kylix.RegisterApprovalCheck(cross(cur), RelicApproved)
}

// Claim gives the caller ClaimTokens Obol, ClaimTokens Drachma and one new
// relic, and returns the relic's id.
func Claim(cur realm) string {
	caller := cur.Previous()
	if !caller.IsUser() {
		panic("kylixdemo: only users can claim")
	}
	who := caller.Address()
	h := runtime.ChainHeight()
	if v := lastClaim.Get(who.String()); v != nil {
		if next := v.(int64) + ClaimCooldownBlocks; h < next {
			panic("kylixdemo: already claimed; claim again from height " + strconv.FormatInt(next, 10))
		}
	}
	if h != claimHeight {
		claimHeight, claimsInBlock = h, 0
	}
	if claimsInBlock >= MaxClaimsPerBlock {
		panic("kylixdemo: the faucet is busy this block; try the next one")
	}
	claimsInBlock++
	lastClaim.Set(who.String(), h)

	check(obolLed.Mint(who, ClaimTokens))
	check(drachmaLed.Mint(who, ClaimTokens))
	minted++
	id := "relic-" + strconv.FormatUint(minted, 10)
	check(relicsLed.Mint(who, grc721.TokenID(id)))
	chain.Emit("Claimed", "to", who.String(), "relic", id)
	return id
}

// CollectionKey is the key Kylix knows the relics by: this realm's path.
func CollectionKey() string { return selfPath }

// TokenKey returns the grc20reg key of "OBOL" or "DRACHMA", which is what
// Kylix's PostIntent takes as a fungible key.
func TokenKey(symbol string) string { return ledgerFor(symbol).key }

// BalanceOf returns addr's balance of "OBOL" or "DRACHMA".
func BalanceOf(symbol string, addr address) int64 { return ledgerFor(symbol).tok.BalanceOf(addr) }

// Allowance returns how much spender may move of owner's "OBOL" or "DRACHMA".
func Allowance(symbol string, owner, spender address) int64 {
	return ledgerFor(symbol).tok.Allowance(owner, spender)
}

// Approve lets spender (typically a Kylix slot) move amount of the caller's
// "OBOL" or "DRACHMA".
func Approve(cur realm, symbol string, spender address, amount int64) {
	check(ledgerFor(symbol).led.CallerTeller().Approve(0, cur, spender, amount))
}

// Transfer sends amount of the caller's "OBOL" or "DRACHMA" to `to`.
func Transfer(cur realm, symbol string, to address, amount int64) {
	check(ledgerFor(symbol).led.CallerTeller().Transfer(0, cur, to, amount))
}

// ApproveRelic lets spender (typically a Kylix slot) move one of the
// caller's relics. Approving the empty address revokes.
func ApproveRelic(cur realm, spender address, id string) {
	check(relicsLed.CallerTeller().Approve(0, cur, spender, grc721.TokenID(id)))
}

// ApproveAllRelics lets operator move all of the caller's relics. Kylix does
// not use such an approval (see MoveRelic); approve one relic per offer.
func ApproveAllRelics(cur realm, operator address, approved bool) {
	check(relicsLed.CallerTeller().SetApprovalForAll(0, cur, operator, approved))
}

// TransferRelic sends one of the caller's relics to `to`.
func TransferRelic(cur realm, to address, id string) {
	who := cur.Previous().Address()
	check(relicsLed.CallerTeller().TransferFrom(0, cur, who, to, grc721.TokenID(id)))
}

// OwnerOfRelic returns the owner of a relic, or the empty address.
func OwnerOfRelic(id string) address { return RelicOwner(kylix.ItemID(id)) }

// MoveRelic is the move function registered with Kylix. Kylix calls it as
// an offer's slot, so cur.Previous() is that slot, and the transfer only
// succeeds if the owner approved that slot for this one relic. An approval
// for all relics is not used: a single-relic approval is cleared by the
// transfer, so its storage deposit is refunded to whoever settles, while an
// operator approval would stay behind (Kylix's rule for collections: an
// approval that Kylix uses must be consumed by the move).
func MoveRelic(cur realm, from, to address, itemID string) error {
	tid := grc721.TokenID(itemID)
	if a, err := relics.GetApproved(tid); err != nil || a != cur.Previous().Address() {
		return errors.New("kylixdemo: approve this offer's address for relic " + itemID + " itself; an approval for all relics is not used")
	}
	return relicsLed.CallerTeller().TransferFrom(0, cur, from, to, tid)
}

// RelicOwner is the owner function registered with Kylix.
func RelicOwner(id kylix.ItemID) address {
	owner, err := relics.OwnerOf(grc721.TokenID(id))
	if err != nil {
		return ""
	}
	return owner
}

// RelicApproved is the approval check registered with Kylix: whether
// spender is approved for this one relic (see MoveRelic: an approval for all
// relics does not count).
func RelicApproved(id kylix.ItemID, spender address) bool {
	approved, err := relics.GetApproved(grc721.TokenID(id))
	return err == nil && approved != "" && approved == spender
}

// Render shows what the demo offers and how to use it.
func Render(path string) string {
	var sb strings.Builder
	sb.WriteString("# Kylix demo assets\n\n")
	sb.WriteString("Call `Claim` to receive " + strconv.Itoa(ClaimTokens) + " Obol, " + strconv.Itoa(ClaimTokens) +
		" Drachma and one Kylix Relic, then trade them on Kylix. One claim per address every " +
		strconv.Itoa(ClaimCooldownBlocks) + " blocks.\n\n")
	sb.WriteString("| Asset | Kylix key | Supply |\n|---|---|---|\n")
	sb.WriteString("| Obol (fungible) | " + obolKey + " | " + strconv.FormatInt(obol.TotalSupply(), 10) + " |\n")
	sb.WriteString("| Drachma (fungible) | " + drachmaKey + " | " + strconv.FormatInt(drachma.TotalSupply(), 10) + " |\n")
	sb.WriteString("| " + CollectionName + " (items) | " + selfPath + " | " + strconv.FormatInt(relics.TotalSupply(), 10) + " |\n")
	return sb.String()
}

type tokenRef struct {
	tok *grc20.Token
	led *grc20.PrivateLedger
	key string
}

func ledgerFor(symbol string) tokenRef {
	switch symbol {
	case "OBOL":
		return tokenRef{obol, obolLed, obolKey}
	case "DRACHMA":
		return tokenRef{drachma, drachmaLed, drachmaKey}
	}
	panic("kylixdemo: unknown token " + strconv.Quote(symbol) + "; use OBOL or DRACHMA")
}

func check(err error) {
	if err != nil {
		panic("kylixdemo: " + err.Error())
	}
}

package luckypick

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/drand/v0"
)

const lookaheadSeconds = 60

type guess struct {
	player address
	choice int
	result int // 0 until settled
	roomID string
	round  uint64
}

var guesses avl.Tree

// Pick commits the number and the beacon request in one transaction.
func Pick(cur realm, number int) string {
	return requestGuess(number, "", cur)
}

func requestGuess(number int, roomID string, scope realm) string {
	if number < 1 || number > 4 {
		panic("pick a number from 1 to 4")
	}
	id := drand.RequestAfter(cross(scope), time.Now().Unix()+lookaheadSeconds)
	round, ready := drand.Status(id)
	if round == 0 || ready {
		panic("expected an unpublished round")
	}
	guesses.Set(id, guess{player: scope.Previous().Address(), choice: number, round: round, roomID: roomID})
	return id
}

func get(id string) guess {
	item := guesses.Get(id)
	if item == nil {
		panic("unknown pick")
	}
	return item.(guess)
}

// Settle is permissionless. Every retry returns the same result.
func Settle(cur realm, id string) int {
	g := get(id)
	if g.result == 0 {
		value := drand.MustGet(id)
		g.result = int(value[0]%4) + 1
		if g.roomID != "" {
			payRoom(id, g, cur)
		}
		guesses.Set(id, g)
	}
	return g.result
}

// Receipt gives clients typed values independent of the page layout.
func Receipt(id string) (uint64, int, int) {
	g := get(id)
	return g.round, g.choice, g.result
}

func Render(path string) string {
	if strings.HasPrefix(path, "room/") {
		return renderRoom(strings.TrimPrefix(path, "room/"))
	}
	if path != "" {
		item := guesses.Get(path)
		if item == nil {
			return "Pick not found."
		}
		g := item.(guess)
		out := "# Lucky Pick receipt\n\nPlayer: " + g.player.String() +
			"\n\nPicked: " + strconv.Itoa(g.choice) +
			"\n\ndrand request: [" + path + "](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/drand/v0:request/" + path + ")" +
			"\n\nevmnet round: " + strconv.FormatUint(g.round, 10)
		if g.roomID != "" {
			out += "\n\n[Room " + g.roomID + "](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/luckypick:room/" + g.roomID + ") · Entry 0.1 test GNOT · Prize 0.4 test GNOT"
		}
		if g.result == 0 {
			if _, ready := drand.Status(path); ready {
				return out + "\n\nProof verified. [Ready to settle](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/luckypick$help&func=Settle&id=" + path + ")."
			}
			return out + "\n\nWaiting for the signed beacon."
		}
		out += "\n\nDrawn: " + strconv.Itoa(g.result)
		if g.choice == g.result {
			out += " · Match"
			if g.roomID != "" {
				out += "\n\nPaid 0.4 test GNOT to the player and 0.1 test GNOT to the host."
			}
			return out
		}
		out += " · Miss"
		if g.roomID != "" {
			r := getRoom(g.roomID)
			out += "\n\nPaid 0.1 test GNOT to the host."
			if len(r.picks) == maxPicks && r.picks[maxPicks-1] == path {
				out += " Returned the 0.4 test GNOT prize to the host."
			}
		}
		return out
	}
	var page strings.Builder
	page.WriteString(renderLobby() + "\n\n## Recent picks\n\n")
	if guesses.Size() == 0 {
		page.WriteString("No picks yet.")
	}
	guesses.ReverseIterateByOffset(0, 10, func(id string, _ any) bool {
		page.WriteString("- [" + id + "](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/luckypick:" + id + ")\n")
		return false
	})
	return page.String()
}

package luckypick

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	prize    = int64(400000)
	entry    = int64(100000)
	maxPicks = 5
)

type room struct {
	host    address
	picks   []string
	pending string
	closed  string
}

var (
	rooms        avl.Tree
	pendingPicks avl.Tree
	roomIDs      seqid.ID
)

func getRoom(id string) room {
	item := rooms.Get(id)
	if item == nil {
		panic("unknown room")
	}
	return item.(room)
}

func requireDeposit(amount int64) {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != amount {
		panic("send exactly " + strconv.FormatInt(amount, 10) + "ugnot")
	}
}

// OpenRoom locks the host's prize until the room ends.
func OpenRoom(cur realm) string {
	runtime.AssertOriginCall()
	requireDeposit(prize)
	id := roomIDs.Next().String()
	rooms.Set(id, room{host: cur.Previous().Address()})
	return id
}

// JoinRoom accepts a single paid guess when the room is idle.
func JoinRoom(cur realm, roomID string, number int) string {
	r := getRoom(roomID)
	if r.closed != "" || r.pending != "" {
		panic("room is closed or awaiting settlement")
	}
	runtime.AssertOriginCall()
	requireDeposit(entry)
	id := requestGuess(number, roomID, cur)
	r.picks = append(r.picks, id)
	r.pending = id
	pendingPicks.Set(id, true)
	rooms.Set(roomID, r)
	return id
}

func payRoom(requestID string, g guess, scope realm) {
	r := getRoom(g.roomID)
	if r.pending != requestID || r.closed != "" {
		panic("request does not match pending room pick")
	}
	hostAmount := entry
	b := banker.NewBanker(banker.BankerTypeRealmSend, scope)
	if g.result == g.choice {
		b.SendCoins(scope.Address(), g.player, chain.Coins{{"ugnot", prize}})
		r.closed = "Player won"
	} else if len(r.picks) == maxPicks {
		hostAmount += prize
		r.closed = "Host won"
	}
	b.SendCoins(scope.Address(), r.host, chain.Coins{{"ugnot", hostAmount}})
	r.pending = ""
	pendingPicks.Remove(requestID)
	rooms.Set(g.roomID, r)
}

// CloseRoom returns the prize to its host before the first guess.
func CloseRoom(cur realm, roomID string) {
	r := getRoom(roomID)
	if cur.Previous().Address() != r.host {
		panic("host only")
	}
	if r.closed != "" || r.pending != "" {
		panic("room is closed or awaiting settlement")
	}
	if len(r.picks) > 0 {
		panic("only rooms with no guesses can be closed")
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), r.host, chain.Coins{{"ugnot", prize}})
	r.closed = "Prize returned to host"
	rooms.Set(roomID, r)
}

// PendingPicks returns up to 20 unsettled room request IDs after the cursor.
func PendingPicks(after string) string {
	var ids []string
	pendingPicks.Iterate(after, "", func(id string, _ any) bool {
		if id != after {
			ids = append(ids, id)
		}
		return len(ids) == 20
	})
	return strings.Join(ids, ",")
}

func (r room) status() string {
	if r.closed != "" {
		return r.closed
	}
	if r.pending != "" {
		return "Awaiting draw"
	}
	return "Open"
}

func renderLobby() string {
	var p strings.Builder
	p.WriteString("# Lucky Pick\n\nPick 1–4. First match wins 0.4 test GNOT. Each guess costs 0.1 test GNOT; the host receives each entry fee. After five misses, the host gets the prize back.\n\n[Open a room](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/luckypick$help&func=OpenRoom&.send=400000ugnot) · Send 400000ugnot with this action.\n\n## Recent rooms\n\n")
	if rooms.Size() == 0 {
		p.WriteString("No rooms yet.")
	}
	rooms.ReverseIterateByOffset(0, 10, func(id string, item any) bool {
		r := item.(room)
		p.WriteString("- [Room " + id + "](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/luckypick:room/" + id + ") · " + r.status() + "\n")
		return false
	})
	return p.String()
}

func renderRoom(id string) string {
	if rooms.Get(id) == nil {
		return "Room not found."
	}
	r := getRoom(id)
	var p strings.Builder
	p.WriteString("# Room " + id + "\n\n" + r.status() + " · Host: " + r.host.String())
	p.WriteString("\n\nPrize: 0.4 test GNOT · Entry: 0.1 test GNOT · Guesses: " + strconv.Itoa(len(r.picks)) + "/5")
	if r.closed == "" && r.pending == "" {
		p.WriteString("\n\n[Pick a number](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/luckypick$help&func=JoinRoom&roomID=" + id + "&.send=100000ugnot) · Send 100000ugnot.")
		if len(r.picks) == 0 {
			p.WriteString("\n\n[Close room](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/luckypick$help&func=CloseRoom&roomID=" + id + ") · Host only, before the first guess.")
		}
	}
	for i, req := range r.picks {
		g := get(req)
		p.WriteString("\n\n[Guess " + strconv.Itoa(i+1) + "](/r/g1lfl0wj4qct6hch7g0d6kee0e605yj9fxdpu8mq/luckypick:" + req + ") · Picked " + strconv.Itoa(g.choice))
		if g.result == 0 {
			p.WriteString(" · Pending")
		} else {
			p.WriteString(" · Drawn " + strconv.Itoa(g.result))
		}
	}
	return p.String()
}

package tollgate

import (
	"chain/runtime"
	"strconv"
	"strings"

	ptollgate "gno.land/p/g1zt8w45ecxhlsdse7hd5gwr6xzcaxy9zsej6hl2/tollgate"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

const realmBaseLink = "/r/g1zt8w45ecxhlsdse7hd5gwr6xzcaxy9zsej6hl2/tollgate"

func rlink(sub string) string {
	if sub == "" {
		return realmBaseLink
	}
	return realmBaseLink + ":" + sub
}

func actionLink(fn string, params string) string {
	if params == "" {
		return realmBaseLink + "$help&func=" + fn
	}
	return realmBaseLink + "$help&func=" + fn + "&" + params
}

// jsonEscape produces strict RFC 8259 JSON and unicode-escapes Markdown
// metacharacters so :json/* routes cannot inject active Markdown in gnoweb.
func jsonEscape(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '[', ']', '<', '>', '*', '_', '|', '#', '!', '`':
			b.WriteString(`\u00`)
			const hexDigits = "0123456789abcdef"
			b.WriteByte(hexDigits[c>>4])
			b.WriteByte(hexDigits[c&0x0f])
		default:
			if c < 0x20 {
				b.WriteString(" ")
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func Render(path string) string {
	path = strings.Trim(path, "/")
	if path == "" {
		return renderHome()
	}

	parts := strings.Split(path, "/")
	switch parts[0] {
	case "services":
		return renderServices()
	case "service":
		if len(parts) == 2 {
			return renderServiceDetail(parts[1])
		}
	case "passes":
		return renderPasses()
	case "pass":
		if len(parts) == 2 {
			return renderPassDetail(parts[1])
		}
	case "subs":
		return renderSubs()
	case "sub":
		if len(parts) == 2 {
			return renderSubDetail(parts[1])
		}
	case "receipt":
		if len(parts) == 2 {
			return renderReceiptDetail(parts[1])
		}
	case "disputes":
		return renderDisputes()
	case "json":
		return renderJSON(parts[1:])
	}

	return "# Tollgate — Not Found\n\nUnknown route " + sanitize.InlineCode(path) + ".\n\n[Back to Tollgate Home](" + rlink("") + ")\n"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Tollgate — On-Chain x402 Metering & Receipt Protocol\n\n")
	b.WriteString("> Bridging `gnolang/x402` HTTP 402 micropayments with Ed25519-authenticated prepaid credit vaults, fixed-window subscriptions, challenge-window settlements, and verifiable SHA-256 receipts on Gno.land.\n\n")

	b.WriteString("## Quick Actions\n\n")
