				rlink("service/"+strconv.FormatUint(r.serviceID, 10)),
				r.units, r.amountUgnot, signedStr, shortHash,
			))
			return false
		})
		b.WriteString("\n")
	}

	b.WriteString("## Explorer Navigation\n\n")
