	b.WriteString("- [Threat-Class Taxonomy (15 Rules)](/r/g1zt8w45ecxhlsdse7hd5gwr6xzcaxy9zsej6hl2/ironclad:taxonomy) · [Auditor Directory](/r/g1zt8w45ecxhlsdse7hd5gwr6xzcaxy9zsej6hl2/ironclad:auditors)\n")
