package qfmath

// u128 provides minimal, deterministic, zero-float 128-bit unsigned integer
// arithmetic so quadratic funding sums, pairwise overlap denominators, HHI
// concentration scores, and Hamilton apportionment remain overflow-free across
// the entire positive int64 domain.
type u128 struct {
	hi uint64
	lo uint64
}

func u128From64(v uint64) u128 {
	return u128{hi: 0, lo: v}
}

func (a u128) isZero() bool {
	return a.hi == 0 && a.lo == 0
}

func (a u128) cmp(b u128) int {
	if a.hi < b.hi {
		return -1
	}
	if a.hi > b.hi {
		return 1
	}
	if a.lo < b.lo {
		return -1
	}
	if a.lo > b.lo {
		return 1
	}
	return 0
}

func add128(a, b u128) u128 {
	lo := a.lo + b.lo
	carry := uint64(0)
	if lo < a.lo {
		carry = 1
	}
	hi := a.hi + b.hi + carry
	if hi < a.hi || (carry == 1 && hi == a.hi) {
		panic("qfmath: u128 addition overflow")
	}
	return u128{hi: hi, lo: lo}
}

func sub128(a, b u128) u128 {
	borrow := uint64(0)
	if a.lo < b.lo {
		borrow = 1
	}
	lo := a.lo - b.lo
	if a.hi < b.hi+borrow {
		panic("qfmath: u128 subtraction underflow")
	}
	hi := a.hi - b.hi - borrow
	return u128{hi: hi, lo: lo}
}

// mul64 multiplies two uint64 values into an exact 128-bit product.
func mul64(x, y uint64) u128 {
	const mask32 = (uint64(1) << 32) - 1
	x0 := x & mask32
	x1 := x >> 32
	y0 := y & mask32
	y1 := y >> 32

	w0 := x0 * y0
	t := x1*y0 + (w0 >> 32)
	w1 := t & mask32
	w2 := t >> 32
	w1 += x0 * y1

	hi := x1*y1 + w2 + (w1 >> 32)
	lo := (w1 << 32) | (w0 & mask32)
	return u128{hi: hi, lo: lo}
}

// mul128By64 multiplies a u128 by a uint64, panicking on 128-bit overflow.
func mul128By64(a u128, b uint64) u128 {
	loProd := mul64(a.lo, b)
	hiProd := mul64(a.hi, b)
	if hiProd.hi != 0 {
		panic("qfmath: u128 multiplication overflow")
	}
	hi := hiProd.lo + loProd.hi
	if hi < hiProd.lo {
		panic("qfmath: u128 multiplication overflow")
	}
	return u128{hi: hi, lo: loProd.lo}
}

func bitLen64(v uint64) int {
	n := 0
	for v > 0 {
		v >>= 1
		n++
	}
	return n
}

func (a u128) bitLen() int {
	if a.hi != 0 {
		return 64 + bitLen64(a.hi)
	}
	return bitLen64(a.lo)
}

func (a u128) lsh(n uint) u128 {
	if n == 0 {
		return a
	}
	if n >= 128 {
		return u128{}
	}
	if n >= 64 {
		return u128{hi: a.lo << (n - 64), lo: 0}
	}
	return u128{
		hi: (a.hi << n) | (a.lo >> (64 - n)),
		lo: a.lo << n,
	}
}

func (a u128) rsh(n uint) u128 {
	if n == 0 {
		return a
	}
	if n >= 128 {
		return u128{}
	}
	if n >= 64 {
		return u128{hi: 0, lo: a.hi >> (n - 64)}
	}
	return u128{
		hi: a.hi >> n,
		lo: (a.lo >> n) | (a.hi << (64 - n)),
	}
}

func (a u128) bit(pos uint) uint64 {
	if pos >= 128 {
		return 0
	}
	if pos >= 64 {
		return (a.hi >> (pos - 64)) & 1
	}
	return (a.lo >> pos) & 1
}

func (a u128) setBit(pos uint) u128 {
	if pos >= 64 {
		a.hi |= uint64(1) << (pos - 64)
	} else {
		a.lo |= uint64(1) << pos
	}
	return a
}

// divRem128 computes quotient q and remainder r such that a = q*b + r and 0 <= r < b.
func divRem128(a, b u128) (q, r u128) {
	if b.isZero() {
		panic("qfmath: division by zero")
	}
	if a.cmp(b) < 0 {
		return u128{}, a
	}
	if a.hi == 0 && b.hi == 0 {
		return u128From64(a.lo / b.lo), u128From64(a.lo % b.lo)
	}

	bits := a.bitLen()
	for i := bits - 1; i >= 0; i-- {
		r = r.lsh(1)
		r.lo |= a.bit(uint(i))
		if r.cmp(b) >= 0 {
			r = sub128(r, b)
			q = q.setBit(uint(i))
		}
	}
	return q, r
}

// isqrt128 returns floor(sqrt(n)) as a uint64 for any u128 value.
// For any n < 2^128, floor(sqrt(n)) < 2^64 and always fits in uint64.
func isqrt128(n u128) uint64 {
	if n.isZero() {
		return 0
	}
	if n.hi == 0 {
		return isqrt64u(n.lo)
	}
	// Binary search on the exact bit length half-range [0, 2^64-1].
	shift := uint((n.bitLen() + 1) / 2)
	var lo, hi uint64
	if shift >= 64 {
		hi = ^uint64(0)
	} else {
		hi = (uint64(1) << shift) - 1
	}
	if shift > 1 {
		lo = uint64(1) << (shift - 1)
	}
	for lo < hi {
		// mid = lo + (hi - lo + 1) / 2 avoiding uint64 overflow
		mid := lo + ((hi - lo) >> 1) + ((hi - lo) & 1)
		sq := mul64(mid, mid)
		cmp := sq.cmp(n)
		if cmp == 0 {
			return mid
		}
		if cmp < 0 {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return lo
}

// isqrt64u computes exact floor(sqrt(u)) for any uint64 using Newton's method.
func isqrt64u(u uint64) uint64 {
	if u < 2 {
		return u
	}
	// Initial overestimate x0 >= sqrt(u) guarantees monotonic convergence.
	shift := uint((bitLen64(u) + 1) / 2)
	var x uint64
	if shift >= 32 {
		x = (uint64(1) << 32) - 1
	} else {
		x = uint64(1) << shift
	}
	for {
		next := (x + u/x) >> 1
		if next >= x {
			// Guard against underestimate when shift was capped at 32.
			for x < ^uint64(0) && mul64(x+1, x+1).cmp(u128From64(u)) <= 0 {
				x++
			}
			return x
		}
		x = next
	}
}

// Package quorumcraft implements QuorumCraft, an on-chain Pairwise Quadratic
// Funding & Milestone Escrow Protocol for Gno.land.
//
// Core capabilities:
//   - Permissionless Quadratic Grant Rounds funded with real escrowed ugnot
//   - Deterministic anti-collusion matching via PairwiseQF (Vitalik Buterin 2019)
//   - Milestone-structured builder proposals (2-4 tranches summing to 100%)
//   - Quorum-gated proof attestation, dispute resolution, and atomic banker payouts
//   - Multi-page on-chain Markdown + SVG Render() explorer
package quorumcraft

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1v4wuqfzakzpty87t0njkcjtx8yte4v5d8v69tj/qfmath"
	"gno.land/p/nt/avl/v0"
)

var (
	rounds        []*Round
	totalEscrowed int64
	totalReleased int64
	totalRefunded int64
)

// receiveUgnot validates and returns ugnot attached to a direct EOA call.
// If allowZero is true, zero coins are permitted without requiring an EOA send.
func receiveUgnot(cur realm, allowZero bool) int64 {
	sent := unsafe.OriginSend()
	if len(sent) == 0 {
		if allowZero {
			return 0
		}
		panic("quorumcraft: must send positive ugnot amount")
	}

	if !cur.Previous().IsUserCall() {
		panic("quorumcraft: direct user call (maketx call) required for coin transfers")
	}

	for _, c := range sent {
		if c.Denom != ugnotDenom {
			panic("quorumcraft: only ugnot denomination accepted")
		}
	}

	amt := sent.AmountOf(ugnotDenom)
	if amt <= 0 {
		if allowZero {
			return 0
		}
		panic("quorumcraft: must send positive ugnot amount")
	}

	// Verify real bank balance backs our escrowed accounting ledger.
	roBank := banker.NewReadonlyBanker()
	if roBank.GetCoin(cur.Address(), ugnotDenom) < totalEscrowed+amt {
		panic("quorumcraft: insufficient realm bank balance for reported send")
	}
	return amt
}

// CreateRound launches a new Quadratic Funding grant round.
// Any ugnot sent with the transaction is escrowed as the initial matching pool.
//
// Parameters:
//   - mode: 0 = StandardQF, 1 = PairwiseQF (anti-collusion)
//   - penaltyCoeff: pairwise damping factor M in ugnot (required > 0 for PairwiseQF)
//   - quorumBps: attestation quorum in basis points (1..10000, e.g. 5000 = 50%)
//   - durationBlocks: blocks until permissionless finalization (0 = sponsor-only close)
func CreateRound(
	cur realm,
	name string,
	description string,
	mode int,
	penaltyCoeff int64,
	quorumBps int64,
	durationBlocks int64,
) int {
	name = strings.TrimSpace(name)
	description = strings.TrimSpace(description)
	if name == "" || len(name) > 120 {
		panic("quorumcraft: invalid round name")
	}
	if len(description) > 1000 {
		panic("quorumcraft: round description too long")
	}
	qfMode := QFMode(mode)
	if qfMode != ModeStandardQF && qfMode != ModePairwiseQF {
		panic("quorumcraft: invalid QF mode (use 0=StandardQF or 1=PairwiseQF)")
	}
	if qfMode == ModePairwiseQF && penaltyCoeff <= 0 {
		panic("quorumcraft: PairwiseQF requires positive penaltyCoeff")
	}
	if quorumBps <= 0 || quorumBps > bpsFull {
		panic("quorumcraft: quorumBps must be between 1 and 10000")
	}
	if durationBlocks < 0 {
		panic("quorumcraft: durationBlocks cannot be negative")
	}

	initialPool := receiveUgnot(cur, true)
	sponsor := cur.Previous().Address()
	nowHeight := runtime.ChainHeight()
	var endHeight int64
	if durationBlocks > 0 {
		endHeight = nowHeight + durationBlocks
	}

	reviewers := avl.NewTree()
	reviewers.Set(sponsor.String(), true)

	roundID := len(rounds) + 1
	r := &Round{
		ID:           roundID,
		Sponsor:      sponsor,
		Name:         name,
		Description:  description,
		Mode:         qfMode,
		PenaltyCoeff: penaltyCoeff,
		QuorumBps:    quorumBps,
		EndHeight:    endHeight,
		MatchingPool: initialPool,
		Status:       RoundOpen,
		Reviewers:    reviewers,
		Donors:       avl.NewTree(),
		Proposals:    make([]*Proposal, 0),
		CreatedAt:    nowHeight,
	}
	rounds = append(rounds, r)
	totalEscrowed += initialPool

	chain.Emit(
		"RoundCreated",
		"roundId", strconv.Itoa(roundID),
		"sponsor", sponsor.String(),
		"mode", qfMode.String(),
		"matchingPool", strconv.FormatInt(initialPool, 10),
	)
	return roundID
}

// FundMatchingPool adds escrowed ugnot to an open round's matching pool.
func FundMatchingPool(cur realm, roundID int) {
	r := mustGetRound(roundID)
	if r.Status != RoundOpen {
		panic("quorumcraft: round is already finalized")
	}
	amt := receiveUgnot(cur, false)
	r.MatchingPool += amt
	totalEscrowed += amt

	chain.Emit(
		"MatchingPoolFunded",
		"roundId", strconv.Itoa(roundID),
		"funder", cur.Previous().Address().String(),
		"amount", strconv.FormatInt(amt, 10),
		"newPool", strconv.FormatInt(r.MatchingPool, 10),
	)
}

// AddReviewer authorizes an additional reviewer address to attest or dispute
// milestones for proposals in the specified round. Sponsor-only.
func AddReviewer(cur realm, roundID int, reviewer address) {
	r := mustGetRound(roundID)
	caller := cur.Previous().Address()
	if caller != r.Sponsor {
		panic("quorumcraft: only round sponsor can add reviewers")
	}
	if !reviewer.IsValid() {
		panic("quorumcraft: invalid reviewer address")
	}
	r.Reviewers.Set(reviewer.String(), true)

	chain.Emit(
		"ReviewerAdded",
		"roundId", strconv.Itoa(roundID),
		"reviewer", reviewer.String(),
	)
}

// parseMilestoneSpec parses "Title1:3000|Title2:4000|Title3:3000" into 2..4 milestones
// whose basis points strictly sum to 10000 (100.00%).
func parseMilestoneSpec(spec string) []*Milestone {
	spec = strings.TrimSpace(spec)
	if spec == "" {
		panic("quorumcraft: milestoneSpec required")
	}
	parts := strings.Split(spec, "|")
	if len(parts) < minMilestones || len(parts) > maxMilestones {
		panic("quorumcraft: proposal must define 2 to 4 milestones")
	}

	milestones := make([]*Milestone, len(parts))
	var sumBps int64
	for i, part := range parts {
		part = strings.TrimSpace(part)
		sep := strings.LastIndex(part, ":")
		if sep <= 0 || sep == len(part)-1 {
			panic("quorumcraft: invalid milestone format (expected Title:Bps)")
		}
		title := strings.TrimSpace(part[:sep])
		bpsStr := strings.TrimSpace(part[sep+1:])
		if title == "" || len(title) > 100 {
			panic("quorumcraft: invalid milestone title")
		}
		bps, err := strconv.ParseInt(bpsStr, 10, 64)
		if err != nil || bps <= 0 || bps > bpsFull {
			panic("quorumcraft: invalid milestone basis points")
		}
		sumBps += bps
		milestones[i] = &Milestone{
			Index:     i,
			Title:     title,
			Bps:       bps,
			Status:    MilestonePending,
			Approvals: avl.NewTree(),
		}
	}
	if sumBps != bpsFull {
		panic("quorumcraft: milestone basis points must sum to 10000")
	}
	return milestones
}

// SubmitProposal registers a milestone-structured builder proposal in an open round.
// milestoneSpec format: "M1 Spec & Tests:3000|M2 Testnet Deploy:4000|M3 Mainnet Audit:3000"
func SubmitProposal(
	cur realm,
	roundID int,
	title string,
	repoURL string,
	summary string,
	milestoneSpec string,
) int {
	r := mustGetRound(roundID)
	if r.Status != RoundOpen {
		panic("quorumcraft: round is already finalized")
	}
	title = strings.TrimSpace(title)
	repoURL = strings.TrimSpace(repoURL)
	summary = strings.TrimSpace(summary)
	if title == "" || len(title) > 120 {
		panic("quorumcraft: invalid proposal title")
	}
	if len(repoURL) > 240 {
		panic("quorumcraft: repoURL too long")
	}
	if summary == "" || len(summary) > 1500 {
		panic("quorumcraft: invalid proposal summary")
	}

	milestones := parseMilestoneSpec(milestoneSpec)
	recipient := cur.Previous().Address()
	propID := len(r.Proposals) + 1

	p := &Proposal{
		ID:            propID,
		RoundID:       roundID,
		Recipient:     recipient,
		Title:         title,
		RepoURL:       repoURL,
		Summary:       summary,
		DonorContribs: avl.NewTree(),
		Milestones:    milestones,
		CreatedAt:     runtime.ChainHeight(),
	}
	r.Proposals = append(r.Proposals, p)

	chain.Emit(
		"ProposalSubmitted",
		"roundId", strconv.Itoa(roundID),
		"proposalId", strconv.Itoa(propID),
		"recipient", recipient.String(),
		"milestones", strconv.Itoa(len(milestones)),
	)
	return propID
}

// Contribute sends real escrowed ugnot directly to a proposal during an open round.
// Repeat contributions from the same donor aggregate into their single matrix cell,
// preventing trivial split-transaction quadratic amplification.
func Contribute(cur realm, roundID int, proposalID int) {
	r := mustGetRound(roundID)
	if r.Status != RoundOpen {
		panic("quorumcraft: round is already finalized")
	}
	p := mustGetProposal(r, proposalID)
	donor := cur.Previous().Address()
	if donor == p.Recipient {
		panic("quorumcraft: proposal recipient cannot self-contribute")
	}

	amt := receiveUgnot(cur, false)
	donorKey := donor.String()

	var prevProp int64
	if v := p.DonorContribs.Get(donorKey); v != nil {
		prevProp = v.(int64)
	}
	p.DonorContribs.Set(donorKey, prevProp+amt)
	p.DirectTotal += amt

	var prevRound int64
	if v := r.Donors.Get(donorKey); v != nil {
		prevRound = v.(int64)
	}
	r.Donors.Set(donorKey, prevRound+amt)
	r.DirectTotal += amt
	totalEscrowed += amt

	chain.Emit(
		"ContributionReceived",
		"roundId", strconv.Itoa(roundID),
		"proposalId", strconv.Itoa(proposalID),
		"donor", donorKey,
		"amount", strconv.FormatInt(amt, 10),
	)
}

// buildContributionMatrix constructs the deterministic [numProposals][numDonors]
// matrix ordered by proposal ID and lexicographically sorted donor address.
func buildContributionMatrix(r *Round) (matrix [][]int64, donorWeights []int64) {
	numProps := len(r.Proposals)
	numDonors := r.Donors.Size()
	donorKeys := make([]string, 0, numDonors)
	donorWeights = make([]int64, 0, numDonors)
	r.Donors.Iterate("", "", func(key string, val any) bool {
		donorKeys = append(donorKeys, key)
		donorWeights = append(donorWeights, val.(int64))
		return false
	})

	matrix = make([][]int64, numProps)
	for pi, p := range r.Proposals {
		row := make([]int64, numDonors)
		for di, dk := range donorKeys {
			if v := p.DonorContribs.Get(dk); v != nil {
				row[di] = v.(int64)
			}
		}
		matrix[pi] = row
	}
	return matrix, donorWeights
}

// PreviewRoundMatching returns live deterministic StandardQF and PairwiseQF
// matching allocations for a round without mutating state.
func PreviewRoundMatching(roundID int) (stdAlloc []int64, pwAlloc []int64) {
	r := mustGetRound(roundID)
	if len(r.Proposals) == 0 || r.MatchingPool == 0 {
		return make([]int64, len(r.Proposals)), make([]int64, len(r.Proposals))
	}
	matrix, _ := buildContributionMatrix(r)
	stdAlloc = qfmath.StandardQF(matrix, r.MatchingPool)
	if r.PenaltyCoeff > 0 {
		pwAlloc = qfmath.PairwiseQF(matrix, r.MatchingPool, r.PenaltyCoeff)
	} else {
		pwAlloc = stdAlloc
	}
	return stdAlloc, pwAlloc
}

// FinalizeRound locks the round's matching distribution via qfmath.PairwiseQF
// (or qfmath.StandardQF) and credits every proposal's Milestone Escrow.
//
// Callable by the round Sponsor at any time, or permissionlessly by anyone once
// runtime.ChainHeight() >= r.EndHeight (when durationBlocks > 0).
// If no contributions were made, the matching pool is refunded to the Sponsor.
func FinalizeRound(cur realm, roundID int) {
	r := mustGetRound(roundID)
	if r.Status != RoundOpen {
		panic("quorumcraft: round is already finalized")
	}

	caller := cur.Previous().Address()
	nowHeight := runtime.ChainHeight()
	if caller != r.Sponsor {
		if r.EndHeight == 0 || nowHeight < r.EndHeight {
			panic("quorumcraft: only sponsor can finalize before round end height")
		}
	}

	r.Status = RoundFinalized
	r.FinalizedAt = nowHeight

	// Refund matching pool cleanly if no funded proposals exist.
	if len(r.Proposals) == 0 || r.DirectTotal == 0 {
		refund := r.MatchingPool
		r.MatchingPool = 0
		if refund > 0 {
			totalEscrowed -= refund
			totalRefunded += refund
			b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
			b.SendCoins(cur.Address(), r.Sponsor, chain.NewCoins(chain.NewCoin(ugnotDenom, refund)))
		}
		chain.Emit(
			"RoundFinalized",
			"roundId", strconv.Itoa(roundID),
			"mode", r.Mode.String(),
			"refundedPool", strconv.FormatInt(refund, 10),
		)
		return
	}

	matrix, _ := buildContributionMatrix(r)
	stdAlloc := qfmath.StandardQF(matrix, r.MatchingPool)
	finalAlloc := stdAlloc
	if r.Mode == ModePairwiseQF {
		finalAlloc = qfmath.PairwiseQF(matrix, r.MatchingPool, r.PenaltyCoeff)
	}

	for i, p := range r.Proposals {
		p.StandardQFMatched = stdAlloc[i]
		p.MatchedGrant = finalAlloc[i]
	}

	chain.Emit(
		"RoundFinalized",
		"roundId", strconv.Itoa(roundID),
		"mode", r.Mode.String(),
		"matchingPool", strconv.FormatInt(r.MatchingPool, 10),
		"directTotal", strconv.FormatInt(r.DirectTotal, 10),
	)
}

// SubmitMilestoneProof allows the proposal recipient to submit deliverable proof
// (URI + commit hash) for a pending milestone once the round is finalized.
func SubmitMilestoneProof(
	cur realm,
	roundID int,
	proposalID int,
	milestoneIdx int,
	proofURI string,
	commitHash string,
) {
	r := mustGetRound(roundID)
	if r.Status != RoundFinalized {
		panic("quorumcraft: round must be finalized before submitting milestone proof")
	}
	p := mustGetProposal(r, proposalID)
	caller := cur.Previous().Address()
	if caller != p.Recipient {
		panic("quorumcraft: only proposal recipient can submit milestone proof")
	}
	if p.TotalGrant() <= 0 {
		panic("quorumcraft: proposal has zero funded escrow")
	}
	m := mustGetMilestone(p, milestoneIdx)
	if m.Status != MilestonePending {
		panic("quorumcraft: milestone is not in PENDING state")
	}

	proofURI = strings.TrimSpace(proofURI)
	commitHash = strings.TrimSpace(commitHash)
	if proofURI == "" || len(proofURI) > 300 {
		panic("quorumcraft: invalid proofURI")
	}
	if commitHash == "" || len(commitHash) > 100 {
		panic("quorumcraft: invalid commitHash")
	}

	m.ProofURI = proofURI
	m.CommitHash = commitHash
	m.SubmittedAt = runtime.ChainHeight()
	m.Status = MilestoneSubmitted

	chain.Emit(
		"MilestoneProofSubmitted",
		"roundId", strconv.Itoa(roundID),
		"proposalId", strconv.Itoa(proposalID),
		"milestoneIdx", strconv.Itoa(milestoneIdx),
		"commitHash", commitHash,
	)
}

// isEligibleAttestor checks whether addr is a round reviewer, round sponsor, or
// direct contributor to proposal p (and NOT the proposal recipient).
func isEligibleAttestor(r *Round, p *Proposal, addr address) bool {
	if addr == p.Recipient {
		return false
	}
	key := addr.String()
	if r.Reviewers.Has(key) {
		return true
	}
	if p.DonorContribs.Has(key) {
		return true
	}
	return false
}

// EligibleAttestorCount counts the unique eligible attestors (reviewers U donors \ {recipient}).
func EligibleAttestorCount(r *Round, p *Proposal) int {
	recKey := p.Recipient.String()
	seen := avl.NewTree()
	r.Reviewers.Iterate("", "", func(key string, _ any) bool {
		if key != recKey {
			seen.Set(key, true)
		}
		return false
	})
	p.DonorContribs.Iterate("", "", func(key string, _ any) bool {
		if key != recKey {
			seen.Set(key, true)
		}
		return false
	})
	return seen.Size()
}

// RequiredQuorum computes ceil(eligibleCount * QuorumBps / 10000), minimum 1.
func RequiredQuorum(r *Round, p *Proposal) int {
	eligible := EligibleAttestorCount(r, p)
	if eligible <= 0 {
		return 1
	}
	req := int((int64(eligible)*r.QuorumBps + bpsFull - 1) / bpsFull)
	if req < 1 {
		req = 1
	}
	return req
}

// AttestMilestone records an approval vote from an eligible reviewer/sponsor/donor
// for a submitted milestone proof.
func AttestMilestone(cur realm, roundID int, proposalID int, milestoneIdx int) {
	r := mustGetRound(roundID)
	if r.Status != RoundFinalized {
		panic("quorumcraft: round is not finalized")
	}
	p := mustGetProposal(r, proposalID)
	m := mustGetMilestone(p, milestoneIdx)
	if m.Status != MilestoneSubmitted {
		panic("quorumcraft: milestone is not awaiting attestation")
	}

	caller := cur.Previous().Address()
	if !isEligibleAttestor(r, p, caller) {
		panic("quorumcraft: caller is not an eligible attestor for this proposal")
	}
	key := caller.String()
	if m.Approvals.Has(key) {
		panic("quorumcraft: caller has already attested this milestone")
	}

	m.Approvals.Set(key, true)
	m.ApprovalCount++

	chain.Emit(
		"MilestoneAttested",
		"roundId", strconv.Itoa(roundID),
		"proposalId", strconv.Itoa(proposalID),
		"milestoneIdx", strconv.Itoa(milestoneIdx),
		"attestor", key,
		"approvals", strconv.Itoa(m.ApprovalCount),
		"required", strconv.Itoa(RequiredQuorum(r, p)),
	)
}

// DisputeMilestone flags a submitted milestone proof as disputed, halting escrow
// release until the round sponsor resolves the dispute.
func DisputeMilestone(cur realm, roundID int, proposalID int, milestoneIdx int, reason string) {
	r := mustGetRound(roundID)
	if r.Status != RoundFinalized {
		panic("quorumcraft: round is not finalized")
	}
	p := mustGetProposal(r, proposalID)
	m := mustGetMilestone(p, milestoneIdx)
	if m.Status != MilestoneSubmitted {
		panic("quorumcraft: only SUBMITTED milestones can be disputed")
	}

	caller := cur.Previous().Address()
	if !isEligibleAttestor(r, p, caller) {
		panic("quorumcraft: caller is not eligible to dispute this milestone")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" || len(reason) > 500 {
		panic("quorumcraft: invalid dispute reason")
	}

	m.Status = MilestoneDisputed
	m.DisputeReason = reason
	m.DisputedBy = caller

	chain.Emit(
		"MilestoneDisputed",
		"roundId", strconv.Itoa(roundID),
		"proposalId", strconv.Itoa(proposalID),
		"milestoneIdx", strconv.Itoa(milestoneIdx),
		"disputedBy", caller.String(),
	)
}

// ProposalTrancheAmount returns the exact ugnot payout for milestone idx,
// assigning any integer division dust to the final milestone so all tranches
// sum strictly to proposal.TotalGrant().
func ProposalTrancheAmount(p *Proposal, idx int) int64 {
	total := p.TotalGrant()
	if total <= 0 || idx < 0 || idx >= len(p.Milestones) {
		return 0
	}
	var allocated int64
	lastIdx := len(p.Milestones) - 1
	for i := 0; i <= lastIdx; i++ {
		if i == lastIdx {
			if idx == i {
				return total - allocated
			}
			break
		}
		tranche := (total * p.Milestones[i].Bps) / bpsFull
		if idx == i {
			return tranche
		}
		allocated += tranche
	}
	return 0
}

// ReleaseMilestone atomically disburses a milestone's escrowed ugnot tranche to
// the proposal recipient once quorum approvals are met and no dispute is active.
func ReleaseMilestone(cur realm, roundID int, proposalID int, milestoneIdx int) int64 {
	r := mustGetRound(roundID)
	if r.Status != RoundFinalized {
		panic("quorumcraft: round is not finalized")
	}
	p := mustGetProposal(r, proposalID)
	m := mustGetMilestone(p, milestoneIdx)
	if m.Status != MilestoneSubmitted {
		panic("quorumcraft: milestone is not eligible for release")
	}

	req := RequiredQuorum(r, p)
	if m.ApprovalCount < req {
		panic("quorumcraft: milestone has not reached attestation quorum")
	}

	payout := ProposalTrancheAmount(p, milestoneIdx)
	if payout <= 0 {
		panic("quorumcraft: zero tranche payout")
	}

	// Checks-Effects-Interactions: update ledger before sending coins.
	m.Status = MilestoneReleased
	m.ReleasedAmount = payout
	p.EscrowReleased += payout
	totalEscrowed -= payout
	totalReleased += payout

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), p.Recipient, chain.NewCoins(chain.NewCoin(ugnotDenom, payout)))

	chain.Emit(
		"MilestoneReleased",
		"roundId", strconv.Itoa(roundID),
		"proposalId", strconv.Itoa(proposalID),
		"milestoneIdx", strconv.Itoa(milestoneIdx),
		"recipient", p.Recipient.String(),
		"amount", strconv.FormatInt(payout, 10),
	)
	return payout
}

// ResolveDispute allows the round sponsor to resolve a DISPUTED milestone by
// either releasing the tranche to the recipient (releaseToRecipient=true) or
// slashing/refunding that tranche back to the round sponsor (releaseToRecipient=false).
func ResolveDispute(
	cur realm,
	roundID int,
	proposalID int,
	milestoneIdx int,
	releaseToRecipient bool,
) int64 {
	r := mustGetRound(roundID)
	caller := cur.Previous().Address()
	if caller != r.Sponsor {
		panic("quorumcraft: only round sponsor can resolve disputes")
	}
	p := mustGetProposal(r, proposalID)
	m := mustGetMilestone(p, milestoneIdx)
	if m.Status != MilestoneDisputed {
		panic("quorumcraft: milestone is not disputed")
	}

	tranche := ProposalTrancheAmount(p, milestoneIdx)
	if tranche <= 0 {
		panic("quorumcraft: zero tranche amount")
	}

	var dest address
	var outcome string
	if releaseToRecipient {
		m.Status = MilestoneReleased
		m.ReleasedAmount = tranche
		p.EscrowReleased += tranche
		totalEscrowed -= tranche
		totalReleased += tranche
		dest = p.Recipient
		outcome = "RELEASED"
	} else {
		m.Status = MilestoneRefunded
		p.EscrowRefunded += tranche
		totalEscrowed -= tranche
		totalRefunded += tranche
		dest = r.Sponsor
		outcome = "REFUNDED"
	}

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), dest, chain.NewCoins(chain.NewCoin(ugnotDenom, tranche)))

	chain.Emit(
		"DisputeResolved",
		"roundId", strconv.Itoa(roundID),
		"proposalId", strconv.Itoa(proposalID),
		"milestoneIdx", strconv.Itoa(milestoneIdx),
		"outcome", outcome,
		"destination", dest.String(),
		"amount", strconv.FormatInt(tranche, 10),
	)
	return tranche
}

// GetProtocolStats returns aggregate escrow & round metrics.
func GetProtocolStats() ProtocolStats {
	stats := ProtocolStats{
		RoundCount:    len(rounds),
		TotalEscrowed: totalEscrowed,
		TotalReleased: totalReleased,
		TotalRefunded: totalRefunded,
	}
	for _, r := range rounds {
		if r.Status == RoundOpen {
			stats.OpenRounds++
		}
		stats.ProposalCount += len(r.Proposals)
	}
	return stats
}

// GetRound returns the round struct for read-only inspection.
func GetRound(roundID int) *Round {
	return mustGetRound(roundID)
}

func mustGetRound(roundID int) *Round {
	if roundID < 1 || roundID > len(rounds) {
		panic("quorumcraft: round not found")
	}
	return rounds[roundID-1]
}

func mustGetProposal(r *Round, proposalID int) *Proposal {
	if proposalID < 1 || proposalID > len(r.Proposals) {
		panic("quorumcraft: proposal not found")
	}
	return r.Proposals[proposalID-1]
}

func mustGetMilestone(p *Proposal, milestoneIdx int) *Milestone {
	if milestoneIdx < 0 || milestoneIdx >= len(p.Milestones) {
		panic("quorumcraft: milestone index out of range")
	}
	return p.Milestones[milestoneIdx]
}

package quorumcraft

import (
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/svg/v0"
	"gno.land/p/nt/ufmt/v0"
)

func truncLabel(s string, maxLen int) string {
	s = sanitize.HTMLEscape(s)
	if len(s) <= maxLen {
		return s
	}
	if maxLen <= 3 {
		return s[:maxLen]
	}
	return s[:maxLen-3] + "..."
}

func formatGnot(ugnot int64) string {
	neg := ""
	if ugnot < 0 {
		neg = "-"
		ugnot = -ugnot
	}
	whole := ugnot / 1_000_000
	frac := (ugnot % 1_000_000) / 10_000 // 2 decimal places
	return ufmt.Sprintf("%s%d.%02d GNOT", neg, whole, frac)
}

// buildRoundChartCanvas generates a native on-chain SVG horizontal bar chart
// comparing Direct Community Donations vs Pairwise-QF Matched Grants per proposal.
func buildRoundChartCanvas(r *Round, matched []int64) *svg.Canvas {
	const (
		width    = 760
		rowH     = 54
		headerH  = 64
		footerH  = 34
		labelX   = 20
		barX     = 220
		maxBarW  = 390
		valueX   = 622
	)
	n := len(r.Proposals)
	if n == 0 {
		c := svg.NewCanvas(width, 110).WithViewBox(0, 0, width, 110)
		c.Append(
			&svg.Rectangle{X: 0, Y: 0, Width: width, Height: 110, RX: 10, RY: 10, Fill: "#0B0D11"},
			&svg.Text{X: 24, Y: 62, Text: "No proposals submitted yet in this round.", Fill: "#94A3B8", Attr: svg.BaseAttrs{Style: "font-family:monospace;font-size:13px"}},
		)
		return c
	}

	// Determine max combined bar value for linear scaling.
	var maxVal int64 = 1
	for i, p := range r.Proposals {
		m := int64(0)
		if i < len(matched) {
			m = matched[i]
		}
		if p.DirectTotal+m > maxVal {
			maxVal = p.DirectTotal + m
		}
	}

	height := headerH + n*rowH + footerH
	c := svg.NewCanvas(width, height).WithViewBox(0, 0, width, height)

	// Dark slate obsidian background + subtle frame border
	c.Append(&svg.Rectangle{
		X: 0, Y: 0, Width: width, Height: height, RX: 12, RY: 12, Fill: "#0B0D11",
		Attr: svg.BaseAttrs{Stroke: "#222938", StrokeWidth: "1"},
	})

	// Title + Legend
	modeLabel := r.Mode.String()
	c.Append(&svg.Text{
		X: 20, Y: 28,
		Text: ufmt.Sprintf("Round #%d — Direct vs %s Matched Grants", r.ID, modeLabel),
		Fill: "#F8FAFC",
		Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:14px;font-weight:700"},
	})
	// Legend swatches
	c.Append(
		&svg.Rectangle{X: 20, Y: 40, Width: 10, Height: 10, RX: 2, RY: 2, Fill: "#38BDF8"},
		&svg.Text{X: 36, Y: 49, Text: "Direct Donations", Fill: "#94A3B8", Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:11px"}},
		&svg.Rectangle{X: 155, Y: 40, Width: 10, Height: 10, RX: 2, RY: 2, Fill: "#10B981"},
		&svg.Text{X: 171, Y: 49, Text: modeLabel + " Matched Grant", Fill: "#94A3B8", Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:11px"}},
	)

	for i, p := range r.Proposals {
		y := headerH + i*rowH
		m := int64(0)
		if i < len(matched) {
			m = matched[i]
		}
		total := p.DirectTotal + m

		// Alternating subtle row card
		rowBg := "#131720"
		if i%2 == 1 {
			rowBg = "#10141C"
		}
		c.Append(&svg.Rectangle{X: 12, Y: y, Width: width - 24, Height: rowH - 8, RX: 6, RY: 6, Fill: rowBg})

		// Proposal label
		c.Append(&svg.Text{
			X: labelX, Y: y + 20,
			Text: ufmt.Sprintf("#%d %s", p.ID, truncLabel(p.Title, 22)),
			Fill: "#E2E8F0",
			Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:12px;font-weight:600"},
		})
		c.Append(&svg.Text{
			X: labelX, Y: y + 36,
			Text: ufmt.Sprintf("%d donors", p.DonorContribs.Size()),
			Fill: "#64748B",
			Attr: svg.BaseAttrs{Style: "font-family:monospace;font-size:10px"},
		})

		// Track background
		c.Append(&svg.Rectangle{X: barX, Y: y + 12, Width: maxBarW, Height: 20, RX: 4, RY: 4, Fill: "#1E2534"})

		// Direct segment + Matched segment
		directW := int((p.DirectTotal * int64(maxBarW)) / maxVal)
		matchW := int((m * int64(maxBarW)) / maxVal)
		if p.DirectTotal > 0 && directW < 4 {
			directW = 4
		}
		if m > 0 && matchW < 4 {
			matchW = 4
		}
		if directW+matchW > maxBarW {
			matchW = maxBarW - directW
			if matchW < 0 {
				matchW = 0
			}
		}

		if directW > 0 {
			c.Append(&svg.Rectangle{X: barX, Y: y + 12, Width: directW, Height: 20, RX: 3, RY: 3, Fill: "#38BDF8"})
		}
		if matchW > 0 {
			c.Append(&svg.Rectangle{X: barX + directW, Y: y + 12, Width: matchW, Height: 20, RX: 3, RY: 3, Fill: "#10B981"})
		}

		// Right-side total figure
		c.Append(&svg.Text{
			X: valueX, Y: y + 20,
			Text: formatGnot(total),
			Fill: "#F8FAFC",
			Attr: svg.BaseAttrs{Style: "font-family:monospace;font-size:12px;font-weight:700"},
		})
		c.Append(&svg.Text{
			X: valueX, Y: y + 36,
			Text: ufmt.Sprintf("+%s QF", formatGnot(m)),
			Fill: "#10B981",
			Attr: svg.BaseAttrs{Style: "font-family:monospace;font-size:10px"},
		})
	}

	c.Append(&svg.Text{
		X: 20, Y: height - 12,
		Text: "Deterministic on-chain SVG rendered by QuorumCraft (gno.land/p/nt/svg/v0 + p/qfmath)",
		Fill: "#64748B",
		Attr: svg.BaseAttrs{Style: "font-family:monospace;font-size:10px"},
	})
	return c
}

// buildEscrowBarCanvas generates an on-chain SVG Milestone Escrow Progress Bar
// showing each tranche's weight and live status (Released / Submitted / Disputed / Pending).
func buildEscrowBarCanvas(r *Round, p *Proposal) *svg.Canvas {
	const (
		width  = 760
		height = 132
		barX   = 20
		barY   = 52
		barW   = 720
		barH   = 28
	)
	c := svg.NewCanvas(width, height).WithViewBox(0, 0, width, height)
	c.Append(&svg.Rectangle{
		X: 0, Y: 0, Width: width, Height: height, RX: 12, RY: 12, Fill: "#0B0D11",
		Attr: svg.BaseAttrs{Stroke: "#222938", StrokeWidth: "1"},
	})

	c.Append(&svg.Text{
		X: 20, Y: 28,
		Text: ufmt.Sprintf("Milestone Escrow — %s (%s Total)", truncLabel(p.Title, 38), formatGnot(p.TotalGrant())),
		Fill: "#F8FAFC",
		Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:14px;font-weight:700"},
	})

	// Track
	c.Append(&svg.Rectangle{X: barX, Y: barY, Width: barW, Height: barH, RX: 6, RY: 6, Fill: "#1E2534"})

	curX := barX
	for i, m := range p.Milestones {
		segW := int((m.Bps * int64(barW)) / bpsFull)
		if i == len(p.Milestones)-1 {
			segW = (barX + barW) - curX
		}
		if segW < 2 {
			segW = 2
		}

		fill := "#334155" // PENDING
		switch m.Status {
		case MilestoneReleased:
			fill = "#10B981" // Emerald
		case MilestoneSubmitted:
			fill = "#F59E0B" // Amber awaiting quorum
		case MilestoneDisputed:
			fill = "#EF4444" // Crimson
		case MilestoneRefunded:
			fill = "#6366F1" // Indigo refunded
		}

		// Leave 2px crisp gap between tranches
		drawW := segW
		if i < len(p.Milestones)-1 && drawW > 4 {
			drawW -= 2
		}
		c.Append(&svg.Rectangle{
			X: curX, Y: barY, Width: drawW, Height: barH, RX: 4, RY: 4, Fill: fill,
		})

		pct := m.Bps / 100
		label := ufmt.Sprintf("M%d (%d%%)", i+1, pct)
		if drawW >= 68 {
			c.Append(&svg.Text{
				X: curX + 8, Y: barY + 18,
				Text: label,
				Fill: "#FFFFFF",
				Attr: svg.BaseAttrs{Style: "font-family:monospace;font-size:11px;font-weight:700"},
			})
		}
		curX += segW
	}

	// Status legend row
	c.Append(
		&svg.Rectangle{X: 20, Y: 96, Width: 10, Height: 10, RX: 2, RY: 2, Fill: "#10B981"},
		&svg.Text{X: 36, Y: 105, Text: "Released", Fill: "#94A3B8", Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:11px"}},
		&svg.Rectangle{X: 112, Y: 96, Width: 10, Height: 10, RX: 2, RY: 2, Fill: "#F59E0B"},
		&svg.Text{X: 128, Y: 105, Text: "Proof Submitted / Quorum", Fill: "#94A3B8", Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:11px"}},
		&svg.Rectangle{X: 288, Y: 96, Width: 10, Height: 10, RX: 2, RY: 2, Fill: "#334155"},
		&svg.Text{X: 304, Y: 105, Text: "Pending", Fill: "#94A3B8", Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:11px"}},
		&svg.Rectangle{X: 374, Y: 96, Width: 10, Height: 10, RX: 2, RY: 2, Fill: "#EF4444"},
		&svg.Text{X: 390, Y: 105, Text: "Disputed", Fill: "#94A3B8", Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:11px"}},
		&svg.Rectangle{X: 464, Y: 96, Width: 10, Height: 10, RX: 2, RY: 2, Fill: "#6366F1"},
		&svg.Text{X: 480, Y: 105, Text: "Refunded", Fill: "#94A3B8", Attr: svg.BaseAttrs{Style: "font-family:sans-serif;font-size:11px"}},
		&svg.Text{
			X: 570, Y: 105,
			Text: ufmt.Sprintf("Quorum: %d.%02d%%", r.QuorumBps/100, r.QuorumBps%100),
			Fill: "#38BDF8",
			Attr: svg.BaseAttrs{Style: "font-family:monospace;font-size:11px;font-weight:700"},
		},
	)
	return c
}

// RenderRoundChartSVG returns the raw <svg> markup for a round's QF bar chart.
func RenderRoundChartSVG(roundID int) string {
	r := mustGetRound(roundID)
	stdAlloc, pwAlloc := PreviewRoundMatching(roundID)
	matched := stdAlloc
	if r.Mode == ModePairwiseQF {
		matched = pwAlloc
	}
	if r.Status == RoundFinalized {
		matched = make([]int64, len(r.Proposals))
		for i, p := range r.Proposals {
			matched[i] = p.MatchedGrant
		}
	}
	return buildRoundChartCanvas(r, matched).String()
}

// RenderEscrowSVG returns the raw <svg> markup for a proposal's milestone escrow progress bar.
func RenderEscrowSVG(roundID, proposalID int) string {
	r := mustGetRound(roundID)
	p := mustGetProposal(r, proposalID)
	return buildEscrowBarCanvas(r, p).String()
}

package quorumcraft

import "gno.land/p/nt/avl/v0"

const (
	realmPkgPath = "gno.land/r/g1v4wuqfzakzpty87t0njkcjtx8yte4v5d8v69tj/quorumcraft"
	ugnotDenom   = "ugnot"
	bpsFull      = int64(10_000)
	minMilestones = 2
	maxMilestones = 4
)

// QFMode determines which matching algorithm is used at round finalization.
type QFMode int

const (
	ModeStandardQF QFMode = 0
	ModePairwiseQF QFMode = 1
)

func (m QFMode) String() string {
	switch m {
	case ModeStandardQF:
		return "StandardQF"
	case ModePairwiseQF:
		return "PairwiseQF"
	default:
		return "Unknown"
	}
}

// RoundStatus tracks the lifecycle of a quadratic funding round.
type RoundStatus int

const (
	RoundOpen      RoundStatus = 0
	RoundFinalized RoundStatus = 1
)

func (s RoundStatus) String() string {
	switch s {
	case RoundOpen:
		return "OPEN"
	case RoundFinalized:
		return "FINALIZED"
	default:
		return "UNKNOWN"
	}
}

// MilestoneStatus tracks the escrow state of an individual grant tranche.
type MilestoneStatus int

const (
	MilestonePending   MilestoneStatus = 0
	MilestoneSubmitted MilestoneStatus = 1
	MilestoneReleased  MilestoneStatus = 2
	MilestoneDisputed  MilestoneStatus = 3
	MilestoneRefunded  MilestoneStatus = 4
)

func (s MilestoneStatus) String() string {
	switch s {
	case MilestonePending:
		return "PENDING"
	case MilestoneSubmitted:
		return "SUBMITTED"
	case MilestoneReleased:
		return "RELEASED"
	case MilestoneDisputed:
		return "DISPUTED"
	case MilestoneRefunded:
		return "REFUNDED"
	default:
		return "UNKNOWN"
	}
}

// Milestone represents a single deliverable tranche backed by escrowed ugnot.
type Milestone struct {
	Index          int
	Title          string
	Bps            int64 // share of proposal's total grant in basis points (sum == 10000)
	Status         MilestoneStatus
	ProofURI       string
	CommitHash     string
	SubmittedAt    int64
	Approvals      *avl.Tree // address string -> bool
	ApprovalCount  int
	DisputeReason  string
	DisputedBy     address
	ReleasedAmount int64
}

// Proposal represents a builder grant proposal with structured milestones.
type Proposal struct {
	ID                int
	RoundID           int
	Recipient         address
	Title             string
	RepoURL           string
	Summary           string
	DirectTotal       int64
	MatchedGrant      int64
	StandardQFMatched int64
	EscrowReleased    int64
	EscrowRefunded    int64
	DonorContribs     *avl.Tree // donor address string -> int64 ugnot
	Milestones        []*Milestone
	CreatedAt         int64
}

// TotalGrant returns the proposal's combined direct + matched ugnot grant.
func (p *Proposal) TotalGrant() int64 {
	return p.DirectTotal + p.MatchedGrant
}

// RemainingEscrow returns unreleased, unrefunded ugnot still locked for this proposal.
func (p *Proposal) RemainingEscrow() int64 {
	rem := p.TotalGrant() - p.EscrowReleased - p.EscrowRefunded
	if rem < 0 {
		return 0
	}
	return rem
}

// Round represents a Pairwise or Standard Quadratic Funding round with on-chain escrow.
type Round struct {
	ID           int
	Sponsor      address
	Name         string
	Description  string
	Mode         QFMode
	PenaltyCoeff int64 // M in ugnot for PairwiseQF anti-collusion damping
	QuorumBps    int64 // required attestation quorum in basis points (1..10000)
	EndHeight    int64 // 0 = sponsor-finalized; >0 = anyone may finalize once ChainHeight >= EndHeight
	MatchingPool int64 // escrowed ugnot in the matching pool
	DirectTotal  int64 // sum of all direct community contributions
	Status       RoundStatus
	Reviewers    *avl.Tree // reviewer address string -> bool
	Donors       *avl.Tree // donor address string -> int64 total ugnot in this round
	Proposals    []*Proposal
	CreatedAt    int64
	FinalizedAt  int64
}

// ProtocolStats summarizes live protocol-wide escrow & activity metrics.
type ProtocolStats struct {
	RoundCount    int
	OpenRounds    int
	ProposalCount int
	TotalEscrowed int64
	TotalReleased int64
	TotalRefunded int64
}

