func TestValidate(t *testing.T) {
	if e := Validate(basePolicy()); e != "" {
		t.Errorf("base policy invalid: %s", e)
	}
	cases := map[string]func(p *Policy){
		"negative":    func(p *Policy) { p.DailyCap = -1 },
		"per > daily": func(p *Policy) { p.PerPayment = 3_000 },
		"dup name":    func(p *Policy) { p.Payees[1].Name = "bar" },
		"dup address": func(p *Policy) { p.Payees[1].Addr = bar },
		"bad name":    func(p *Policy) { p.Payees[0].Name = "Bar Tab!" },
		"empty name":  func(p *Policy) { p.Payees[0].Name = "" },
		"bad address": func(p *Policy) { p.Payees[0].Addr = address("g1notanaddress") },
		"too many": func(p *Policy) {
			for i := 0; i < MaxPayees; i++ {
				p.Payees = append(p.Payees, p.Payees[0])
			}
		},
	}
	for name, mut := range cases {
		p := basePolicy()
		mut(&p)
		if Validate(p) == "" {
			t.Errorf("Validate accepted %s", name)
		}
	}
}

func TestDayOf(t *testing.T) {
	if DayOf(0) != 0 || DayOf(Day-1) != 0 || DayOf(Day) != 1 || DayOf(-1) != -1 {
		t.Errorf("DayOf wrong: %d %d %d %d", DayOf(0), DayOf(Day-1), DayOf(Day), DayOf(-1))
	}
}

// Package bartab gives an AI agent a tab instead of a wallet.
//
// The owner opens a tab with ugnot and names the agent's address. The agent orders payments; every order runs through
// gno.land/p/g1n8s3sg4yegu8awzxl7e094vhtcxkw6a4lvxq44/spendpolicy and is allowed (paid at once), held for the owner, or refused. Every decision, refusals
// included, is written to the tab's on-chain ledger and shown on the realm's Render page. The owner can approve or reject
// holds, add payees (a new or changed payee address waits out a hold period first) and freeze the tab in one call.
//
// Banker discipline (see SECURITY.md): the realm mints a RealmSend banker only inside the function that pays, keeps it
// in a local variable, and never stores or passes it anywhere. A stored banker would bypass every check here.
package bartab

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	sp "gno.land/p/g1n8s3sg4yegu8awzxl7e094vhtcxkw6a4lvxq44/spendpolicy"
)

const (
	denom      = "ugnot"
	maxMemo    = 64
	maxIdemKey = 64
	maxTabs    = 1000
)

type Hold struct {
	ID      int
	To      address
	Payee   string
	Amount  int64
	Memo    string
	Reason  string
	Created int64
	Status  string // pending, paid, rejected, cancelled, refused:<reason>
}

type Entry struct {
	Seq      int
	Time     int64
	Height   int64
	Actor    address
	Payee    string // payee name at the time, if To was a payee
	Action   string // open, topup, order, approve, reject, payee, caps, freeze, close
	Amount   int64
	To       address
	Decision string
	Note     string
}

type Tab struct {
	ID     int
	Owner  address
	Agent  address
	Policy sp.Policy
	State  sp.State
	Holds  []*Hold
	Ledger []Entry
	Idem   map[string]string
	Closed bool
	Paid   int64 // total paid out to payees
	Served int   // orders paid
	CutOff int   // orders refused
	Held   int   // orders held
}

var (
	tabs []*Tab
)

// ---------- helpers

func now() int64 { return time.Now().Unix() }

func getTab(id int) *Tab {
	if id < 1 || id > len(tabs) {
		panic("no such tab")
	}
	return tabs[id-1]
}

func ownerTab(cur realm, id int) *Tab {
	t := getTab(id)
	if cur.Previous().Address() != t.Owner {
		panic("only the tab's owner can do this")
	}
	if t.Closed {
		panic("tab is closed")
	}
	return t
}

func (t *Tab) log(actor address, action string, amount int64, to address, decision, note string) {
	e := Entry{
		Seq: len(t.Ledger) + 1, Time: now(), Height: runtime.ChainHeight(), Actor: actor, Payee: payeeName(t, to),
		Action: action, Amount: amount, To: to, Decision: decision, Note: note,
	}
	t.Ledger = append(t.Ledger, e)
	chain.Emit("BarTab",
		"tab", strconv.Itoa(t.ID), "seq", strconv.Itoa(e.Seq), "action", action,
		"amount", strconv.FormatInt(amount, 10), "to", to.String(), "decision", decision, "note", note)
}

// received returns the ugnot the caller sent with this call. Only a direct user call (maketx call) is accepted, so the
// send envelope is the caller's own coins and not a balance some intermediate realm already held.
func received(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("call this directly with gnokey maketx call")
	}
	return unsafe.OriginSend().AmountOf(denom)
}

// pay is the only place coins leave the realm. The banker lives in this frame only.
func pay(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(denom, amount)))
}

func payeeName(t *Tab, to address) string {
	if p, ok := sp.FindPayee(t.Policy, to); ok {
		return p.Name
	}
	return ""
}

// ---------- owner functions

// OpenTab opens a tab funded with the ugnot sent along (-send). The caller becomes the owner; agent is the only address
// that may order from it. Caps are in ugnot; payeeHoldSecs is the wait before a new or changed payee address is usable;
// expiresUnix 0 means the tab never expires. Returns the tab id.
func OpenTab(cur realm, agent address, perPayment, dailyCap, payeeHoldSecs, expiresUnix int64) int {
	amount := received(cur)
	if amount <= 0 {
		panic("send ugnot to fund the tab")
	}
	if !agent.IsValid() {
		panic("invalid agent address")
	}
	owner := cur.Previous().Address()
	if agent == owner {
		panic("the agent must be a different address from the owner")
	}
	if len(tabs) >= maxTabs {
		panic("too many tabs")
	}
	p := sp.Policy{PerPayment: perPayment, DailyCap: dailyCap, PayeeHoldSecs: payeeHoldSecs, ExpiresAt: expiresUnix}
	if e := sp.Validate(p); e != "" {
		panic(e)
	}
	t := &Tab{ID: len(tabs) + 1, Owner: owner, Agent: agent, Policy: p, State: sp.State{Balance: amount}, Idem: map[string]string{}}
	tabs = append(tabs, t)
	t.log(owner, "open", amount, agent, "ok", "")
	return t.ID
}

// TopUp adds the ugnot sent along to a tab.
func TopUp(cur realm, tabID int) {
	t := ownerTab(cur, tabID)
	amount := received(cur)
	if amount <= 0 {
		panic("send ugnot to top up")
	}
	t.State.Balance += amount
	t.log(t.Owner, "topup", amount, "", "ok", "")
}

// SetPayee adds a payee or changes a payee's address. Either way the address is usable without a hold only after the
// tab's payee hold period. Setting the same address again keeps its current hold time.
func SetPayee(cur realm, tabID int, name string, to address) {
	t := ownerTab(cur, tabID)
	if e := sp.ValidName(name); e != "" {
		panic(e)
	}
	if !to.IsValid() {
		panic("invalid payee address")
	}
	usable := now() + t.Policy.PayeeHoldSecs
	for i, p := range t.Policy.Payees {
		if p.Name == name {
			if p.Addr == to {
				return
			}
			if _, taken := sp.FindPayee(t.Policy, to); taken {
				panic("address already belongs to another payee")
			}
			t.Policy.Payees[i] = sp.Payee{Name: name, Addr: to, UsableAt: usable}
			t.log(t.Owner, "payee", 0, to, "changed", name+" usable from "+when(usable))
			return
		}
	}
	next := t.Policy
	next.Payees = append(append([]sp.Payee{}, t.Policy.Payees...), sp.Payee{Name: name, Addr: to, UsableAt: usable})
	if e := sp.Validate(next); e != "" {
		panic(e)
	}
	t.Policy = next
	t.log(t.Owner, "payee", 0, to, "added", name+" usable from "+when(usable))
}

// RemovePayee removes a payee. Pending holds to that address are refused when approved.
func RemovePayee(cur realm, tabID int, name string) {
	t := ownerTab(cur, tabID)
	for i, p := range t.Policy.Payees {
		if p.Name == name {
			t.Policy.Payees = append(t.Policy.Payees[:i:i], t.Policy.Payees[i+1:]...)
			t.log(t.Owner, "payee", 0, p.Addr, "removed", name)
			return
		}
	}
	panic("no such payee")
}

// SetCaps changes the per-payment and daily caps.
func SetCaps(cur realm, tabID int, perPayment, dailyCap int64) {
	t := ownerTab(cur, tabID)
	next := t.Policy
	next.PerPayment, next.DailyCap = perPayment, dailyCap
	if e := sp.Validate(next); e != "" {
		panic(e)
	}
	t.Policy = next
	t.log(t.Owner, "caps", 0, "", "ok", strconv.FormatInt(perPayment, 10)+"/"+strconv.FormatInt(dailyCap, 10))
}

// Approve pays a held order. It re-checks the order against the tab as it is now: an approval lifts the soft limits
// (caps, payee hold) but never a hard one (frozen, expired, unknown payee, not enough balance).
func Approve(cur realm, tabID, holdID int) string {
	t := ownerTab(cur, tabID)
	h := pendingHold(t, holdID)
	d := sp.Check(t.Policy, t.State, sp.Request{To: h.To, Amount: h.Amount, Now: now(), OwnerApproved: true})
	if d.Kind != sp.Allow {
		h.Status = "refused:" + d.Reason
		t.log(t.Owner, "approve", h.Amount, h.To, d.String(), "hold "+strconv.Itoa(h.ID))
		return d.String()
	}
	t.State = sp.Record(t.State, h.Amount, now())
	h.Status = "paid"
	t.Paid += h.Amount
	t.Served++
	pay(cur, h.To, h.Amount)
	t.log(t.Owner, "approve", h.Amount, h.To, "allow", "hold "+strconv.Itoa(h.ID))
	return "allow"
}

// Reject drops a held order.
func Reject(cur realm, tabID, holdID int) {
	t := ownerTab(cur, tabID)
	h := pendingHold(t, holdID)
	h.Status = "rejected"
	t.log(t.Owner, "reject", h.Amount, h.To, "rejected", "hold "+strconv.Itoa(h.ID))
}

func pendingHold(t *Tab, holdID int) *Hold {
	if holdID < 1 || holdID > len(t.Holds) {
		panic("no such hold")
	}
	h := t.Holds[holdID-1]
	if h.Status != "pending" {
		panic("hold is " + h.Status)
	}
	return h
}

// Freeze is the kill switch: every later order is refused and every pending hold is cancelled, in this one call.
// Unfreeze lifts it.
func Freeze(cur realm, tabID int) {
	t := ownerTab(cur, tabID)
	if t.State.Frozen {
		return
	}
	t.State.Frozen = true
	n := 0
	for _, h := range t.Holds {
		if h.Status == "pending" {
			h.Status = "cancelled"
			n++
		}
	}
	t.log(t.Owner, "freeze", 0, "", "frozen", plural(n, "pending order")+" cancelled")
}

func Unfreeze(cur realm, tabID int) {
	t := ownerTab(cur, tabID)
	if !t.State.Frozen {
		return
	}
	t.State.Frozen = false
	t.log(t.Owner, "unfreeze", 0, "", "ok", "")
}

// CloseTab refunds what is left to the owner and closes the tab for good.
func CloseTab(cur realm, tabID int) {
	t := ownerTab(cur, tabID)
	left := t.State.Balance
	t.State.Balance = 0
	t.State.Frozen = true
	t.Closed = true
	for _, h := range t.Holds {
		if h.Status == "pending" {
			h.Status = "cancelled"
		}
	}
	if left > 0 {
		pay(cur, t.Owner, left)
	}
	t.log(t.Owner, "close", left, t.Owner, "closed", "refund")
}

// ---------- agent function

// Order asks the tab to pay `amount` ugnot to `to`. Only the tab's agent may call it. It never panics on a policy
// outcome, so refusals are recorded on-chain too. idemKey (optional) makes retries safe: the same key on the same tab
// returns the first answer and never pays twice. Returns "allow", "hold:<id>:<reason>" or "deny:<reason>".
func Order(cur realm, tabID int, to address, amount int64, memo, idemKey string) string {
	t := getTab(tabID)
	caller := cur.Previous().Address()
	if caller != t.Agent {
		panic("only the tab's agent can order")
	}
	if len(memo) > maxMemo || len(idemKey) > maxIdemKey {
		panic("memo or idemKey too long")
	}
	if idemKey != "" {
		if prev, ok := t.Idem[idemKey]; ok {
			return prev
		}
	}
	if t.Closed {
		return t.remember(idemKey, "deny:closed")
	}
	sessAddr, sessExp, _, isSession := runtime.GetSessionInfo()
	note := memo
	if isSession {
		note = memo + " [session " + sessAddr.String() + "]"
	}
	r := sp.Request{To: to, Amount: amount, Now: now(), SessionExpiresAt: sessExp}
	d := sp.Check(t.Policy, t.State, r)
	switch d.Kind {
	case sp.Allow:
		t.State = sp.Record(t.State, amount, r.Now)
		t.Paid += amount
		t.Served++
		pay(cur, to, amount)
		t.log(caller, "order", amount, to, "allow", note)
		return t.remember(idemKey, "allow")
	case sp.Hold:
		h := &Hold{ID: len(t.Holds) + 1, To: to, Payee: payeeName(t, to), Amount: amount, Memo: memo, Reason: d.Reason, Created: r.Now, Status: "pending"}
		t.Holds = append(t.Holds, h)
		t.Held++
		t.log(caller, "order", amount, to, d.String(), note)
		return t.remember(idemKey, "hold:"+strconv.Itoa(h.ID)+":"+d.Reason)
	}
	t.CutOff++
	t.log(caller, "order", amount, to, d.String(), note)
	return t.remember(idemKey, d.String())
}

func (t *Tab) remember(idemKey, answer string) string {
	if idemKey != "" {
		t.Idem[idemKey] = answer
	}
	return answer
}

// ---------- reads

// TabCount returns the number of tabs opened.
func TabCount() int { return len(tabs) }

// Balance returns a tab's balance in ugnot.
func Balance(tabID int) int64 { return getTab(tabID).State.Balance }

// LastDecision returns the newest ledger line of a tab as "action decision amount".
func LastDecision(tabID int) string {
	t := getTab(tabID)
	if len(t.Ledger) == 0 {
		return ""
	}
	e := t.Ledger[len(t.Ledger)-1]
	return e.Action + " " + e.Decision + " " + strconv.FormatInt(e.Amount, 10)
}

func plural(n int, word string) string {
	if n == 1 {
		return "1 " + word
	}
	return strconv.Itoa(n) + " " + word + "s"
}

package bartab

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
)

var (
	selfPath string       // gno.land/r/<ns>/bartab, read at deploy
	selfURL  string       // /r/<ns>/bartab
	self     txlink.Realm // action links always point at this realm, whoever renders
)

func init() {
	selfPath = unsafe.CurrentRealm().PkgPath()
	selfURL = strings.TrimPrefix(selfPath, "gno.land")
	self = txlink.Realm(selfPath)
}

// Render: "" = the tavern front page; "tab/<id>" = one tab.
func Render(path string) string {
	if strings.HasPrefix(path, "tab/") {
		id, err := strconv.Atoi(strings.TrimPrefix(path, "tab/"))
		if err != nil || id < 1 || id > len(tabs) {
			return "# No such tab\n\n[Back to the bar](" + selfURL + ")\n"
		}
		return renderTab(tabs[id-1])
	}
	return renderHome()
}

func renderHome() string {
	var served, cut, held, open int
	var paid int64
	for _, t := range tabs {
		served += t.Served
		cut += t.CutOff
		held += t.Held
		paid += t.Paid
		if !t.Closed {
			open++
		}
	}
	var b strings.Builder
	b.WriteString("# Bar Tab\n\n")
	b.WriteString("**Give your AI agent a tab, not your wallet.**\n\n")
	b.WriteString("You open a tab with GNOT and name your agent's address. The agent orders payments. The barkeep (this realm) checks every order against your rules before a coin moves:\n\n")
	b.WriteString("- a cap per payment and a cap per day; over either, the order waits for you;\n")
	b.WriteString("- an allowlist of payees; anyone else is refused;\n")
	b.WriteString("- a hold on new or changed payee addresses, the classic invoice-fraud move;\n")
	b.WriteString("- an expiry, and the session key's own expiry;\n")
	b.WriteString("- **Freeze**: one call and the agent is cut off, pending orders cancelled.\n\n")
	b.WriteString("Every decision, refusals included, is written to the tab's ledger below.\n\n")
	b.WriteString("| Tabs open | Orders served | Orders held | Orders cut off | Paid out |\n|---:|---:|---:|---:|---:|\n")
	b.WriteString("| " + strconv.Itoa(open) + " | " + strconv.Itoa(served) + " | " + strconv.Itoa(held) + " | " + strconv.Itoa(cut) + " | " + gnot(paid) + " |\n\n")
	if len(tabs) > 0 {
		b.WriteString("## Tabs\n\n")
		for i := len(tabs) - 1; i >= 0 && i >= len(tabs)-20; i-- {
			t := tabs[i]
			b.WriteString("- [Tab " + strconv.Itoa(t.ID) + "](" + selfURL + ":tab/" + strconv.Itoa(t.ID) + "): " + status(t) + ", balance " + gnot(t.State.Balance) + "\n")
		}
		b.WriteString("\n")
	}
	b.WriteString("## Open a tab\n\n[OpenTab](" + self.Call("OpenTab") + "): agent address, per-payment cap, daily cap, payee hold (seconds), expiry (unix, 0 = never); send the GNOT to put on the tab.\n")
	return b.String()
}

func renderTab(t *Tab) string {
	id := strconv.Itoa(t.ID)
	var b strings.Builder
	b.WriteString("# Tab " + id + ": " + status(t) + "\n\n")
	b.WriteString("[Back to the bar](" + selfURL + ")\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Owner | `" + t.Owner.String() + "` |\n")
	b.WriteString("| Agent | `" + t.Agent.String() + "` |\n")
	b.WriteString("| Balance | " + gnot(t.State.Balance) + " |\n")
	spent := int64(0)
	if t.State.SpentDay == time.Now().Unix()/86400 {
		spent = t.State.SpentToday
	}
	b.WriteString("| Spent today (UTC) | " + gnot(spent) + " of " + gnot(t.Policy.DailyCap) + " " + bar(spent, t.Policy.DailyCap) + " |\n")
	b.WriteString("| Per payment | up to " + gnot(t.Policy.PerPayment) + " without approval |\n")
	b.WriteString("| Payee hold | " + strconv.FormatInt(t.Policy.PayeeHoldSecs, 10) + " s |\n")
	exp := "never"
	if t.Policy.ExpiresAt > 0 {
		exp = when(t.Policy.ExpiresAt)
	}
	b.WriteString("| Expires | " + exp + " |\n\n")
	if !t.Closed {
		if t.State.Frozen {
			b.WriteString("**Frozen.** [Unfreeze](" + self.Call("Unfreeze", "tabID", id) + ")\n\n")
		} else {
			b.WriteString("[**Freeze this tab**](" + self.Call("Freeze", "tabID", id) + ") · ")
			b.WriteString("[Top up](" + self.Call("TopUp", "tabID", id) + ") · ")
			b.WriteString("[Add or change a payee](" + self.Call("SetPayee", "tabID", id) + ") · ")
			b.WriteString("[Close and refund](" + self.Call("CloseTab", "tabID", id) + ")\n\n")
		}
	}
	b.WriteString("## Payees\n\n")
	if len(t.Policy.Payees) == 0 {
		b.WriteString("None yet: every order is refused until you add one.\n\n")
	} else {
		b.WriteString("| Name | Address | Usable |\n|---|---|---|\n")
		n := time.Now().Unix()
		for _, p := range t.Policy.Payees {
			u := "now"
			if p.UsableAt > n {
				u = "on hold until " + when(p.UsableAt)
			}
			b.WriteString("| " + p.Name + " | `" + p.Addr.String() + "` | " + u + " |\n")
		}
		b.WriteString("\n")
	}
	pending := 0
	for _, h := range t.Holds {
		if h.Status == "pending" {
			pending++
		}
	}
	b.WriteString("## Waiting for you (" + strconv.Itoa(pending) + ")\n\n")
	if pending > 0 {
		b.WriteString("| # | To | Amount | Why held | |\n|---|---|---:|---|---|\n")
		for _, h := range t.Holds {
			if h.Status != "pending" {
				continue
			}
			hid := strconv.Itoa(h.ID)
			b.WriteString("| " + hid + " | " + who(h.Payee, h.To) + " | " + gnot(h.Amount) + " | " + strings.TrimPrefix(outcome("hold:"+h.Reason), "⏸ held: ") + " | [Approve](" +
				self.Call("Approve", "tabID", id, "holdID", hid) + ") · [Reject](" + self.Call("Reject", "tabID", id, "holdID", hid) + ") |\n")
		}
		b.WriteString("\n")
	}
	b.WriteString("## Ledger (newest first)\n\n")
	for i := len(t.Ledger) - 1; i >= 0 && i >= len(t.Ledger)-20; i-- {
		e := t.Ledger[i]
		line := "- `" + clock(e.Time) + "` **" + e.Action + "**"
		if e.Amount != 0 {
			line += " " + gnot(e.Amount)
		}
		if e.To != "" {
			line += " → " + who(e.Payee, e.To)
		}
		line += ": " + outcome(e.Decision)
		if e.Note != "" {
			line += " · _" + esc(e.Note) + "_"
		}
		b.WriteString(line + "\n")
	}
	return b.String()
}

var reasonWords = map[string]string{
	"frozen": "tab frozen", "policy-expired": "tab expired", "session-expired": "session expired", "bad-amount": "bad amount",
	"unknown-payee": "not a payee", "insufficient-balance": "not enough on the tab", "overflow": "overflow",
	"payee-hold": "new payee address", "over-per-payment": "over the per-payment cap", "over-daily-cap": "over the daily cap",
	"closed": "tab closed",
}

// outcome turns a ledger decision into words: allow -> paid, hold:<r> -> held, deny:<r> -> refused.
func outcome(d string) string {
	kind, reason := d, ""
	if i := strings.Index(d, ":"); i > 0 {
		kind, reason = d[:i], d[i+1:]
	}
	if w, ok := reasonWords[reason]; ok {
		reason = w
	}
	switch kind {
	case "allow":
		return "✅ paid"
	case "hold":
		return "⏸ held: " + reason
	case "deny":
		return "⛔ refused: " + reason
	}
	return d
}

func clock(t int64) string { return time.Unix(t, 0).UTC().Format("01-02 15:04:05") }

func status(t *Tab) string {
	switch {
	case t.Closed:
		return "closed"
	case t.State.Frozen:
		return "frozen"
	}
	return "open"
}

func who(name string, a address) string {
	s := a.String()
	short := s
	if len(s) > 12 {
		short = s[:8] + "…" + s[len(s)-4:]
	}
	if name != "" {
		return name + " (`" + short + "`)"
	}
	return "`" + short + "`"
}

// gnot formats ugnot as GNOT with up to 6 decimals.
func gnot(u int64) string {
	whole := strconv.FormatInt(u/1_000_000, 10)
	frac := u % 1_000_000
	if frac == 0 {
		return whole + " GNOT"
	}
	f := strconv.FormatInt(frac+1_000_000, 10)[1:]
	return whole + "." + strings.TrimRight(f, "0") + " GNOT"
}

func bar(v, max int64) string {
	if max <= 0 {
		return ""
	}
	n := int(v * 10 / max)
	if n > 10 {
		n = 10
	}
	return "`" + strings.Repeat("█", n) + strings.Repeat("░", 10-n) + "`"
}

func when(t int64) string { return time.Unix(t, 0).UTC().Format("2006-01-02 15:04:05") }

func esc(s string) string {
	return strings.NewReplacer("|", "\\|", "\n", " ", "[", "\\[", "]", "\\]", "<", "&lt;").Replace(s)
}

