	println("  brewery has", bal(brewery))

	// unknown payee: refused, but recorded
	at(t0+3603)
	testing.SetRealm(testing.NewUserRealm(agent))
	println("4 stranger:", bartab.Order(cross(cur), id, thief, 10_000, "tip?", "k3"))

