	id := bartab.OpenTab(cross(cur), agent, 1_000_000, 2_500_000, 3600, 0)
	at(t0 + 1)
	testing.SetRealm(testing.NewUserRealm(owner))
	bartab.SetPayee(cross(cur), id, "brewery", brewery)
