package kylix

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nym-kylix000/ring/v0"
	"gno.land/r/gnoswap/pool"
	"gno.land/r/gnoswap/router"
	"gno.land/r/nt/grc20reg/v0"
)

// The GnoSwap bridge (decision 6). A ring may contain one hop that gives
// token A to someone who wants token B; Kylix swaps A for B on GnoSwap in
// the middle of the settlement. See docs/research/gnoswap-bridge.md.
//
// The input passes through Kylix's own sub-address cur.Sub("settle") for
// the length of one swap, because the router pays out to whoever called it.
// It is empty again before SettleRing returns.

const (
	// routerPath is the router proxy. The input allowance must be on this
	// address: the router pulls the input with its own RealmTeller.
	routerPath = "gno.land/r/gnoswap/router"
	settlePath = "settle"
)

var feeTiers = [4]uint32{100, 500, 3000, 10000}

// bridgeFee picks the fee tier SettleRing swaps through: among the pools
// that exist for the pair and hold some of the output token, the one holding
// the most of it. It returns false when there is none. It only reads (pool
// getters run without crossing and have no realm value with which to call
// back).
//
// A pool's balance counts liquidity at every price, so it is a poor guide
// when a pair has several pools: anyone can add liquidity that sits far from
// the current price and make this choose a pool that cannot pay the
// receiver's minimum, which aborts the ring. The receiver never gets less
// than their minimum either way. SettleRingVia lets the settler name the
// pool; this automatic choice is a convenience for pairs with one pool.
//
// No price quote is taken here: a DrySwapRoute costs about 20M gas.
func bridgeFee(keyIn, keyOut string) (uint32, bool) {
	best, found := uint32(0), false
	var bestReserve int64
	outIsToken1 := strings.Compare(keyOut, keyIn) > 0
	for _, fee := range feeTiers {
		path := pool.GetPoolPath(keyIn, keyOut, fee)
		if !pool.ExistsPoolPath(path) {
			continue
		}
		b0, b1, err := pool.GetBalances(path)
		if err != nil {
			continue
		}
		reserve := b0
		if outIsToken1 {
			reserve = b1
		}
		if reserve > bestReserve {
			best, bestReserve, found = fee, reserve, true
		}
	}
	return best, found
}

// poolExists reports whether a GnoSwap pool exists for the pair at fee.
func poolExists(keyIn, keyOut string, fee uint32) bool {
	return pool.ExistsPoolPath(pool.GetPoolPath(keyIn, keyOut, fee))
}

// isFeeTier reports whether fee is one of GnoSwap's fee tiers.
func isFeeTier(fee uint32) bool {
	for _, f := range feeTiers {
		if f == fee {
			return true
		}
	}
	return false
}

// bridgeHop settles a bridged hop: pull the offer's input through its slot
// into the settle sub-address, swap it as that sub-address, check that the
// whole input was used and that the output meets the receiver's minimum,
// and forward all of the output to the receiver. slot and settle are
// sub-realm tokens minted from SettleRing's cur; this is called without
// crossing so both stay current.
func bridgeHop(_ int, slot, settle realm, i int, o *Offer, h ring.Hop, to address, fee uint32) {
	keyIn, keyOut := h.Asset.Key, h.Want.Key
	amountIn, wantMin := h.Asset.Amount, h.Want.Amount
	settleAddr := settle.Address()
	routerAddr := chain.PackageAddress(routerPath)
	route := keyIn + ":" + keyOut + ":" + strconv.FormatUint(uint64(fee), 10)

	grc20reg.TransferFrom(0, slot, keyIn, o.Owner, settleAddr, amountIn)
	grc20reg.Approve(0, settle, keyIn, routerAddr, amountIn)
	usedStr, gotStr := router.ExactInSingleSwapRoute(cross(settle),
		keyIn, keyOut, i64(amountIn), route, i64(wantMin), "0", time.Now().Unix(), "")

	used, err := strconv.ParseInt(usedStr, 10, 64)
	if err != nil || used != amountIn {
		panic(legMsg(i, o.ID, "swap used "+usedStr+" of "+i64(amountIn)+"; a leg gives its whole amount"))
	}
	// The router spent exactly the allowance, which deletes it. Setting it to
	// 0 again would store a zero entry, so check instead of resetting.
	if left := tokenOf(keyIn).Allowance(settleAddr, routerAddr); left != 0 {
		panic(legMsg(i, o.ID, "router allowance left after the swap: "+i64(left)))
	}
	got, err := strconv.ParseInt(gotStr, 10, 64)
	if err != nil || got <= 0 || got < wantMin {
		panic(legMsg(i, o.ID, "swap returned "+gotStr+" of "+keyOut+", receiver wants at least "+i64(wantMin)))
	}
	grc20reg.Transfer(0, settle, keyOut, to, got)
}

// SettleAddress is the sub-address a bridged swap passes through. It holds
// nothing between transactions.
func SettleAddress() address { return chain.DerivePkgSubAddr(selfPath, settlePath) }

package kylix

import (
	"chain"
	"strings"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
)

// ItemID names an item when Kylix asks a collection about it.
//
// It is declared here, not as a plain string, so that only realm code can
// implement OwnerFn or ApprovedFn: a /p/ package cannot import this realm,
// so it cannot name this type. That closes the one gap a non-crossing
// callback would otherwise leave open (a top-level /p/ function called from
// here would run with this realm's storage authority; see
// gno-security-guide.md section 3C).
type ItemID string

// MoveFn moves one item from `from` to `to`. Kylix calls it crossing, as the
// offer's slot sub-address: inside it, cur.Previous().Address() is the slot
// that `from` approved for that one offer. It must move the item only if
// that address is approved for it, and return an error (or panic) otherwise.
// Because it is a crossing function, it can only be declared in a realm.
//
// An adapter's MoveFn instead crosses into its target collection as its own
// sub-identity "k/<slot address>" (see RegisterAdapter).
type MoveFn func(cur realm, from, to address, itemID string) error

// OwnerFn reports who owns an item, or the empty address if nobody does.
// Kylix calls it without crossing, so it runs with its collection's storage
// and has no realm value with which to call back into Kylix.
type OwnerFn func(itemID ItemID) address

// ApprovedFn reports whether spender may move the item now. It is optional
// (see RegisterApprovalCheck); like OwnerFn it is called without crossing.
type ApprovedFn func(itemID ItemID, spender address) bool

type collection struct {
	name     string
	move     MoveFn
	ownerOf  OwnerFn
	approved ApprovedFn // optional
	target   string     // adapters only: the collection realm the adapter drives
}

// Collection describes a registered collection. All strings are untrusted
// text; escape them before rendering.
type Collection struct {
	Key           string // the registering realm's package path
	Name          string
	Adapter       bool   // registered with RegisterAdapter
	Target        string // adapters only: the collection realm it drives
	Official      bool   // the key is under Kylix's own namespace
	Label         string // "official collection", "official adapter", "third-party collection" or "third-party adapter"
	ApprovalCheck bool   // an ApprovedFn is registered
}

const (
	maxCollectionNameLen = 64
	maxTargetLen         = 200
	adapterSubPrefix     = "k/"
)

var collections avl.Tree // realm pkgpath -> *collection

// RegisterItem registers the calling realm as a collection whose items can
// be traded. The collection key is the caller's package path, so no realm can
// register under another's name, and a realm registers once: what Kylix
// calls for its items never changes after offers have been posted.
//
// Kylix trusts a collection only about its own items. After every move it
// checks ownerOf(id) == to, so a collection that says it moved an item it
// did not can only hurt people who chose to want that collection's items.
func RegisterItem(cur realm, name string, move MoveFn, ownerOf OwnerFn) {
	guard(cur)
	register(0, cur.Previous(), name, "", move, ownerOf)
}

// RegisterAdapter registers the calling realm as an adapter for an existing
// collection realm, target, that knows nothing of Kylix. The key is still
// the adapter's own package path; target is recorded for display.
//
// The difference is the address an owner approves in the target collection:
// not the offer's slot but the adapter's sub-address
// DerivePkgSubAddr(adapterPath, "k/"+slotAddress), which ApproveTarget
// returns. The adapter's MoveFn crosses into the target as
// cur.Sub("k/"+cur.Previous().Address()), so only that one slot can ever
// produce the identity the owner approved.
//
// An adapter whose path sits under Kylix's own namespace is labelled
// official, any other third-party. The label is information only; nothing
// is blocked on it.
func RegisterAdapter(cur realm, target, name string, move MoveFn, ownerOf OwnerFn) {
	guard(cur)
	if !validTarget(target) {
		panic("kylix: target must be the package path of a realm, e.g. gno.land/r/owner/collection")
	}
	prev := cur.Previous()
	if target == prev.PkgPath() {
		panic("kylix: an adapter cannot target itself; use RegisterItem")
	}
	register(0, prev, name, target, move, ownerOf)
}

// RegisterApprovalCheck adds an ApprovedFn to the calling realm's
// registration, once. SettleRing then refuses, before anything moves and
// naming the leg, an item that is not approved for ApproveTarget(...).
func RegisterApprovalCheck(cur realm, approved ApprovedFn) {
	guard(cur)
	c := getCollection(cur.Previous().PkgPath())
	if c == nil {
		panic("kylix: register the collection first")
	}
	if approved == nil {
		panic("kylix: approved is required")
	}
	if c.approved != nil {
		panic("kylix: approval check already registered")
	}
	c.approved = approved
	chain.Emit("ApprovalCheckRegistered", "key", cur.Previous().PkgPath())
}

func register(_ int, prev realm, name, target string, move MoveFn, ownerOf OwnerFn) {
	key := prev.PkgPath()
	if key == "" {
		panic("kylix: only a realm can register a collection")
	}
	if prev.IsEphemeral() {
		panic("kylix: a MsgRun package cannot register a collection")
	}
	if strings.Contains(key, "#") {
		panic("kylix: register from the realm itself, not from a sub-identity")
	}
	if move == nil || ownerOf == nil {
		panic("kylix: move and ownerOf are both required")
	}
	if !validName(name) {
		panic("kylix: collection name must be 1-64 bytes of printable UTF-8")
	}
	if collections.Has(key) {
		panic("kylix: collection already registered")
	}
	collections.Set(key, &collection{name: name, move: move, ownerOf: ownerOf, target: target})
	chain.Emit("CollectionRegistered", "key", key, "name", name, "target", target)
}

// ApproveTarget returns the exact address an owner must approve for the
// offer with this owner and nonce that gives an asset under key: the slot
// for a token or a native collection, the adapter's derived sub-address for
// an adapter. It reads only Kylix's own state.
func ApproveTarget(owner address, nonce uint64, key string) address {
	slot := SlotAddress(owner, nonce)
	if c := getCollection(key); c != nil && c.target != "" {
		return chain.DerivePkgSubAddr(key, adapterSubPrefix+slot.String())
	}
	return slot
}

// IsCollection reports whether key is a registered collection.
func IsCollection(key string) bool { return collections.Has(key) }

// CollectionName returns the display name a collection registered with.
// It is untrusted text; escape it before rendering.
func CollectionName(key string) string {
	c := getCollection(key)
	if c == nil {
		return ""
	}
	return c.name
}

// GetCollection describes a registered collection.
func GetCollection(key string) (Collection, bool) {
	c := getCollection(key)
	if c == nil {
		return Collection{}, false
	}
	return describe(key, c), true
}

// IsOfficial reports whether key sits under Kylix's own namespace, e.g.
// gno.land/r/<namespace>/... for Kylix at gno.land/r/<namespace>/kylix.
func IsOfficial(key string) bool {
	ns := namespacePrefix()
	return ns != "" && strings.HasPrefix(key, ns)
}

func describe(key string, c *collection) Collection {
	return Collection{
		Key:           key,
		Name:          c.name,
		Adapter:       c.target != "",
		Target:        c.target,
		Official:      IsOfficial(key),
		Label:         collectionKind(key),
		ApprovalCheck: c.approved != nil,
	}
}

// namespacePrefix is the first three segments of Kylix's own path plus a
// slash, e.g. "gno.land/r/nym-kylix000/".
func namespacePrefix() string {
	parts := strings.SplitN(selfPath, "/", 4)
	if len(parts) < 3 {
		return ""
	}
	return parts[0] + "/" + parts[1] + "/" + parts[2] + "/"
}

func getCollection(key string) *collection {
	v := collections.Get(key)
	if v == nil {
		return nil
	}
	return v.(*collection)
}

func validName(s string) bool {
	if len(s) == 0 || len(s) > maxCollectionNameLen || !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		switch {
		case r < 0x20, r == 0x7f, r >= 0x80 && r < 0xa0: // control characters
			return false
		case r >= 0x200b && r <= 0x200f, r >= 0x2028 && r <= 0x202e, r >= 0x2066 && r <= 0x2069, r == 0xfeff:
			return false // zero-width, line separators and bidi overrides
		}
	}
	return true
}

// validTarget accepts a realm package path: <domain>/r/<rest>, lowercase
// letters, digits and . _ - / only.
func validTarget(s string) bool {
	if len(s) == 0 || len(s) > maxTargetLen || !strings.Contains(s, "/r/") {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '.', c == '_', c == '-', c == '/':
		default:
			return false
		}
	}
	return !strings.Contains(s, "//") && !strings.HasSuffix(s, "/")
}

package kylix

import (
	"chain/runtime"
	"strconv"
	"strings"
)

// MaxDeliverableBatch bounds one Deliverable query. A token offer costs two
// ledger reads; an item offer calls its collection's OwnerFn and, if
// registered, ApprovedFn, which is foreign code of unknown cost.
const MaxDeliverableBatch = 50

// Deliverable reports, for each of up to MaxDeliverableBatch comma-separated
// offer ids, whether its owner could deliver it right now and, if not, why.
// It runs the same check as SettleRing's preflight, so a
// solver can screen candidates in one query instead of one or two per offer:
//
//	{"height":123,"offers":[
//	  {"id":7,"deliverable":true,"reason":""},
//	  {"id":9,"deliverable":false,"reason":"slot g1... may spend 0 of ..., offer gives 10"},
//	  {"id":12,"deliverable":false,"reason":"not open"}]}
//
// An expired offer is reported as not deliverable with reason "expired".
// It writes nothing to Kylix, but for an item it calls the collection's
// registered functions, which may write to their own realm's storage (see
// SettleRing); as a query that costs nothing. Bridged hops need a pool too;
// that is not checked here.
func Deliverable(ids string) string {
	assertNotSettling()
	parts := strings.Split(ids, ",")
	if strings.TrimSpace(ids) == "" || len(parts) > MaxDeliverableBatch {
		panic("kylix: Deliverable takes 1 to " + strconv.Itoa(MaxDeliverableBatch) + " offer ids")
	}
	h := runtime.ChainHeight()
	var sb strings.Builder
	sb.WriteString(`{"height":`)
	sb.WriteString(strconv.FormatInt(h, 10))
	sb.WriteString(`,"offers":[`)
	for i, p := range parts {
		id, err := strconv.ParseUint(strings.TrimSpace(p), 10, 64)
		if err != nil || id == 0 {
			panic("kylix: bad offer id " + strconv.Quote(strings.TrimSpace(p)))
		}
		reason := "not open"
		if o := loadOffer(id); o != nil {
			if expired(o, h) {
				reason = "expired"
			} else {
				reason = undeliverable(o)
			}
		}
		if i > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(`{"id":`)
		sb.WriteString(u64(id))
		sb.WriteString(`,"deliverable":`)
		sb.WriteString(strconv.FormatBool(reason == ""))
		sb.WriteString(`,"reason":`)
		sb.WriteString(jsonString(reason))
		sb.WriteByte('}')
	}
	sb.WriteString(`]}`)
	return sb.String()
}

package kylix

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nym-kylix000/ring/v0"
)

const (
	// DefaultExportPage and MaxExportPage bound ExportGraphJSONPage, so one
	// query stays within the read-gas limit however large the book grows.
	DefaultExportPage = 100
	MaxExportPage     = 500
)

// ExportGraphJSON returns every open, unexpired offer and every registered
// collection as JSON, for off-chain solvers looking for rings. Its cost
// grows with the book; past a few hundred offers use ExportGraphJSONPage.
//
//	{"realm":"gno.land/r/...","height":123,
//	 "collections":[{"key":"gno.land/r/...","name":"...","adapter":false,
//	   "target":"","official":true,"approvalCheck":true}],
//	 "offers":[{"id":1,"owner":"g1...","nonce":1,"slot":"g1...","approve":"g1...",
//	   "give":{"kind":"fungible","key":"gno.land/r/x.FOO","id":"","amount":"100"},
//	   "want":{"kind":"item","key":"gno.land/r/y","id":"relic-7","amount":"0"},
//	   "expiry":12345,"viaSession":false}],
//	 "hasMore":false,"next":0,"total":1}
//
// Amounts are decimal strings because int64 does not fit a JSON number in
// most parsers. "approve" is the address the owner must have approved (see
// ApproveTarget); a solver can check it before proposing a ring, or ask
// Deliverable. Offers are in id order. "hasMore" says another page follows
// and "next" is the cursor to pass as `after` for it (0 when hasMore is
// false). "total" counts every open offer in the book, expired ones
// included until pruned, so it can exceed what the pages list.
func ExportGraphJSON() string {
	assertNotSettling()
	return exportJSON(0, -1)
}

// ExportGraphJSONPage returns at most limit open, unexpired offers with id
// greater than after (limit <= 0 means DefaultExportPage; at most
// MaxExportPage). It looks at no more than MaxExportPage offers, expired
// ones included, so its cost is bounded however many offers have expired;
// a page can therefore hold fewer than limit offers and still have
// "hasMore" set. "collections" is included only in the first page (after
// == 0). Page with "hasMore" and "next" as ExportGraphJSON describes.
func ExportGraphJSONPage(after uint64, limit int) string {
	assertNotSettling()
	if limit <= 0 {
		limit = DefaultExportPage
	}
	if limit > MaxExportPage {
		limit = MaxExportPage
	}
	return exportJSON(after, limit)
}

// exportJSON lists offers after the given id; limit < 0 means all, with no
// scan bound.
func exportJSON(after uint64, limit int) string {
	h := runtime.ChainHeight()
	var sb strings.Builder
	sb.WriteString(`{"realm":`)
	sb.WriteString(jsonString(selfPath))
	sb.WriteString(`,"height":`)
	sb.WriteString(strconv.FormatInt(h, 10))
	if after == 0 {
		writeCollectionsJSON(&sb, "", MaxExportCollections)
	}
	sb.WriteString(`,"offers":[`)
	paged := limit >= 0
	count, scanned := 0, 0
	var last, next uint64 // last: id of the last offer looked at
	eachOfferAfter(after, func(o *Offer) bool {
		if paged && scanned == MaxExportPage {
			next = last // scan bound reached; more offers may remain
			return true
		}
		scanned++
		if expired(o, h) {
			last = o.ID
			return false
		}
		if paged && count == limit {
			next = last // an unexpired offer remains; resume after the last one seen
			return true
		}
		last = o.ID
		if count > 0 {
			sb.WriteByte(',')
		}
		writeOfferJSON(&sb, o)
		count++
		return false
	})
	sb.WriteString(`],"hasMore":`)
	sb.WriteString(strconv.FormatBool(next != 0))
	sb.WriteString(`,"next":`)
	sb.WriteString(u64(next))
	sb.WriteString(`,"total":`)
	sb.WriteString(strconv.Itoa(offers.Size()))
	sb.WriteString(`}`)
	return sb.String()
}

func writeOfferJSON(sb *strings.Builder, o *Offer) {
	sb.WriteString(`{"id":`)
	sb.WriteString(u64(o.ID))
	sb.WriteString(`,"owner":`)
	sb.WriteString(jsonString(o.Owner.String()))
	sb.WriteString(`,"nonce":`)
	sb.WriteString(u64(o.Nonce))
	sb.WriteString(`,"slot":`)
	sb.WriteString(jsonString(SlotAddress(o.Owner, o.Nonce).String()))
	sb.WriteString(`,"approve":`)
	sb.WriteString(jsonString(ApproveTarget(o.Owner, o.Nonce, o.Give.Key).String()))
	sb.WriteString(`,"give":`)
	writeAssetJSON(sb, o.Give)
	sb.WriteString(`,"want":`)
	writeAssetJSON(sb, o.Want)
	sb.WriteString(`,"expiry":`)
	sb.WriteString(strconv.FormatInt(o.Expiry, 10))
	sb.WriteString(`,"viaSession":`)
	sb.WriteString(strconv.FormatBool(o.ViaSession))
	sb.WriteByte('}')
}

// MaxExportCollections bounds the collections listed in one export: the
// first offers page carries up to this many, official ones first, and
// ExportCollectionsJSON pages through the rest.
const MaxExportCollections = 100

// ExportCollectionsJSON lists up to limit registered collections (at most
// MaxExportCollections; 0 for that maximum), official ones first, starting
// after the key after ("" for the start):
//
//	{"collections":[...],"collectionsHasMore":true,"collectionsNext":"gno.land/r/..."}
//
// Pass collectionsNext as after for the next page.
func ExportCollectionsJSON(after string, limit int) string {
	assertNotSettling()
	if limit <= 0 || limit > MaxExportCollections {
		limit = MaxExportCollections
	}
	var sb strings.Builder
	writeCollectionsJSON(&sb, after, limit)
	return "{" + strings.TrimPrefix(sb.String(), ",") + "}"
}

// writeCollectionsJSON writes `,"collections":[...],"collectionsHasMore":b,
// "collectionsNext":"key"`.
func writeCollectionsJSON(sb *strings.Builder, after string, limit int) {
	keys, more := collectionKeys(after, limit)
	sb.WriteString(`,"collections":[`)
	for i, key := range keys {
		if i > 0 {
			sb.WriteByte(',')
		}
		writeCollectionJSON(sb, describe(key, getCollection(key)))
	}
	sb.WriteString(`],"collectionsHasMore":`)
	sb.WriteString(strconv.FormatBool(more))
	next := ""
	if more {
		next = keys[len(keys)-1]
	}
	sb.WriteString(`,"collectionsNext":`)
	sb.WriteString(jsonString(next))
}

func writeCollectionJSON(sb *strings.Builder, c Collection) {
	sb.WriteString(`{"key":`)
	sb.WriteString(jsonString(c.Key))
	sb.WriteString(`,"name":`)
	sb.WriteString(jsonString(c.Name))
	sb.WriteString(`,"adapter":`)
	sb.WriteString(strconv.FormatBool(c.Adapter))
	sb.WriteString(`,"target":`)
	sb.WriteString(jsonString(c.Target))
	sb.WriteString(`,"official":`)
	sb.WriteString(strconv.FormatBool(c.Official))
	sb.WriteString(`,"label":`)
	sb.WriteString(jsonString(c.Label))
	sb.WriteString(`,"approvalCheck":`)
	sb.WriteString(strconv.FormatBool(c.ApprovalCheck))
	sb.WriteByte('}')
}

func writeAssetJSON(sb *strings.Builder, a ring.Asset) {
	sb.WriteString(`{"kind":`)
	sb.WriteString(jsonString(a.Kind.String()))
	sb.WriteString(`,"key":`)
	sb.WriteString(jsonString(a.Key))
	sb.WriteString(`,"id":`)
	sb.WriteString(jsonString(a.ID))
	sb.WriteString(`,"amount":"`)
	sb.WriteString(strconv.FormatInt(a.Amount, 10))
	sb.WriteString(`"}`)
}

// jsonString quotes s as a JSON string. Besides what JSON requires, it
// escapes <, >, & and U+2028/U+2029 so the output is also safe to embed in
// HTML or a JavaScript literal. Invalid UTF-8 becomes U+FFFD.
func jsonString(s string) string {
	const hex = "0123456789abcdef"
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			sb.WriteString(`\"`)
		case r == '\\':
			sb.WriteString(`\\`)
		case r == '\n':
			sb.WriteString(`\n`)
		case r == '\r':
			sb.WriteString(`\r`)
		case r == '\t':
			sb.WriteString(`\t`)
		case r < 0x20, r == '<', r == '>', r == '&', r == 0x2028, r == 0x2029:
			sb.WriteString(`\u`)
			sb.WriteByte(hex[(r>>12)&0xf])
			sb.WriteByte(hex[(r>>8)&0xf])
			sb.WriteByte(hex[(r>>4)&0xf])
			sb.WriteByte(hex[r&0xf])
		default:
			sb.WriteRune(r)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

// Package kylix settles trades in a circle. Each person posts an offer, "I
// give X, I want at least Y". When two to six offers form a closed ring,
// anyone can submit the ring and every leg settles in one transaction, or
// nothing moves.
//
// Kylix never holds anyone's assets. Before posting, an owner approves a
// sub-address of this realm that belongs to that one offer (see NextSlot).
// At settlement Kylix acts as that sub-address to move the offer's asset from
// its owner straight to the next owner in the ring.
package kylix

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nym-kylix000/ring/v0"
)

// Offer is one open offer, as decoded from storage (see store.gno). Every
// Offer value is a fresh copy, so nothing outside can alias state.
//
// There is no status field: only open offers are stored. Settling,
// cancelling or pruning an offer deletes it (releasing its storage deposit to
// whoever sent that transaction), and the event emitted says which.
type Offer struct {
	ID    uint64
	Owner address
	Nonce uint64 // per owner; the offer's slot is w/<owner>/<nonce>
	Give  ring.Asset
	Want  ring.Asset
	// Expiry is the last block height at which the offer may settle. Every
	// offer has one (see PostIntent); after it anyone may prune the offer.
	Expiry     int64
	ViaSession bool // posted by a session key
}

const (
	// BlocksPerDay assumes 5 s blocks.
	BlocksPerDay = 17280
	// DefaultExpiryBlocks is the lifetime of an offer posted with expiry 0:
	// about 7 days.
	DefaultExpiryBlocks = 7 * BlocksPerDay
	// MaxExpiryBlocks is the longest lifetime an offer may ask for: about 30
	// days. Every offer expires, so every offer can eventually be pruned.
	MaxExpiryBlocks = 30 * BlocksPerDay

	maxItemIDLen = 64
)

var (
	selfPath string        // this realm's package path, captured in init
	nonces   bptree.BPTree // owner -> uint64, last nonce used by that owner
	lastID   uint64

	// locked is true while SettleRing is moving assets. Every exported
	// function except Render refuses to run while it is set, so foreign code
	// called during a settlement can neither re-enter nor observe the book
	// half settled. A failed transaction rolls it back with everything else.
	locked bool

	// sessionCheck reports whether the transaction was signed by a session
	// key. It is a variable only so that in-package tests can simulate a
	// session signer, which `gno test` cannot produce. Nothing in this
	// package assigns it outside tests.
	sessionCheck = func() bool {
		_, _, _, isSession := runtime.GetSessionInfo()
		return isSession
	}
)

func init(cur realm) {
	selfPath = cur.PkgPath()
}

// NextSlot returns the nonce and the slot address that owner's next offer
// will use. The owner approves the slot for the offered asset, then calls
// PostIntent; both can go in one transaction because the slot is
// deterministic and only the owner can advance their own nonce.
func NextSlot(owner address) (nonce uint64, slot address) {
	if !owner.IsValid() {
		panic("kylix: invalid owner address")
	}
	nonce = lastNonce(owner) + 1
	return nonce, SlotAddress(owner, nonce)
}

// SlotAddress is the sub-address that may move the asset of owner's offer
// with the given nonce. Off chain: chain.DerivePkgSubAddr(<kylix path>,
// "w/<owner>/<nonce>").
func SlotAddress(owner address, nonce uint64) address {
	return chain.DerivePkgSubAddr(selfPath, slotPath(owner, nonce))
}

// PostIntent records an offer: the caller gives giveAmount of a token, or
// one item, and wants at least wantMin of a token, or one item. Kinds are
// "fungible" (key: a grc20reg key, id: empty) and "item" (key: a registered
// collection, id: the item id, amount: 0). expiry is the last block height
// at which the offer may settle: 0 means DefaultExpiryBlocks from now, and it
// may be at most MaxExpiryBlocks from now. It returns the offer id; the
// IntentPosted event carries the expiry it got.
//
// A token offer, or an item offer of an official collection, must be
// deliverable when it is posted: the same check settlement runs first (see
// undeliverable). For a token, the owner holds the amount and has approved
// NextSlot's address for exactly that amount; for an official item, the
// collection says the owner holds it and, if it registered an approval
// check, that ApproveTarget's address may move it. So approve first, then
// post (two messages in one transaction work). Nothing is pulled.
//
// An official collection's functions are Kylix's own code; Kylix holds its
// lock while they run, so they cannot post, cancel or settle, nor read the
// book. An item of a third-party collection is not checked: posting runs no
// third-party code, so a collection cannot bill the poster for storage
// (security review 4, R4-1). Such offers are kept off the home page and are
// checked when someone settles them.
func PostIntent(cur realm, giveKind, giveKey, giveID string, giveAmount int64, wantKind, wantKey, wantID string, wantMin int64, expiry int64) uint64 {
	guard(cur)
	owner := cur.Previous().Address()
	give := mustAsset("give", giveKind, giveKey, giveID, giveAmount)
	want := mustAsset("want", wantKind, wantKey, wantID, wantMin)
	if give.SameAs(want) {
		panic("kylix: an offer cannot give the asset it wants")
	}
	expiry = offerExpiry(expiry, runtime.ChainHeight())

	nonce := lastNonce(owner) + 1
	o := &Offer{
		ID:         lastID + 1,
		Owner:      owner,
		Nonce:      nonce,
		Give:       give,
		Want:       want,
		Expiry:     expiry,
		ViaSession: sessionCheck(),
	}
	why := ""
	if give.Kind == ring.Fungible || IsOfficial(give.Key) {
		locked = true
		why = undeliverable(o)
		locked = false
	}
	if why != "" {
		panic("kylix: give: the offer could not settle now (" + why + "); approve first, then post")
	}
	nonces.Set(owner.String(), nonce)
	lastID++
	storeOffer(o)

	chain.Emit("IntentPosted",
		"id", u64(o.ID),
		"owner", owner.String(),
		"slot", SlotAddress(owner, nonce).String(),
		"give", give.String(),
		"want", want.String(),
		"expiry", strconv.FormatInt(expiry, 10),
	)
	return o.ID
}

// CancelIntent withdraws an open offer. Only its owner may cancel, and not
// through a session key. It calls no foreign code, so nothing can stop an
// owner from cancelling. Cancelling does not revoke the owner's approval of
// the slot; the slot is never used again, but the owner may revoke it at the
// token or collection for tidiness.
func CancelIntent(cur realm, id uint64) {
	guard(cur)
	if sessionCheck() {
		panic("kylix: a session key cannot cancel an offer; sign with the account key")
	}
	o := mustOpen(id)
	if cur.Previous().Address() != o.Owner {
		panic("kylix: only the owner can cancel offer " + u64(id))
	}
	removeOffer(o.ID)
	chain.Emit("IntentCancelled", "id", u64(id), "owner", o.Owner.String())
}

// GetOffer returns an open offer, expired ones included until pruned.
func GetOffer(id uint64) (Offer, bool) {
	assertNotSettling()
	o := loadOffer(id)
	if o == nil {
		return Offer{}, false
	}
	return *o, true
}

// OpenOffers is the number of open offers, expired ones included until they
// are pruned.
func OpenOffers() int {
	assertNotSettling()
	return offers.Size()
}

// guard runs first in every state-changing entry point.
func guard(cur realm) {
	if locked {
		panic("kylix: re-entrant call during settlement")
	}
	// Kylix cannot send coins anywhere, so coins a user sends straight to it
	// would be stuck. Coins attached to a MsgRun or sent to a realm that then
	// calls Kylix went to that caller, not to Kylix, so they are not refused.
	// OriginSend is read only to refuse, never as proof of payment.
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("kylix: do not send coins; trade GNOT as wugnot")
	}
}

// assertNotSettling runs first in every exported read except Render: while
// SettleRing is moving assets the book is already updated but the assets
// are not, so a collection's callback must not be shown that state.
func assertNotSettling() {
	if locked {
		panic("kylix: settlement in progress")
	}
}

// offerExpiry turns PostIntent's expiry argument into a height: 0 means the
// default, a past or current height and one beyond the maximum are refused.
func offerExpiry(expiry, h int64) int64 {
	switch {
	case expiry == 0:
		return h + DefaultExpiryBlocks
	case expiry <= h:
		panic("kylix: expiry must be a future block height, or 0 for the default of " +
			strconv.Itoa(DefaultExpiryBlocks/BlocksPerDay) + " days")
	case expiry > h+MaxExpiryBlocks:
		panic("kylix: expiry may be at most " + strconv.Itoa(MaxExpiryBlocks/BlocksPerDay) +
			" days ahead, height " + strconv.FormatInt(h+MaxExpiryBlocks, 10))
	}
	return expiry
}

func mustOpen(id uint64) *Offer {
	o := loadOffer(id)
	if o == nil {
		panic("kylix: offer " + u64(id) + " is not open (unknown, settled, cancelled or pruned)")
	}
	return o
}

func removeOffer(id uint64) { offers.Remove(offerKey(id)) }

func expired(o *Offer, height int64) bool { return height > o.Expiry }

// mustAsset parses and validates one side of an offer against what is
// registered right now.
func mustAsset(side, kind, key, id string, amount int64) ring.Asset {
	k, ok := ring.ParseKind(kind)
	if !ok {
		panic("kylix: " + side + " kind must be \"fungible\" or \"item\"")
	}
	a := ring.Asset{Kind: k, Key: key, ID: id, Amount: amount}
	if r := a.Validate(); r != "" {
		panic("kylix: " + side + ": " + r)
	}
	switch k {
	case ring.Fungible:
		if tokenOf(key) == nil {
			panic("kylix: " + side + ": token is not in grc20reg")
		}
	case ring.Item:
		if getCollection(key) == nil {
			panic("kylix: " + side + ": collection is not registered with kylix")
		}
		if !validItemID(id) {
			panic("kylix: " + side + ": item id must be 1-64 characters of A-Z a-z 0-9 . _ : / - *")
		}
	}
	return a
}

func validItemID(id string) bool {
	if len(id) == 0 || len(id) > maxItemIDLen {
		return false
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		case c == '.', c == '_', c == ':', c == '/', c == '-', c == '*':
		default:
			return false
		}
	}
	return true
}

func lastNonce(owner address) uint64 {
	v := nonces.Get(owner.String())
	if v == nil {
		return 0
	}
	return v.(uint64)
}

func slotPath(owner address, nonce uint64) string {
	return "w/" + owner.String() + "/" + u64(nonce)
}

func u64(n uint64) string { return strconv.FormatUint(n, 10) }

package kylix

import (
	"chain/runtime"

	"gno.land/p/nym-kylix000/ring/v0"
)

// Bounds for the on-page ring search. Every cap is constant so Render("")
// stays O(1) in book size even when thousands of offers are open or expired.
//
// What may take part (security review 3, R3-2). Every offer was deliverable
// when it was posted, but its owner can make it dead later by moving the
// asset or revoking the approval. So the search checks each offer again:
//   - a token offer must be funded and approved now (token ledgers only);
//   - an item offer of an official collection (Kylix's own code, written not
//     to panic) that registered an approval check must be owned and
//     approved now;
//   - an item offer of any other collection is never checked here, because
//     that would run third-party code: the home page leaves it out, and an
//     offer page keeps it as unverified, after every verified offer.
//
// Crowding (security reviews 2 and 3). Posting an offer is cheap, so one
// account's offers must not push everyone else's out:
//   - the window counts up to matchScanRawLimit newest offers, of which an
//     owner contributes at most matchPerOwnerSeen (kept or skipped as dead
//     or expired); its further offers are passed over without counting, up
//     to matchScanReadLimit offers read in all;
//   - it keeps at most matchPerOwnerWindow offers of one owner;
//   - each wanted-asset bucket keeps at most matchPerOwnerBucket offers of
//     one owner, verified offers first;
//   - an offer may appear in at most matchPerOfferCands candidate rings, so
//     a handful of overlapping offers cannot use up the candidate budget
//     before distinct rings are found;
//   - only rings that close count as search steps, so offers that almost
//     match cost checks but not steps (security review 4, R4-3).
//
// Offers from many different accounts can still fill the window; on the
// home page they must be ready, so they form real rings that anyone may
// settle, and the settler collects their storage deposits.
const (
	matchScanRawLimit   = 100  // max offers counted for the window
	matchScanReadLimit  = 400  // max offers read from storage for the window
	matchScanLimit      = 50   // max offers kept in the search window
	matchPerOwnerSeen   = 8    // max offers of one owner counted (kept or skipped)
	matchPerOwnerWindow = 4    // max offers of one owner in the window
	matchMaxBucket      = 12   // max offers indexed per wanted asset
	matchPerOwnerBucket = 2    // max offers of one owner per wanted asset
	matchPerOfferCands  = 2    // max candidate rings one offer may appear in
	matchMaxSteps       = 500  // max closing rings tried per search (see findHomeRingsFrom)
	matchMaxChecks      = 8000 // max pairs and triples checked per search
	maxHomeRings        = 6    // max rings displayed on the home page
	maxOfferRings       = 6    // max rings displayed on an offer page
	maxCandidates       = 12   // max candidate rings collected before selection
)

// findHomeRings finds up to maxHomeRings disjoint direct rings of 2 or 3
// offers among the newest unexpired offers, every one of them verified ready
// now. It calls no third-party collection code.
func findHomeRings() [][]*Offer {
	return findHomeRingsFrom(newestUnexpiredOffers(0, true))
}

func findHomeRingsFrom(w *window) [][]*Offer {
	if len(w.offers) < 2 {
		return nil
	}
	window := w.offers
	ix := indexByWant(w)

	seen := map[string]bool{}
	uses := map[uint64]int{} // candidate rings each offer appears in
	var cands [][]*Offer
	steps := 0
	add := func(cand []*Offer) {
		k := ringDedupKey(cand)
		if seen[k] {
			return
		}
		for _, o := range cand {
			if uses[o.ID] >= matchPerOfferCands {
				return
			}
		}
		seen[k] = true
		for _, o := range cand {
			uses[o.ID]++
		}
		cands = append(cands, cand)
	}

	// Every pair and triple tried is checked in full before it counts as a
	// step (security review 4, R4-3): a step is a ring that closes, so
	// offers that almost match cannot use up the budget. The loops are
	// bounded by the window and bucket sizes (at most 50 starts, 12 offers
	// per bucket, 12 per pair: 7,800 checks), and by matchMaxChecks.
	checks := 0
	for _, a := range window {
		if steps >= matchMaxSteps || checks >= matchMaxChecks || len(cands) >= maxCandidates {
			break
		}
		if uses[a.ID] >= matchPerOfferCands || !ix.satisfiable(a) {
			continue
		}
		for _, b := range ix.byWant[assetBucketKey(a.Give)] {
			checks++
			if checks > matchMaxChecks || steps >= matchMaxSteps || len(cands) >= maxCandidates || uses[a.ID] >= matchPerOfferCands {
				break
			}
			if uses[b.ID] >= matchPerOfferCands || !directMatch(a, b) {
				continue
			}
			// 2-offer ring: a -> b -> a
			if directMatch(b, a) {
				steps++
				add(canonicalRing([]*Offer{a, b}))
				continue
			}
			// 3-offer ring: a -> b -> c -> a
			for _, c := range ix.byPair[pairKey(b.Give, a.Want)] {
				checks++
				if checks > matchMaxChecks || steps >= matchMaxSteps || len(cands) >= maxCandidates ||
					uses[a.ID] >= matchPerOfferCands || uses[b.ID] >= matchPerOfferCands {
					break
				}
				if c.ID == a.ID || c.Owner == a.Owner || uses[c.ID] >= matchPerOfferCands {
					continue
				}
				if !directMatch(b, c) || !directMatch(c, a) || duplicateGivenItem(a, b, c) {
					continue
				}
				steps++
				add(canonicalRing([]*Offer{a, b, c}))
			}
		}
	}

	if len(cands) == 0 {
		return nil
	}

	// Prefer 3-offer rings over 2-offer rings, then rings with newer offers.
	// len(cands) <= maxCandidates (12), so insertion sort is tiny and cheap.
	for i := 1; i < len(cands); i++ {
		cur := cands[i]
		j := i - 1
		for j >= 0 && ringBefore(cur, cands[j]) {
			cands[j+1] = cands[j]
			j--
		}
		cands[j+1] = cur
	}

	// Pick a non-overlapping subset so each open offer appears once on Home.
	used := map[uint64]bool{}
	var out [][]*Offer
	for _, r := range cands {
		if len(out) >= maxHomeRings {
			break
		}
		overlap := false
		for _, o := range r {
			if used[o.ID] {
				overlap = true
				break
			}
		}
		if overlap {
			continue
		}
		for _, o := range r {
			used[o.ID] = true
		}
		out = append(out, r)
	}
	return out
}

// findRingsForOffer finds up to maxOfferRings direct rings of 2 or 3 offers
// among the newest unexpired offers that include target. Every returned ring
// starts at target. Third-party items are kept unverified, after verified
// offers; no third-party collection code runs.
func findRingsForOffer(target *Offer) [][]*Offer {
	if target == nil || expired(target, runtime.ChainHeight()) {
		return nil
	}
	w := newestUnexpiredOffers(target.ID, false)
	if len(w.offers) == 0 {
		return nil
	}
	ix := indexByWant(w)

	seen := map[string]bool{}
	var out [][]*Offer
	steps := 0

	for _, b := range ix.byWant[assetBucketKey(target.Give)] {
		steps++
		if steps > matchMaxSteps || len(out) >= maxOfferRings {
			break
		}
		if !directMatch(target, b) {
			continue
		}
		if directMatch(b, target) {
			k := ringDedupKey(canonicalRing([]*Offer{target, b}))
			if !seen[k] {
				seen[k] = true
				out = append(out, []*Offer{target, b})
			}
			continue
		}
		for _, c := range ix.byPair[pairKey(b.Give, target.Want)] {
			steps++
			if steps > matchMaxSteps || len(out) >= maxOfferRings {
				break
			}
			if c.ID == target.ID || c.Owner == target.Owner {
				continue
			}
			if !directMatch(b, c) || !directMatch(c, target) {
				continue
			}
			if duplicateGivenItem(target, b, c) {
				continue
			}
			k := ringDedupKey(canonicalRing([]*Offer{target, b, c}))
			if !seen[k] {
				seen[k] = true
				out = append(out, []*Offer{target, b, c})
			}
		}
	}
	return out
}

// readyNow reports whether o may take part in the on-page search, and
// whether it was verified: see the comment on the bounds above. strict
// (the home page) leaves out what cannot be verified without third-party
// code.
func readyNow(o *Offer, strict bool) (ok, verified bool) {
	if o.Give.Kind == ring.Fungible {
		return undeliverable(o) == "", true
	}
	c := getCollection(o.Give.Key)
	if c == nil {
		return false, false
	}
	if IsOfficial(o.Give.Key) && c.approved != nil {
		return undeliverable(o) == "", true
	}
	return !strict, false
}

// newestUnexpiredOffers builds the search window from the newest offers,
// skipping excludeID (see the comment on the bounds above).
func newestUnexpiredOffers(excludeID uint64, strict bool) *window {
	h := runtime.ChainHeight()
	w := newWindow(strict)
	eachOfferBefore(0, func(o *Offer) bool {
		if w.done() {
			return true
		}
		if o.ID != excludeID {
			w.consider(o, h)
		}
		return false
	})
	return w
}

// window collects the search window.
type window struct {
	strict   bool
	offers   []*Offer
	verified map[uint64]bool
	kept     map[address]int
	seen     map[address]int
	counted  int
	read     int
}

func newWindow(strict bool) *window {
	return &window{
		strict:   strict,
		offers:   make([]*Offer, 0, matchScanLimit),
		verified: map[uint64]bool{},
		kept:     map[address]int{},
		seen:     map[address]int{},
	}
}

// done reports whether the window needs no more offers.
func (w *window) done() bool {
	return len(w.offers) >= matchScanLimit || w.counted >= matchScanRawLimit || w.read >= matchScanReadLimit
}

func (w *window) consider(o *Offer, h int64) {
	if w.done() {
		return
	}
	w.read++
	if w.seen[o.Owner] >= matchPerOwnerSeen {
		return // passed over without counting
	}
	w.seen[o.Owner]++
	w.counted++
	if expired(o, h) || w.kept[o.Owner] >= matchPerOwnerWindow {
		return
	}
	ok, verified := readyNow(o, w.strict)
	if !ok {
		return
	}
	w.kept[o.Owner]++
	w.verified[o.ID] = verified
	w.offers = append(w.offers, o)
}

// index is the search window bucketed for the ring search.
type index struct {
	// byWant: offers by wanted asset. Within a bucket, verified offers come
	// first, then lower minimums (an offer asking for more than anyone gives
	// cannot close a ring, so it must not take a place another could use),
	// then newer offers; at most matchPerOwnerBucket per owner and
	// matchMaxBucket in all.
	byWant map[string][]*Offer
	// byPair: the same, by wanted and given asset together, so the last
	// offer of a 3-offer ring is looked for only among offers that give
	// what the first one wants.
	byPair map[string][]*Offer
	// given: the largest amount given of each asset (1 for an item), so an
	// offer whose minimum nobody in the window meets costs no search steps.
	given map[string]int64
}

func pairKey(want, give ring.Asset) string { return assetBucketKey(want) + ">" + assetBucketKey(give) }

func indexByWant(w *window) *index {
	ix := &index{byWant: map[string][]*Offer{}, byPair: map[string][]*Offer{}, given: map[string]int64{}}
	all := make(map[string][]*Offer, len(w.offers))
	var keys []string
	for _, o := range w.offers {
		k := assetBucketKey(o.Want)
		if _, ok := all[k]; !ok {
			keys = append(keys, k)
		}
		all[k] = append(all[k], o)
		amt := o.Give.Amount
		if o.Give.Kind == ring.Item {
			amt = 1
		}
		if gk := assetBucketKey(o.Give); amt > ix.given[gk] {
			ix.given[gk] = amt
		}
	}
	for _, k := range keys {
		list := all[k]
		// Insertion sort: stable, and the window holds at most 50 offers.
		for i := 1; i < len(list); i++ {
			cur := list[i]
			j := i - 1
			for j >= 0 && bucketBefore(w, cur, list[j]) {
				list[j+1] = list[j]
				j--
			}
			list[j+1] = cur
		}
		perOwner := map[address]int{}
		perPairOwner := map[string]int{}
		for _, o := range list {
			if len(ix.byWant[k]) < matchMaxBucket && perOwner[o.Owner] < matchPerOwnerBucket {
				ix.byWant[k] = append(ix.byWant[k], o)
				perOwner[o.Owner]++
			}
			pk := pairKey(o.Want, o.Give)
			if len(ix.byPair[pk]) < matchMaxBucket && perPairOwner[pk+o.Owner.String()] < matchPerOwnerBucket {
				ix.byPair[pk] = append(ix.byPair[pk], o)
				perPairOwner[pk+o.Owner.String()]++
			}
		}
	}
	return ix
}

// satisfiable reports whether some offer in the window gives what o wants,
// at least o's minimum.
func (ix *index) satisfiable(o *Offer) bool {
	need := o.Want.Amount
	if o.Want.Kind == ring.Item {
		need = 1
	}
	return ix.given[assetBucketKey(o.Want)] >= need
}

func bucketBefore(w *window, a, b *Offer) bool {
	if w.verified[a.ID] != w.verified[b.ID] {
		return w.verified[a.ID]
	}
	return a.Want.Amount < b.Want.Amount
}

func assetBucketKey(a ring.Asset) string {
	return kindDigit(a.Kind) + "|" + a.Key + "|" + a.ID
}

// directMatch reports whether offer a can feed offer b directly (no GnoSwap).
func directMatch(a, b *Offer) bool {
	if a.ID == b.ID || a.Owner == b.Owner {
		return false
	}
	if !a.Give.SameAs(b.Want) {
		return false
	}
	if a.Give.Kind == ring.Fungible && a.Give.Amount < b.Want.Amount {
		return false
	}
	return true
}

func duplicateGivenItem(a, b, c *Offer) bool {
	if a.Give.Kind == ring.Item && (a.Give.SameAs(b.Give) || a.Give.SameAs(c.Give)) {
		return true
	}
	if b.Give.Kind == ring.Item && b.Give.SameAs(c.Give) {
		return true
	}
	return false
}

// canonicalRing rotates offs so the smallest offer ID comes first.
func canonicalRing(offs []*Offer) []*Offer {
	minIdx := 0
	for i := 1; i < len(offs); i++ {
		if offs[i].ID < offs[minIdx].ID {
			minIdx = i
		}
	}
	if minIdx == 0 {
		return offs
	}
	res := make([]*Offer, len(offs))
	for i := range offs {
		res[i] = offs[(minIdx+i)%len(offs)]
	}
	return res
}

func ringDedupKey(offs []*Offer) string {
	ids := make([]uint64, len(offs))
	for i, o := range offs {
		ids[i] = o.ID
	}
	return ring.FormatOfferIDs(ids)
}

func maxRingOfferID(offs []*Offer) uint64 {
	var m uint64
	for _, o := range offs {
		if o.ID > m {
			m = o.ID
		}
	}
	return m
}

func ringBefore(a, b []*Offer) bool {
	if len(a) != len(b) {
		return len(a) > len(b)
	}
	ma, mb := maxRingOfferID(a), maxRingOfferID(b)
	if ma != mb {
		return ma > mb
	}
	return a[0].ID < b[0].ID
}

package kylix

import (
	"gno.land/r/nym-gfanton001/gnotif/v1"
)

const (
	// OfferSettledEvent is emitted once per owner when their offer settles in
	// a ring, so gnotif can deliver a notification directly to each owner.
	OfferSettledEvent = "OfferSettled"

	offerSettledTriggerName = "offer_settled"
)

// EnableNotifications opens Kylix's gnotif handle and registers the
// OfferSettled notification trigger.
//
// Kylix keeps no admin: gnotif itself enforces that this call is signed with
// the namespace owner's account key (not a session key) and sent straight to
// Kylix. Calling it from init is avoided because gno test runs without
// namespace ownership and a gnotif outage must never block deployment.
//
// Only settled offers trigger notifications. A "matching offer posted"
// trigger is deliberately omitted: PostIntent does not check balances or
// approvals, so an attacker could post and cancel unapproved offers at near
// zero cost to spam another trader's notifications, and every PostIntent
// would have to scan the book.
func EnableNotifications(cur realm) {
	guard(cur)
	me := cur.Sub(gnotif.Subpath)
	h := gnotif.Open(cross(me))
	h.Set(cross(me), offerSettledTriggerName, gnotif.Trigger{
		Event: OfferSettledEvent,
		Param: "owner",
		Title: "Offer settled",
		Body:  "Offer #{id}: gave {gave}, received {received}",
		Link:  webPath(),
	})
}

package kylix

import (
	"chain"
	"chain/runtime"
	"strconv"
)

// PruneIntent deletes an expired offer. Anyone may call it, and the storage
// deposit the offer released goes to the caller. It reads only Kylix's own
// storage and calls no collection or token code, so pruning can never cost
// the caller more than the offer's own bytes, and no collection can make an
// expired offer impossible to prune. An offer that has not expired can only
// be cancelled by its owner or settled in a ring.
func PruneIntent(cur realm, id uint64) {
	guard(cur)
	o := mustOpen(id)
	if h := runtime.ChainHeight(); !expired(o, h) {
		panic("kylix: offer " + u64(id) + " has not expired; it can be pruned after height " +
			strconv.FormatInt(o.Expiry, 10))
	}
	removeOffer(o.ID)
	chain.Emit("IntentPruned", "id", u64(id), "owner", o.Owner.String(), "reason", "expired",
		"pruner", cur.Previous().Address().String())
}

package kylix

import (
	"chain/runtime"
	"html"
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nym-kylix000/ring/v0"
	"gno.land/r/sys/users"
)

const (
	pageOffers       = 50 // open offers per page, newest first
	maxFormAssetOpts = 50 // cap dropdown choices on the post page
	homeCollections  = 10 // collections listed on the home page
	pageCollections  = 50 // collections per page on the collections page
)

// Render serves Kylix's gnoweb pages:
//   - ""             Home: pitch, 3-step guide, ready rings, open offers, collections
//   - "offers/<id>"  Older open offers before <id>
//   - "offer/<id>"   One offer: details, readiness, approve step, matching rings, actions
//   - "ring/<ids>"   One ring (e.g. "ring/1,2,3"): large graph, swaps in words, readiness, settle
//   - "post"         Offer builder (approve address calculator + TxLinks + gnokey form)
//   - "collections"  Registered collections, official first (paged with ?after=<key>)
//   - "about"        How settlement works, custody model, GnoSwap fees, collection plug-in guide
//
// Home ("", "offers/<id>") never calls third-party collection code. It
// reads Kylix's own storage, token ledgers and official collections (to check
// that offers are still ready), and gno.land/r/sys/users for display names.
// Only a third-party item's own offer and ring pages, and settling, run that
// collection's code.
// Every string from a user or collection is sanitized for the slot it lands in.
func Render(path string) string {
	route, rawQuery, _ := strings.Cut(path, "?")
	switch {
	case route == "":
		return renderHome(0)
	case strings.HasPrefix(route, "offers/"):
		before, err := strconv.ParseUint(strings.TrimPrefix(route, "offers/"), 10, 64)
		if err != nil {
			return renderNotFound("No such page.")
		}
		return renderHome(before)
	case strings.HasPrefix(route, "offer/"):
		id, err := strconv.ParseUint(strings.TrimPrefix(route, "offer/"), 10, 64)
		if err != nil {
			return renderNotFound("No such offer.")
		}
		return renderOffer(id)
	case strings.HasPrefix(route, "ring/"):
		return renderRing(strings.TrimPrefix(route, "ring/"))
	case route == "post":
		return renderPost(rawQuery)
	case route == "collections":
		q, _ := url.ParseQuery(rawQuery)
		return renderCollections(q.Get("after"))
	case route == "about" || route == "how":
		return renderAbout()
	}
	return renderNotFound("Page not found.")
}

func renderNotFound(msg string) string {
	return "# Not found\n\n" + navBar("") + "\n\n" + msg + "\n\n[Back to Kylix](" + webPath() + ")\n"
}

func renderHome(before uint64) string {
	cache := map[string]string{}
	var sb strings.Builder
	sb.WriteString("# Kylix\n\n")
	sb.WriteString(navBar("home") + "\n\n")
	sb.WriteString("Swap tokens and collectibles in a circle: post what you offer and what you want, and when two to six offers close a ring, everyone swaps in one transaction — with nothing leaving your wallet until settlement.\n\n")

	sb.WriteString(gnoButton(webPath()+":post", "Post an offer", "success") + " ")
	sb.WriteString(gnoButton(demoWebPath(), "Get free demo assets", "outline") + " ")
	sb.WriteString(gnoButton(webPath()+":about", "How it works", "outline") + "\n\n")

	h := runtime.ChainHeight()
	var table string
	var next uint64

	if before == 0 {
		// One B+ tree pass feeds both the open offers table (the newest
		// pageOffers) and the ring search window, which may read further
		// back (see newestUnexpiredOffers).
		page := make([]*Offer, 0, pageOffers)
		w := newWindow(true)
		eachOfferBefore(0, func(o *Offer) bool {
			if len(page) == pageOffers && next == 0 {
				next = o.ID + 1
			}
			if len(page) < pageOffers {
				page = append(page, o)
			}
			w.consider(o, h)
			return len(page) == pageOffers && next != 0 && w.done()
		})

		sb.WriteString("<gno-columns>\n")
		sb.WriteString("<gno-frame>\n### 1. Approve\nAllow your offer's own address to move only the token amount or item you offer. Your assets stay in your wallet.\n</gno-frame>\n")
		sb.WriteString("<gno-columns-sep />\n")
		sb.WriteString("<gno-frame>\n### 2. Post your offer\nState what you give and the minimum you want back. You can cancel an open offer at any time.\n</gno-frame>\n")
		sb.WriteString("<gno-columns-sep />\n")
		sb.WriteString("<gno-frame>\n### 3. Settle the ring\nWhen two to six offers form a closed circle, anyone can settle it. Every swap happens together, or nothing moves.\n</gno-frame>\n")
		sb.WriteString("</gno-columns>\n\n")

		sb.WriteString("## Ready to settle\n\n")
		rings := findHomeRingsFrom(w)
		if len(rings) == 0 {
			sb.WriteString("No 2- or 3-offer direct ring of ready offers is open among the newest offers right now. [Post a matching offer](" + webPath() + ":post) or grab test tokens and a Relic from the [demo faucet](" +
				demoWebPath() + ").\n\n")
		} else {
			writeRingCards(&sb, rings, cache)
			sb.WriteString("Showing 2- and 3-offer direct rings found among the newest open offers, every offer checked ready just now. ")
			sb.WriteString("This page checks items of official collections only; rings with other collections' items are listed on those offers' own pages. ")
			sb.WriteString("Longer rings (up to 6 offers) and rings that need a GnoSwap swap are found by programs that search off chain.\n\n")
		}
		table = renderOfferRows(page, h, cache)
	} else {
		table, next = offerTableWithCache(before, pageOffers, cache)
	}

	sb.WriteString("## Open offers\n\n")
	if n := offers.Size(); n > 0 {
		sb.WriteString(strconv.Itoa(n) + " open " + pluralWord(n, "offer", "offers") + " in the book")
		if before != 0 {
			sb.WriteString(" · [← Newest offers](" + webPath() + ")")
		}
		sb.WriteString(".\n\n")
	}
	sb.WriteString(table)
	if next != 0 {
		sb.WriteString("\n[Older offers →](" + webPath() + ":offers/" + u64(next) + ")\n")
	}

	sb.WriteString("\n## Collections\n\n")
	sb.WriteString(collectionList())
	sb.WriteString("\n[Collection details & adapter trust guide →](" + webPath() + ":collections)\n\n")

	sb.WriteString("> [!TIP] Try Kylix in two minutes\n")
	sb.WriteString("> Claim free OBOL, DRACHMA and a Kylix Relic from the [demo faucet](" + demoWebPath() + "), then post an offer. ")
	sb.WriteString("Want browser alerts when your offers settle? Opt in on [gnotif](https://gnotif.xyz).\n")
	return sb.String()
}

func writeRingCards(sb *strings.Builder, rings [][]*Offer, cache map[string]string) {
	for i := 0; i < len(rings); i += 2 {
		sb.WriteString("<gno-columns>\n")
		writeOneRingCard(sb, rings[i], cache)
		if i+1 < len(rings) {
			sb.WriteString("<gno-columns-sep />\n")
			writeOneRingCard(sb, rings[i+1], cache)
		}
		sb.WriteString("</gno-columns>\n\n")
	}
}

func writeOneRingCard(sb *strings.Builder, r []*Offer, cache map[string]string) {
	ids := offerIDList(r)
	hops := make([]ring.GraphHop, len(r))
	for i, o := range r {
		hops[i] = ring.GraphHop{
			From:    ownerPlain(o.Owner, cache),
			Give:    graphAsset(o.Give),
			Note:    svgHint(assetHint(o.Give)),
			OfferID: o.ID,
		}
	}
	uri := ring.GraphDataURI(hops, ring.GraphThumb)
	sb.WriteString("<gno-frame>\n")
	sb.WriteString("### " + strconv.Itoa(len(r)) + "-offer ring (" + ids + ")\n\n")
	if uri != "" {
		sb.WriteString("![Ring " + ids + "](" + uri + ")\n\n")
	}
	for i, o := range r {
		next := r[(i+1)%len(r)]
		sb.WriteString("- " + ownerMarkdown(o.Owner, cache) + " gives **" + sanitize.InlineText(shortAsset(o.Give)) +
			"** to " + ownerMarkdown(next.Owner, cache) + "\n")
	}
	// The button leads to the ring page, which shows every asset's full key
	// and the settle command, rather than settling from here.
	sb.WriteString("\n" + gnoButton(webPath()+":ring/"+ids, "Review and settle", "success") + "\n")
	sb.WriteString("</gno-frame>\n")
}

// offerTable renders up to limit open offers with id < before (all when
// before is 0), newest first, as a markdown table. next is the before value
// for the following page, or 0 when there is none.
func offerTable(before uint64, limit int) (md string, next uint64) {
	return offerTableWithCache(before, limit, map[string]string{})
}

func offerTableWithCache(before uint64, limit int, cache map[string]string) (md string, next uint64) {
	h := runtime.ChainHeight()
	page := make([]*Offer, 0, limit)
	eachOfferBefore(before, func(o *Offer) bool {
		if len(page) == limit {
			next = o.ID + 1 // an older offer exists; the next page starts at it
			return true
		}
		page = append(page, o)
		return false
	})
	if len(page) == 0 && before != 0 {
		// A page past the oldest offer: the book may still hold newer ones.
		return "No older open offers.\n", 0
	}
	return renderOfferRows(page, h, cache), next
}

func renderOfferRows(page []*Offer, h int64, cache map[string]string) string {
	if len(page) == 0 {
		return "No open offers yet. [Post the first offer](" + webPath() + ":post).\n"
	}
	var sb strings.Builder
	sb.WriteString("| Offer | Owner | Gives | Wants | Expiry |\n|---|---|---|---|---|\n")
	for _, o := range page {
		sb.WriteString("| [" + u64(o.ID) + "](" + webPath() + ":offer/" + u64(o.ID) + ") | ")
		sb.WriteString(ownerTableCell(o.Owner, cache) + " | ")
		sb.WriteString(sanitize.TableCell(shortAsset(o.Give)) + " | ")
		sb.WriteString(sanitize.TableCell(shortWant(o.Want)) + " | ")
		sb.WriteString(expiryString(o, h) + " |\n")
	}
	return sb.String()
}

// collectionList renders the registered collections as a markdown list,
// official ones first, at most homeCollections of them, with a link to the
// collections page for the rest.
func collectionList() string {
	if collections.Size() == 0 {
		return "No collections registered.\n"
	}
	var sb strings.Builder
	keys, more := collectionKeys("", homeCollections)
	for _, key := range keys {
		c := getCollection(key)
		sb.WriteString("- **" + sanitize.InlineText(c.name) + "** (" + sanitize.InlineCode(key) + "): " +
			collectionLabel(key) + "\n")
	}
	if more {
		sb.WriteString("- … and " + strconv.Itoa(collections.Size()-len(keys)) + " more on the [collections page](" + webPath() + ":collections)\n")
	}
	return sb.String()
}

// collectionKeys lists up to limit collection keys, official ones (under
// Kylix's own namespace) first, then the others in key order, starting
// after the key after ("" for the start). more reports whether any follow.
func collectionKeys(after string, limit int) (keys []string, more bool) {
	ns := namespacePrefix()
	type span struct{ start, end string }
	spans := []span{{"", ""}}
	if ns != "" {
		nsEnd := ns + "\xff"
		spans = []span{{ns, nsEnd}, {"", ns}, {nsEnd, ""}}
	}
	in := func(sp span, k string) bool { return k >= sp.start && (sp.end == "" || k < sp.end) }
	from := 0
	if after != "" {
		for i, sp := range spans {
			if in(sp, after) {
				from = i
				spans[i].start = after + "\x00"
				break
			}
		}
	}
	for _, sp := range spans[from:] {
		collections.Iterate(sp.start, sp.end, func(key string, _ any) bool {
			if len(keys) >= limit {
				more = true
				return true
			}
			keys = append(keys, key)
			return false
		})
		if more {
			break
		}
	}
	return keys, more
}

// collectionKind is a collection's trust label, the same words on every
// page, in ring captions and in the export: "official collection" or
// "official adapter" for one registered under Kylix's own namespace,
// "third-party collection" or "third-party adapter" for any other.
// Official is a label, not a gate: anyone may register a collection under
// their own namespace, and pick any display name.
func collectionKind(key string) string {
	c := getCollection(key)
	switch {
	case c == nil:
		return "unregistered"
	case c.target == "" && IsOfficial(key):
		return "official collection"
	case c.target == "":
		return "third-party collection"
	case IsOfficial(key):
		return "official adapter"
	}
	return "third-party adapter"
}

// collectionLabel is collectionKind, naming an adapter's target.
func collectionLabel(key string) string {
	c := getCollection(key)
	if c == nil || c.target == "" {
		return collectionKind(key)
	}
	return collectionKind(key) + " for " + sanitize.InlineText(c.target)
}

func wantString(a ring.Asset) string {
	if a.Kind == ring.Fungible {
		return "at least " + a.String()
	}
	return a.String()
}

func shortWant(a ring.Asset) string {
	if a.Kind == ring.Fungible {
		return "at least " + shortAsset(a)
	}
	return shortAsset(a)
}

// shortAsset names an asset in words with a hint of the realm it lives in,
// because symbols and display names are chosen by whoever deploys: anyone
// can make a token called GNS or a collection called Kylix Relics. Tokens:
// "100 OBOL (nym-kylix000/kylixdemo)". Items carry their collection's label
// too: "Kylix Relics #relic-2 (official collection, nym-kylix000/kylixdemo)".
// Pages where someone decides to sign show the full key as well (keyedAsset).
func shortAsset(a ring.Asset) string {
	if a.Kind == ring.Item {
		return graphAsset(a) + " (" + collectionKind(a.Key) + ", " + realmHint(a.Key) + ")"
	}
	return graphAsset(a) + " (" + realmHint(tokenRealmPath(a.Key)) + ")"
}

// keyedAsset is for the pages where someone decides: the short name in bold,
// then the label and the full key in code. Markdown, already escaped.
func keyedAsset(a ring.Asset, atLeast bool) string {
	name := graphAsset(a)
	if atLeast && a.Kind == ring.Fungible {
		name = "at least " + name
	}
	if a.Kind == ring.Item {
		return "**" + sanitize.InlineText(name) + "** (" + collectionKind(a.Key) + " " + sanitize.InlineCode(a.Key) + ")"
	}
	return "**" + sanitize.InlineText(name) + "** (token " + sanitize.InlineCode(a.Key) + ")"
}

// graphAsset is the bare name, for the ring pictures, which draw the realm
// hint (assetHint) on a second line.
func graphAsset(a ring.Asset) string {
	if a.Kind == ring.Item {
		if name := CollectionName(a.Key); name != "" {
			return name + " #" + a.ID
		}
		return a.Key + "#" + a.ID
	}
	return strconv.FormatInt(a.Amount, 10) + " " + shortTokenSymbol(a.Key)
}

// assetHint is the realm hint of an asset: its token realm or collection.
func assetHint(a ring.Asset) string {
	if a.Kind == ring.Item {
		return realmHint(a.Key)
	}
	return realmHint(tokenRealmPath(a.Key))
}

// svgHint fits a realm hint into a ring picture without making it
// ambiguous. The namespace is what tells owners apart: a name namespace is
// kept whole, and only a namespace that is a valid address (checked as an
// address, not by its look: a registered name may start with "g1") keeps its
// first 8 and last 6 characters, the end being checksum, so matching both
// means grinding about 2^60 keys. Only the rest of the path, which the same
// owner controls anyway, is shortened. A hint is then at most 64 + 15 runes,
// under the picture's 80-rune limit for notes.
func svgHint(hint string) string {
	ns, rest, _ := strings.Cut(hint, "/")
	if address(ns).IsValid() {
		ns = ns[:8] + "…" + ns[len(ns)-6:]
	}
	if rest == "" {
		return ns
	}
	if r := []rune(rest); len(r) > 14 {
		rest = "…" + string(r[len(r)-13:])
	}
	return ns + "/" + rest
}

// realmHint shortens a realm path to what identifies it: the namespace and
// the rest of the path, without "gno.land/r/". The namespace comes first,
// and only its owner can deploy under it, so a look-alike cannot share the
// hint's beginning: "gnoland/wugnot" vs "evil/gnoland/wugnot".
func realmHint(pkgPath string) string {
	s := strings.TrimPrefix(pkgPath, "gno.land/")
	s = strings.TrimPrefix(s, "r/")
	if s == "" {
		return pkgPath
	}
	return s
}

func shortTokenSymbol(key string) string {
	if i := strings.LastIndex(key, "."); i >= 0 && i+1 < len(key) {
		return key[i+1:]
	}
	return key
}

func tokenRealmPath(key string) string {
	if i := strings.LastIndex(key, "."); i > 0 {
		return key[:i]
	}
	return ""
}

func assetNote(a ring.Asset) string {
	if a.Kind != ring.Item {
		return ""
	}
	c := getCollection(a.Key)
	if c == nil {
		return ""
	}
	return " (" + sanitize.InlineText(c.name) + ", " + collectionLabel(a.Key) + ")"
}

// expiryString is the short form for tables: "in about 3 days" or
// "expired".
func expiryString(o *Offer, h int64) string {
	if expired(o, h) {
		return "expired"
	}
	return blocksAhead(o.Expiry - h)
}

// expiryLong adds the block height: "in about 3 days (block height 1234)".
func expiryLong(o *Offer, h int64) string {
	if expired(o, h) {
		return "expired at block height " + strconv.FormatInt(o.Expiry, 10)
	}
	return blocksAhead(o.Expiry-h) + " (block height " + strconv.FormatInt(o.Expiry, 10) + ")"
}

// blocksAhead says roughly how long n blocks take, assuming BlocksPerDay,
// rounded to the nearest hour or day (a 7-day offer a few blocks old still
// reads "in about 7 days").
func blocksAhead(n int64) string {
	const perHour = BlocksPerDay / 24
	hours := (n + perHour/2) / perHour
	days := (n + BlocksPerDay/2) / BlocksPerDay
	switch {
	case hours < 1:
		return "in less than an hour"
	case hours == 1:
		return "in about an hour"
	case hours < 24:
		return "in about " + strconv.FormatInt(hours, 10) + " hours"
	case days == 1:
		return "in about a day"
	}
	return "in about " + strconv.FormatInt(days, 10) + " days"
}

// expiryInputHint explains PostIntent's expiry argument on the post forms.
func expiryInputHint() string {
	h := runtime.ChainHeight()
	return "Expiry block height: 0 for the default of about 7 days, at most about 30 days ahead (now " +
		strconv.FormatInt(h, 10) + ", latest " + strconv.FormatInt(h+MaxExpiryBlocks, 10) + ")"
}

// webPath is this realm's gnoweb path, e.g. "/r/nym-kylix000/kylix".
func webPath() string {
	return pkgWebPath(selfPath)
}

func pkgWebPath(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		return pkgPath[i:]
	}
	return pkgPath
}

func demoRealmPath() string {
	ns := namespacePrefix()
	if ns == "" {
		return ""
	}
	return ns + "kylixdemo"
}

func demoWebPath() string {
	p := demoRealmPath()
	if p == "" {
		return "/r/nym-kylix000/kylixdemo"
	}
	return pkgWebPath(p)
}

func navBar(active string) string {
	items := []struct {
		key, label, href string
	}{
		{"home", "Home", webPath()},
		{"post", "Post an offer", webPath() + ":post"},
		{"collections", "Collections", webPath() + ":collections"},
		{"about", "How it works", webPath() + ":about"},
		{"demo", "Demo faucet", demoWebPath()},
	}
	var parts []string
	for _, it := range items {
		if it.key == active {
			parts = append(parts, "**"+it.label+"**")
		} else {
			parts = append(parts, "["+it.label+"]("+it.href+")")
		}
	}
	return strings.Join(parts, " · ")
}

func lookupUsername(addr address, cache map[string]string) string {
	s := addr.String()
	if name, ok := cache[s]; ok {
		return name
	}
	var name string
	if u := users.ResolveAddress(addr); u != nil {
		name = sanitize.UserName(u.Name())
	}
	cache[s] = name
	return name
}

func ownerPlain(addr address, cache map[string]string) string {
	if name := lookupUsername(addr, cache); name != "" {
		return "@" + name
	}
	return shortAddr(addr)
}

func ownerMarkdown(addr address, cache map[string]string) string {
	if name := lookupUsername(addr, cache); name != "" {
		return "[@" + sanitize.InlineText(name) + "](/u/" + url.PathEscape(name) + ")"
	}
	return "`" + shortAddr(addr) + "`"
}

func ownerFullMarkdown(addr address, cache map[string]string) string {
	if name := lookupUsername(addr, cache); name != "" {
		return "[@" + sanitize.InlineText(name) + "](/u/" + url.PathEscape(name) + ") (`" + addr.String() + "`)"
	}
	return "`" + addr.String() + "`"
}

func ownerTableCell(addr address, cache map[string]string) string {
	if name := lookupUsername(addr, cache); name != "" {
		return "[@" + sanitize.TableCell(name) + "](/u/" + url.PathEscape(name) + ")"
	}
	return "`" + shortAddr(addr) + "`"
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 13 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

func offerIDList(offs []*Offer) string {
	ids := make([]uint64, len(offs))
	for i, o := range offs {
		ids[i] = o.ID
	}
	return ring.FormatOfferIDs(ids)
}

// txLink builds a GnoConnect / gnoweb $help transaction link with query-escaped
// argument pairs (k1, v1, k2, v2, ...).
func txLink(realmWebPath, fn string, kv ...string) string {
	var sb strings.Builder
	sb.WriteString(realmWebPath)
	sb.WriteString("$help&func=")
	sb.WriteString(url.QueryEscape(fn))
	for i := 0; i+1 < len(kv); i += 2 {
		sb.WriteByte('&')
		sb.WriteString(url.QueryEscape(kv[i]))
		sb.WriteByte('=')
		sb.WriteString(url.QueryEscape(kv[i+1]))
	}
	return sb.String()
}

func gnoButton(href, label, variant string) string {
	s := `<gno-button href="` + attrEscape(href) + `" label="` + attrEscape(label) + `"`
	if variant != "" {
		s += ` variant="` + attrEscape(variant) + `"`
	}
	return s + ` />`
}

func gnoInput(name, placeholder, value string, required, readonly bool) string {
	s := `<gno-input name="` + attrEscape(name) + `" placeholder="` + attrEscape(placeholder) + `"`
	if value != "" {
		s += ` value="` + attrEscape(value) + `"`
	}
	if required {
		s += ` required="true"`
	}
	if readonly {
		s += ` readonly="true"`
	}
	return s + " />\n"
}

func gnoSelectOpt(name, value, description string, selected, required bool) string {
	s := `<gno-select name="` + attrEscape(name) + `" value="` + attrEscape(value) + `"`
	if description != "" {
		s += ` description="` + attrEscape(description) + `"`
	}
	if selected {
		s += ` selected="true"`
	}
	if required {
		s += ` required="true"`
	}
	return s + " />\n"
}

func attrEscape(s string) string {
	return html.EscapeString(sanitize.StripBidiAndZeroWidth(s))
}

func pluralWord(n int, singular, plural string) string {
	if n == 1 {
		return singular
	}
	return plural
}

