// Package sinopia3 is the Kylix adapter for Sinopia3 art
// (gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/core), which
// knows nothing of Kylix. Item ids are "<collection id>/<token id>", both
// positive decimal numbers without leading zeros.
//
// Move crosses into the core as this realm's sub-identity k/<slot address>,
// so an owner's approval to SpenderFor(slot) serves exactly one offer.
//
// What an item id fixes. Once a collection is Final its art is a pure
// function of the collection's engine, its parameters and the token's seed,
// none of which the owner can change. Two cases are refused, because the
// value could change between posting and settlement while the id stays the
// same, so Approved answers false and Kylix reports the item as not ready:
//   - a collection that is not Final yet: its tokens are unrevealed, and its
//     lock hook vetoes every move anyway;
//   - a collection whose engine is "living": its art depends on the token's
//     transfer history, which the owner can reset by moving the token away
//     and back before settlement;
//   - a collection whose engine nobody has checked: an engine is code in its
//     own realm, and a realm with state could change what it draws even when
//     its manifest says it is not living. Accepted are engines that the
//     Sinopia3 admin has marked "reviewed", and the engines listed in
//     statelessEngines, whose realms Kylix has read: they keep no state and
//     draw only from an immutable p/ package and the token's seed.
//
// No function here panics on an unknown or malformed id: OwnerOf answers
// the empty address and Approved false, so such an offer is simply never
// ready, never blocks a batch query, and expires like any other.
package sinopia3

import (
	"chain"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	"gno.land/p/nt/grc721/v0"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/core"
	"gno.land/r/nym-kylix000/kylix"
)

const target = "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/core"

// statelessEngines are engines Kylix has reviewed itself (see the package
// comment). Genesis: the realm holds one constant and delegates Render and
// Traits to gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/art/genesis/v1,
// which reads only the seed and params, never the token's moves or heights.
var statelessEngines = []string{
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/engines/genesis",
}

var selfPath string

func init(cur realm) {
	selfPath = cur.PkgPath()
	kylix.RegisterAdapter(cross(cur), target, "Sinopia3 Art", Move, OwnerOf)
	kylix.RegisterApprovalCheck(cross(cur), Approved)
}

// SpenderFor is the address an owner approves in the core for the offer
// whose Kylix slot is slot: core.Approve(cid, tid, SpenderFor(slot)).
func SpenderFor(slot address) address {
	return chain.DerivePkgSubAddr(selfPath, "k/"+slot.String())
}

// Move is the Kylix MoveFn. It refuses what Approved refuses, so the rule
// holds even for a caller that skipped Kylix's checks.
func Move(cur realm, from, to address, itemID string) error {
	cid, tid, ok := parseID(itemID)
	if !ok {
		return errors.New("sinopia3 adapter: item id must be <collection id>/<token id>")
	}
	if why := unmovable(cid, tid); why != "" {
		return errors.New("sinopia3 adapter: " + why)
	}
	if !singleApproval(cid, tid, SpenderFor(cur.Previous().Address())) {
		return errors.New("sinopia3 adapter: " + notSingle)
	}
	sub := cur.Sub("k/" + cur.Previous().Address().String())
	core.TransferFrom(cross(sub), cid, tid, from, to)
	return nil
}

// notSingle explains why an approval for all of a collection is refused: the
// transfer clears a single-token approval, whose deposit is then refunded to
// the settler, but leaves an approval for all in place, while the settler
// still pays for the receiver's new entries.
const notSingle = "approve this offer's address for the token itself; an approval for all tokens is not used, because the move does not consume it"

// singleApproval reports whether spender is approved for exactly this token.
func singleApproval(cid, tid string, spender address) bool {
	a, err := core.Token(cid).GetApproved(grc721.TokenID(tid))
	return err == nil && a != "" && a == spender
}

// OwnerOf is the Kylix OwnerFn: the owner, or the empty address for an
// unknown or malformed id.
func OwnerOf(id kylix.ItemID) address {
	cid, tid, ok := parseID(string(id))
	if !ok {
		return ""
	}
	owner, err := core.OwnerOf(cid, tid)
	if err != nil {
		return ""
	}
	return owner
}

// Approved is the Kylix ApprovedFn: spender is approved for this one token
// (an approval for all is not used; see notSingle), and the token's value is
// fixed (see the package comment).
func Approved(id kylix.ItemID, spender address) bool {
	cid, tid, ok := parseID(string(id))
	return ok && unmovable(cid, tid) == "" && singleApproval(cid, tid, spender)
}

// unmovable returns why the token cannot be offered now, or "". cid must
// already be a known collection (parseID checks it).
func unmovable(cid, tid string) string {
	info := core.Info(cid)
	if info.State != types.StateFinal || core.TokenSeed(cid, tid) == "" {
		return "the collection is not final yet, so its art is unrevealed and its tokens cannot move"
	}
	if core.EngineManifest(info.EngineID).Living {
		return "the art of a living engine changes with its transfer history, which the owner can reset before settlement"
	}
	if !engineReviewed(info.EngineID) {
		return "the collection's engine is not reviewed (status " + core.EngineStatus(info.EngineID) +
			"), so its art could change before settlement"
	}
	return ""
}

func engineReviewed(id string) bool {
	for _, e := range statelessEngines {
		if e == id {
			return true
		}
	}
	return core.EngineStatus(id) == "reviewed"
}

// parseID splits "<cid>/<tid>" and accepts it only if both parts are
// canonical positive numbers and the collection exists, so that no core
// function this adapter calls can panic on it.
func parseID(itemID string) (cid, tid string, ok bool) {
	i := strings.IndexByte(itemID, '/')
	if i <= 0 || i >= len(itemID)-1 {
		return "", "", false
	}
	cid, tid = itemID[:i], itemID[i+1:]
	n, ok := canonicalID(cid)
	if !ok || n > core.CollectionCount() {
		return "", "", false
	}
	if _, ok := canonicalID(tid); !ok {
		return "", "", false
	}
	return cid, tid, true
}

// canonicalID accepts 1 to 18 digits with no leading zero, the format the
// core's own parser accepts without panicking.
func canonicalID(s string) (int64, bool) {
	if len(s) == 0 || len(s) > 18 || s[0] == '0' {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	n, err := strconv.ParseInt(s, 10, 64)
	return n, err == nil
}

// Package nsnft is the Kylix adapter for MNS name NFTs
// (gno.land/r/nym-mnsrehearsal001/nsnft/v2), which knows nothing of Kylix.
// Item ids are MNS token ids, "<label>*<domain>", e.g. "alice*gnoland".
//
// Move crosses into nsnft as this realm's sub-identity k/<slot address>, so
// an owner's approval to SpenderFor(slot) serves exactly one offer.
//
// What an item id fixes. An MNS token is a lease on a name: the ledger
// (nsnft) holds ownership and nothing else, and the lease lives in the
// registry (nsdata/v2). nsnft.TransferFrom deliberately does not check the
// lease, so a lapsed name still moves, and a buyer would receive a name
// nobody can resolve and anyone may soon reclaim. So, like MNS's own
// marketplace, this adapter asks the registry, and refuses a name, in both
// Approved and Move, unless all of these hold:
//   - the id is "<label>*<domain>" with both parts present;
//   - nsdata/v2 is still a registry nsnft trusts, and it has a record for
//     the name;
//   - the name is not frozen and carries no registry hold (a free-tier name
//     is held until it is paid for);
//   - the lease is valid now and has at least MinLeaseLeft (31 days) to run,
//     which is longer than any Kylix offer can stay open, so a name that
//     passes when the offer is posted cannot lapse before the offer expires;
//   - the owner approved this offer's address for this one name: an
//     approval for all names is not used, because the move does not consume
//     it (see notSingle).
//
// No function here panics on an unknown or malformed id: OwnerOf answers
// the empty address and Approved false.
package nsnft

import (
	"chain"
	"errors"
	"strconv"
	"strings"
	"time"

	"gno.land/r/nym-kylix000/kylix"
	"gno.land/r/nym-mnsrehearsal001/nsdata/v2"
	"gno.land/r/nym-mnsrehearsal001/nsnft/v2"
)

const (
	target   = "gno.land/r/nym-mnsrehearsal001/nsnft/v2"
	registry = "gno.land/r/nym-mnsrehearsal001/nsdata/v2"

	// MinLeaseLeft is the lease, in seconds, a name must have left to be
	// offered or moved: one day more than the longest an offer can stay
	// open (kylix.MaxExpiryBlocks at five-second blocks). A name with less
	// than this left is refused; one with exactly this much passes.
	MinLeaseLeft = (kylix.MaxExpiryBlocks/kylix.BlocksPerDay + 1) * 24 * 60 * 60
)

var selfPath string

func init(cur realm) {
	selfPath = cur.PkgPath()
	kylix.RegisterAdapter(cross(cur), target, "MNS Names (v2)", Move, OwnerOf)
	kylix.RegisterApprovalCheck(cross(cur), Approved)
}

// SpenderFor is the address an owner approves in nsnft for the offer whose
// Kylix slot is slot: nsnft.Approve(SpenderFor(slot), "<label>*<domain>").
func SpenderFor(slot address) address {
	return chain.DerivePkgSubAddr(selfPath, "k/"+slot.String())
}

// Move is the Kylix MoveFn. It refuses what Approved refuses, so the rule
// holds even for a caller that skipped Kylix's checks.
func Move(cur realm, from, to address, itemID string) error {
	if why := Unmovable(itemID); why != "" {
		return errors.New("mns adapter: " + why)
	}
	if !singleApproval(itemID, SpenderFor(cur.Previous().Address())) {
		return errors.New("mns adapter: " + notSingle)
	}
	sub := cur.Sub("k/" + cur.Previous().Address().String())
	nsnft.TransferFrom(cross(sub), from, to, itemID)
	return nil
}

// OwnerOf is the Kylix OwnerFn: the ledger's owner, or the empty address.
func OwnerOf(id kylix.ItemID) address { return nsnft.OwnerOf(string(id)) }

// Approved is the Kylix ApprovedFn: spender is approved for this one name
// (an approval for all is not used; see notSingle), and its lease will
// outlast the offer.
func Approved(id kylix.ItemID, spender address) bool {
	name := string(id)
	return Unmovable(name) == "" && singleApproval(name, spender)
}

// notSingle explains why an approval for all names is refused: the transfer
// clears a single-name approval, whose deposit is then refunded to the
// settler, but leaves an approval for all in place, while the settler still
// pays for the receiver's new entries.
const notSingle = "approve this offer's address for the name itself; an approval for all names is not used, because the move does not consume it"

func singleApproval(name string, spender address) bool {
	a := nsnft.GetApproved(name)
	return a != "" && a == spender
}

// Unmovable returns why the name cannot be offered or moved now, or "".
func Unmovable(tid string) string {
	label, domain, ok := splitTokenID(tid)
	if !ok {
		return "an MNS item id is <label>*<domain>"
	}
	if nsnft.IsLocked(tid) {
		return "the registry holds " + tid + " (frozen, or a free-tier name not yet paid for)"
	}
	if !nsnft.IsTrusted(chain.PackageAddress(registry)) {
		return "the MNS registry this adapter reads is no longer trusted by the ledger"
	}
	exists := nsdata.NameExists(label, domain)
	var frozen, valid bool
	var expires int64
	if exists {
		_, _, expires, _, frozen, _ = nsdata.GetNameInfo(label, domain)
		valid = nsdata.IsNameValid(label, domain)
	}
	return leaseProblem(tid, exists, frozen, valid, expires, time.Now().Unix())
}

// leaseProblem is the lease decision, given the registry's answers for tid:
// whether it has a record, whether the name is frozen, whether the
// registry calls the lease valid now, and when it ends (unix seconds).
func leaseProblem(tid string, exists, frozen, valid bool, expires, now int64) string {
	switch {
	case !exists:
		return "the registry has no record of " + tid
	case frozen:
		return tid + " is frozen"
	case !valid:
		return "the lease on " + tid + " has expired"
	case expires-now < MinLeaseLeft:
		return "the lease on " + tid + " has less than " + strconv.Itoa(MinLeaseLeft/86400) +
			" days left, so it could end before an offer expires; renew it first"
	}
	return ""
}

// splitTokenID splits "<label>*<domain>": exactly one '*', both parts
// present.
func splitTokenID(tid string) (label, domain string, ok bool) {
	i := strings.IndexByte(tid, '*')
	if i <= 0 || i >= len(tid)-1 || strings.IndexByte(tid[i+1:], '*') >= 0 {
		return "", "", false
	}
	return tid[:i], tid[i+1:], true
}

// Package poll is a simple on-chain voting realm: anyone can create a poll,
// each address gets exactly one vote per poll, and only the poll creator
// can close it. Built for the Gnome Tavern Hackathon.
package poll

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Limits keep on-chain state bounded.
const (
	maxQuestionLen = 200
	maxOptionLen   = 100
	maxOptions     = 10
	minOptions     = 2
)

type poll struct {
	question string
	options  []string
	creator  address
	closed   bool
	votes    []int
	voters   map[address]bool
}

var polls []poll

// CreatePoll creates a new poll and returns its ID. The caller becomes the
// poll creator and is the only one who can close it. Options are given as a
// single "|" separated string (e.g. "Poll|Token|Bounty") because gnokey and
// gnoweb can only pass scalar arguments to realm functions — a []string
// argument cannot be supplied from the CLI.
func CreatePoll(cur realm, question string, options string) (int, error) {
	question = strings.TrimSpace(question)
	if question == "" {
		return -1, errors.New("question must not be empty")
	}
	if len(question) > maxQuestionLen {
		return -1, errors.New("question too long")
	}
	opts := strings.Split(options, "|")
	if len(opts) < minOptions || len(opts) > maxOptions {
		return -1, errors.New("poll needs 2 to 10 options")
	}
	for i, opt := range opts {
		opts[i] = strings.TrimSpace(opt)
		if opts[i] == "" {
			return -1, errors.New("options must not be empty")
		}
		if len(opts[i]) > maxOptionLen {
			return -1, errors.New("option too long")
		}
	}
	creator := cur.Previous().Address()
	p := poll{
		question: question,
		options:  opts,
		creator:  creator,
		votes:    make([]int, len(opts)),
		voters:   make(map[address]bool),
	}
	polls = append(polls, p)
	return len(polls) - 1, nil
}

// Vote casts one vote for an option in a poll. Each address may vote only
// once per poll, and closed polls reject votes.
func Vote(cur realm, pollID int, optionIndex int) error {
	if pollID < 0 || pollID >= len(polls) {
		return errors.New("poll not found")
	}
	p := &polls[pollID]
	if p.closed {
		return errors.New("poll is closed")
	}
	if optionIndex < 0 || optionIndex >= len(p.options) {
		return errors.New("option out of range")
	}
	caller := cur.Previous().Address()
	if p.voters[caller] {
		return errors.New("address has already voted in this poll")
	}
	p.voters[caller] = true
	p.votes[optionIndex]++
	return nil
}

// ClosePoll closes a poll. Only the poll creator may close it.
func ClosePoll(cur realm, pollID int) error {
	if pollID < 0 || pollID >= len(polls) {
		return errors.New("poll not found")
	}
	p := &polls[pollID]
	if p.closed {
		return errors.New("poll is already closed")
	}
	if cur.Previous().Address() != p.creator {
		return errors.New("only the poll creator can close it")
	}
	p.closed = true
	return nil
}

// PollCount returns how many polls exist.
func PollCount() int {
	return len(polls)
}

// Tally returns a copy of the vote counts per option for a poll.
func Tally(pollID int) ([]int, error) {
	if pollID < 0 || pollID >= len(polls) {
		return nil, errors.New("poll not found")
	}
	return append([]int(nil), polls[pollID].votes...), nil
}

// GetPoll returns a poll's question, options, creator and closed status.
func GetPoll(pollID int) (question string, options []string, creator address, closed bool, err error) {
	if pollID < 0 || pollID >= len(polls) {
		return "", nil, address(""), false, errors.New("poll not found")
	}
	p := polls[pollID]
	return p.question, append([]string(nil), p.options...), p.creator, p.closed, nil
}

// Render shows all polls and their current tallies as markdown.
// User-supplied text is escaped so it cannot break out of the markdown.
func Render(_ string) string {
	out := "# Polls\n\n"
	if len(polls) == 0 {
		out += "No polls yet. Create one with CreatePoll.\n"
		return out
	}
	for i, p := range polls {
		status := "open"
		if p.closed {
			status = "closed"
		}
		out += "## " + strconv.Itoa(i+1) + ". " + sanitize.InlineText(p.question) + " (" + status + ")\n\n"
		for j, opt := range p.options {
			out += "- " + sanitize.InlineText(opt) + ": " + strconv.Itoa(p.votes[j]) + " vote(s)\n"
		}
		out += "\n"
	}
	return out
}

package poll

import (
	"strings"
	"testing"

	"chain"
)

// Deterministic test addresses, derived from fixed package paths.
func alice() address { return chain.PackageAddress("gno.land/r/test/alice") }
func bob() address   { return chain.PackageAddress("gno.land/r/test/bob") }
func carol() address { return chain.PackageAddress("gno.land/r/test/carol") }

// reset clears realm state. gno test runs all test functions in this file
// against the same store, so each test must start from a clean slate
// (same pattern as the counter example resetting its counter).
func reset() {
	polls = nil
}

// NOTE: testing.SetRealm is frame-scoped: it must be called in the same
// function frame that performs the cross(cur) call, otherwise the crossing
// function sees the test realm instead of the simulated user. That is why
// the helpers below each do SetRealm + the cross call in their own body
// instead of delegating SetRealm to a separate helper.

func createPollAs(cur realm, t *testing.T, creator address, question string, options string) int {
	testing.SetRealm(testing.NewUserRealm(creator))
	id, err := CreatePoll(cross(cur), question, options)
	if err != nil {
		t.Fatalf("CreatePoll failed: %v", err)
	}
	return id
}

func voteAs(cur realm, t *testing.T, voter address, pollID int, optionIndex int) error {
	testing.SetRealm(testing.NewUserRealm(voter))
	return Vote(cross(cur), pollID, optionIndex)
}

func closeAs(cur realm, t *testing.T, closer address, pollID int) error {
	testing.SetRealm(testing.NewUserRealm(closer))
	return ClosePoll(cross(cur), pollID)
}

func TestCreatePoll(cur realm, t *testing.T) {
	reset()
	id := createPollAs(cur, t, alice(), "Best Gno project?", "Poll|Token|Bounty")
	if id != 0 {
		t.Fatalf("expected first poll id 0, got %d", id)
	}
	if PollCount() != 1 {
		t.Fatalf("expected 1 poll, got %d", PollCount())
	}
	question, options, creator, closed, err := GetPoll(id)
	if err != nil {
		t.Fatalf("GetPoll failed: %v", err)
	}
	if question != "Best Gno project?" {
		t.Fatalf("unexpected question: %q", question)
	}
	if len(options) != 3 || options[0] != "Poll" || options[2] != "Bounty" {
		t.Fatalf("unexpected options: %v", options)
	}
	if creator != alice() {
		t.Fatalf("expected creator alice, got %s", creator.String())
	}
	if closed {
		t.Fatalf("new poll should be open")
	}
	tally, err := Tally(id)
	if err != nil {
		t.Fatalf("Tally failed: %v", err)
	}
	for i, v := range tally {
		if v != 0 {
			t.Fatalf("expected 0 votes for option %d, got %d", i, v)
		}
	}
}

func TestCreatePollValidation(cur realm, t *testing.T) {
	reset()
	if _, err := createPollAsExpectErr(cur, t, alice(), "", "A|B"); err == nil {
		t.Fatalf("expected error for empty question")
	}
	if _, err := createPollAsExpectErr(cur, t, alice(), "Q?", "Only one"); err == nil {
		t.Fatalf("expected error for a single option")
	}
	if _, err := createPollAsExpectErr(cur, t, alice(), "Q?", "A|"); err == nil {
		t.Fatalf("expected error for an empty option")
	}
	if PollCount() != 0 {
		t.Fatalf("expected 0 polls after rejected creates, got %d", PollCount())
	}
}

// createPollAsExpectErr is createPollAs for cases that must fail: it returns
// the error instead of failing the test.
func createPollAsExpectErr(cur realm, t *testing.T, creator address, question string, options string) (int, error) {
	testing.SetRealm(testing.NewUserRealm(creator))
	return CreatePoll(cross(cur), question, options)
}

