	if len(parts) == 0 || parts[0] == "summary" {
		return ufmt.Sprintf(
			`{"protocol":%s,"chainId":%s,"height":%d,"vaultBalanceUgnot":%d,"services":%d,"activePasses":%d,"passes":%d,"subscriptions":%d,"settlements":%d,"receipts":%d,"totalDepositedUgnot":%d,"totalSettledUgnot":%d,"totalX402AnchoredUgnot":%d,"totalSubRevenueUgnot":%d,"totalRefundedUgnot":%d}`,
			jsonEscape(ptollgate.ProtocolVersion),
			jsonEscape(runtime.ChainID()),
			runtime.ChainHeight(),
			VaultBalanceUgnot(),
			services.Size(),
			activePassesCount,
			passes.Size(),
			subs.Size(),
			settlements.Size(),
			receipts.Size(),
			totalDepositedUgnot,
			totalSettledUgnot,
			totalX402AnchoredUgnot,
			totalSubRevenueUgnot,
			totalRefundedUgnot,
		)
	}
	if parts[0] == "services" {
		var b strings.Builder
		b.WriteByte('[')
		first := true
		services.ReverseIterateByOffset(0, maxRenderRows, func(_ string, v any) bool {
			if !first {
				b.WriteByte(',')
			}
			first = false
			b.WriteString(serviceJSON(v.(*serviceRecord)))
			return false
		})
		b.WriteByte(']')
		return b.String()
	}
	if len(parts) == 2 {
		id, err := strconv.ParseUint(parts[1], 10, 64)
		switch parts[0] {
		case "service":
			if err != nil {
				if v := slugIndex.Get(parts[1]); v != nil {
					id = v.(uint64)
				}
			}
			if s := getServiceRecord(id); s != nil {
				return serviceJSON(s)
			}
		case "pass":
			if err == nil {
				if p, ok := GetPass(id); ok {
					return ufmt.Sprintf(
						`{"id":%d,"serviceId":%d,"buyer":%s,"depositUgnot":%d,"spentUgnot":%d,"pendingUgnot":%d,"availableUgnot":%d,"maxPerCallUgnot":%d,"expiryHeight":%d,"openedHeight":%d,"closed":%t,"usedSessionKey":%t,"voucherPubKey":%s,"settledCalls":%d,"currentHeight":%d}`,
						p.ID, p.ServiceID, jsonEscape(p.Buyer.String()), p.DepositUgnot, p.SpentUgnot, p.PendingUgnot,
						p.AvailableUgnot, p.MaxPerCallUgnot, p.ExpiryHeight, p.OpenedHeight, p.Closed,
						p.UsedSessionKey, jsonEscape(p.VoucherPubKey), p.SettledCalls, runtime.ChainHeight(),
					)
				}
			}
		case "sub":
			if err == nil {
				if s, ok := GetSubscription(id); ok {
					return ufmt.Sprintf(
						`{"id":%d,"serviceId":%d,"buyer":%s,"paidUgnot":%d,"quotaTotal":%d,"quotaUsed":%d,"quotaRemaining":%d,"startHeight":%d,"expiryHeight":%d,"active":%t,"voucherPubKey":%s,"currentHeight":%d}`,
						s.ID, s.ServiceID, jsonEscape(s.Buyer.String()), s.PaidUgnot, s.QuotaTotal,
						s.QuotaUsed, s.QuotaRemaining, s.StartHeight, s.ExpiryHeight, s.Active,
						jsonEscape(s.VoucherPubKey), runtime.ChainHeight(),
					)
				}
			}
		case "receipt":
			if err != nil {
				if v := receiptHashIndex.Get(parts[1]); v != nil {
					id = v.(uint64)
				}
			}
			if r, ok := GetReceipt(id); ok {
				return ufmt.Sprintf(
					`{"id":%d,"rail":%s,"serviceId":%d,"passId":%d,"subId":%d,"settlementId":%d,"settlementStatus":%s,"buyer":%s,"provider":%s,"units":%d,"amountUgnot":%d,"nonce":%s,"resourceHash":%s,"commitment":%s,"txHash":%s,"height":%d,"buyerSigned":%t}`,
					r.ID, jsonEscape(r.Rail), r.ServiceID, r.PassID, r.SubID, r.SettlementID,
					jsonEscape(r.SettlementStatus), jsonEscape(r.Buyer.String()),
					jsonEscape(r.Provider.String()), r.Units, r.AmountUgnot, jsonEscape(r.Nonce),
					jsonEscape(r.ResourceHash), jsonEscape(r.Commitment), jsonEscape(r.TxHash), r.Height, r.BuyerSigned,
				)
			}
		case "settlement":
			if err == nil {
				if st, ok := GetSettlement(id); ok {
					return ufmt.Sprintf(
						`{"id":%d,"serviceId":%d,"passId":%d,"buyer":%s,"provider":%s,"units":%d,"grossUgnot":%d,"discountBps":%d,"netUgnot":%d,"nonce":%s,"resourceHash":%s,"commitment":%s,"claimedHeight":%d,"challengeEnd":%d,"status":%s,"disputeReason":%s,"receiptId":%d,"buyerSigned":%t}`,
						st.ID, st.ServiceID, st.PassID, jsonEscape(st.Buyer.String()), jsonEscape(st.Provider.String()),
						st.Units, st.GrossUgnot, st.DiscountBps, st.NetUgnot, jsonEscape(st.Nonce),
						jsonEscape(st.ResourceHash), jsonEscape(st.Commitment), st.ClaimedHeight,
						st.ChallengeEnd, jsonEscape(st.Status), jsonEscape(st.DisputeReason), st.ReceiptID, st.BuyerSigned,
					)
				}
			}
		}
	}
	return `{"error":"not_found"}`
}

func serviceJSON(s *serviceRecord) string {
	return ufmt.Sprintf(
		`{"id":%d,"slug":%s,"name":%s,"description":%s,"endpointUrl":%s,"owner":%s,"payTo":%s,"unitPriceUgnot":%d,"subPriceUgnot":%d,"subBlocks":%d,"subQuota":%d,"challengeBlocks":%d,"paused":%t,"createdHeight":%d,"totalCalls":%d,"escrowedRevenue":%d,"x402AttestedRevenue":%d}`,
		s.id, jsonEscape(s.slug), jsonEscape(s.name), jsonEscape(s.description), jsonEscape(s.endpointURL),
		jsonEscape(s.owner.String()), jsonEscape(s.payTo.String()), s.unitPriceUgnot, s.subPriceUgnot,
		s.subBlocks, s.subQuota, s.challengeBlocks, s.paused, s.createdHeight, s.totalCalls,
		s.escrowedRevenue, s.x402AttestedRevenue,
	)
}

// Package tollgate implements the on-chain HTTP 402 (x402) metering vault,
// Ed25519-authenticated prepaid credit passes, fixed-window subscriptions,
// challenge-window settlements with buyer reclaim protection, and verifiable
// SHA-256 receipt anchoring for Gno.land.
package tollgate

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"strconv"
	"strings"

	ptollgate "gno.land/p/g1zt8w45ecxhlsdse7hd5gwr6xzcaxy9zsej6hl2/tollgate"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/seqid/v0"
)

func mustCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
}

func readDirectUgnot(cur realm) int64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	if !cur.Previous().IsUserCall() {
		panic("tollgate: payment must be a direct user call")
	}
	sent := unsafe.OriginSend()
	var total int64
	for _, c := range sent {
		if c.Denom != "ugnot" {
			panic("tollgate: only ugnot is accepted")
		}
		total = satAdd(total, c.Amount)
	}
	if total <= 0 {
		panic("tollgate: positive ugnot payment required")
	}
	return total
}

// satAdd prevents silent int64 wraparound on telemetry/revenue accumulators.
func satAdd(a, b int64) int64 {
	if b <= 0 {
		return a
	}
	if a > maxInt64-b {
		return maxInt64
	}
	return a + b
}

func idKey(id uint64) string {
	return seqid.ID(id).Binary()
}

func nonceKey(serviceID uint64, nonce string) string {
	return strconv.FormatUint(serviceID, 10) + ":" + nonce
}

func appendLP(b *strings.Builder, s string) {
	b.WriteString(strconv.Itoa(len(s)))
	b.WriteByte(':')
	b.WriteString(s)
	b.WriteByte('|')
}

// VoucherMessage builds the canonical domain-separated byte message signed by
// a buyer's Ed25519 voucher key for off-chain HTTP authentication and optional
// on-chain ClaimSettlement / ConsumeSubscription cryptographic proof.
func VoucherMessage(
	chainID string,
	serviceID uint64,
	passID uint64,
	subID uint64,
	units int64,
	nonce string,
	resourceHash string,
) string {
	var b strings.Builder
	b.WriteString(VoucherDomain)
	b.WriteByte('|')
	appendLP(&b, chainID)
	b.WriteString(strconv.FormatUint(serviceID, 10))
	b.WriteByte('|')
	b.WriteString(strconv.FormatUint(passID, 10))
	b.WriteByte('|')
	b.WriteString(strconv.FormatUint(subID, 10))
	b.WriteByte('|')
	b.WriteString(strconv.FormatInt(units, 10))
	b.WriteByte('|')
	appendLP(&b, nonce)
	appendLP(&b, resourceHash)
	return b.String()
}

const maxPayWordSteps int64 = 1024

func hexEncode32(sum [32]byte) string {
	const digits = "0123456789abcdef"
	var out [64]byte
	for i := 0; i < 32; i++ {
		out[2*i] = digits[sum[i]>>4]
		out[2*i+1] = digits[sum[i]&0x0f]
	}
	return string(out[:])
}

// PayWordStep advances a Rivest-Shamir PayWord SHA-256 hash-chain voucher by 1 unit.
func PayWordStep(chainID string, prevHex string) string {
	sum := sha256.Sum256([]byte("tollgate-payword-v1|" + chainID + "|" + prevHex))
	return hexEncode32(sum)
}

func verifyPayWord(chainID string, anchorHex string, preimageHex string, steps int64) bool {
	if steps <= 0 || steps > maxPayWordSteps {
		return false
	}
	if !ptollgate.IsValidHexDigest(anchorHex) || !ptollgate.IsValidHexDigest(preimageHex) {
		return false
	}
	cur := preimageHex
	for i := int64(0); i < steps; i++ {
		cur = PayWordStep(chainID, cur)
	}
	var diff byte
	for i := 0; i < 64; i++ {
		diff |= cur[i] ^ anchorHex[i]
	}
	return diff == 0
}

func validateOptionalPubKey(pubKeyHex string) string {
	pubKeyHex = strings.TrimSpace(strings.ToLower(pubKeyHex))
	if pubKeyHex == "" {
		return ""
	}
	if !ptollgate.IsValidHexDigest(pubKeyHex) {
		panic("tollgate: invalid voucherPubKeyHex (expect empty or 64-char lowercase Ed25519 hex)")
	}
	return pubKeyHex
}

