// RegisterService registers a new HTTP 402 / Tollgate metered API service.
func RegisterService(
	cur realm,
	slug string,
	name string,
	endpointURL string,
	payTo address,
	unitPriceUgnot int64,
	subPriceUgnot int64,
	subBlocks int64,
	subQuota int64,
	challengeBlocks int64,
	description string,
) uint64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	owner := cur.Previous().Address()

	slug = strings.TrimSpace(slug)
	if !ptollgate.ValidateSlug(slug) {
		panic("tollgate: invalid service slug (use 2..40 lowercase a-z0-9-)")
	}
	if slugIndex.Has(slug) {
		panic("tollgate: slug already registered")
	}
	name = strings.TrimSpace(sanitize.StripBidiAndZeroWidth(name))
	if name == "" || len(name) > maxNameLen {
		panic("tollgate: invalid service name")
	}
	endpointURL = strings.TrimSpace(sanitize.URL(endpointURL))
	if endpointURL == "" || len(endpointURL) > maxURLLen {
		panic("tollgate: invalid endpoint URL")
	}
	description = strings.TrimSpace(sanitize.StripBidiAndZeroWidth(description))
	if len(description) > maxDescLen {
		panic("tollgate: description exceeds max length")
	}
	if !payTo.IsValid() {
		payTo = owner
	}
	if unitPriceUgnot <= 0 || unitPriceUgnot > maxAmountPerTx {
		panic("tollgate: unitPriceUgnot out of bounds")
	}
	if subPriceUgnot < 0 || subPriceUgnot > maxAmountPerTx {
		panic("tollgate: subPriceUgnot out of bounds")
	}
	if subPriceUgnot > 0 && (subBlocks < minExpiryBlocks || subBlocks > maxExpiryBlocks || subQuota <= 0 || subQuota > maxUnitsPerTx) {
		panic("tollgate: subscription requires valid subBlocks and subQuota")
	}
	if challengeBlocks < ptollgate.MinChallengeBlocks || challengeBlocks > ptollgate.MaxChallengeBlocks {
		panic("tollgate: challengeBlocks out of bounds")
	}

	sid := nextServiceID.Next()
	rec := &serviceRecord{
		id:              uint64(sid),
		slug:            slug,
		name:            name,
		description:     description,
		endpointURL:     endpointURL,
		owner:           owner,
		payTo:           payTo,
		unitPriceUgnot:  unitPriceUgnot,
		subPriceUgnot:   subPriceUgnot,
		subBlocks:       subBlocks,
		subQuota:        subQuota,
		challengeBlocks: challengeBlocks,
		paused:          false,
		createdHeight:   runtime.ChainHeight(),
	}
	services.Set(sid.Binary(), rec)
	slugIndex.Set(slug, uint64(sid))

	chain.Emit(
		"ServiceRegistered",
		"service_id", strconv.FormatUint(rec.id, 10),
		"slug", slug,
		"owner", owner.String(),
		"pay_to", payTo.String(),
		"unit_price_ugnot", strconv.FormatInt(unitPriceUgnot, 10),
	)
	return rec.id
}

// UpdateServicePricing lets the service owner adjust unit and subscription prices.
func UpdateServicePricing(
	cur realm,
	serviceID uint64,
	unitPriceUgnot int64,
	subPriceUgnot int64,
	subBlocks int64,
	subQuota int64,
) {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	svc := getServiceRecord(serviceID)
	if svc == nil {
		panic("tollgate: service not found")
	}
	if cur.Previous().Address() != svc.owner {
		panic("tollgate: only service owner may update pricing")
	}
	if unitPriceUgnot <= 0 || unitPriceUgnot > maxAmountPerTx || subPriceUgnot < 0 || subPriceUgnot > maxAmountPerTx {
		panic("tollgate: invalid pricing parameters")
	}
	if subPriceUgnot > 0 && (subBlocks < minExpiryBlocks || subBlocks > maxExpiryBlocks || subQuota <= 0 || subQuota > maxUnitsPerTx) {
		panic("tollgate: subscription requires valid subBlocks and subQuota")
	}
	svc.unitPriceUgnot = unitPriceUgnot
	svc.subPriceUgnot = subPriceUgnot
	svc.subBlocks = subBlocks
	svc.subQuota = subQuota

	chain.Emit(
		"ServicePricingUpdated",
		"service_id", strconv.FormatUint(serviceID, 10),
		"unit_price_ugnot", strconv.FormatInt(unitPriceUgnot, 10),
		"sub_price_ugnot", strconv.FormatInt(subPriceUgnot, 10),
	)
}

// SetServicePaused pauses or unpauses new passes/subscriptions on a service.
func SetServicePaused(cur realm, serviceID uint64, paused bool) {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	svc := getServiceRecord(serviceID)
	if svc == nil {
		panic("tollgate: service not found")
	}
	if cur.Previous().Address() != svc.owner {
		panic("tollgate: only service owner may pause service")
	}
	svc.paused = paused
	state := StatusActive
	if paused {
		state = StatusPaused
	}
	chain.Emit("ServiceStatusChanged", "service_id", strconv.FormatUint(serviceID, 10), "status", state)
}

// OpenPass locks buyer ugnot into an on-chain prepaid credit vault for high-frequency
// metered API calls. When voucherPubKeyHex (64-char Ed25519 hex) is set, both the
// HTTP gateway AND on-chain ClaimSettlement verify buyer Ed25519 voucher signatures.
// If maxPerCallUgnot <= 0, it safely defaults to the service's current unitPriceUgnot.
func OpenPass(
	cur realm,
	serviceID uint64,
	maxPerCallUgnot int64,
	expiryBlocks int64,
	voucherPubKeyHex string,
) uint64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	if !cur.Previous().IsUserCall() {
		panic("tollgate: payment must be a direct user call")
	}
	sent := readDirectUgnot(cur)
	svc := getServiceRecord(serviceID)
	if svc == nil {
		panic("tollgate: service not found")
	}
	if svc.paused {
		panic("tollgate: service is paused")
	}
	if expiryBlocks < minExpiryBlocks || expiryBlocks > maxExpiryBlocks {
		panic("tollgate: expiryBlocks out of bounds")
	}
	// P0 #5: Safe default per-call cap equals current unitPriceUgnot (never whole deposit).
	if maxPerCallUgnot <= 0 {
		maxPerCallUgnot = svc.unitPriceUgnot
	}
	if maxPerCallUgnot < svc.unitPriceUgnot {
		panic("tollgate: maxPerCallUgnot below service unit price")
	}
	cleanPub := validateOptionalPubKey(voucherPubKeyHex)

	buyer := cur.Previous().Address()
	sessAddr, _, _, isSess := runtime.GetSessionInfo()
	height := runtime.ChainHeight()

	pid := nextPassID.Next()
	rec := &passRecord{
		id:              uint64(pid),
		serviceID:       serviceID,
		buyer:           buyer,
		depositUgnot:    sent,
		maxPerCallUgnot: maxPerCallUgnot,
		expiryHeight:    height + expiryBlocks,
		openedHeight:    height,
		usedSessionKey:  isSess,
		sessionKeyAddr:  sessAddr,
		voucherPubKey:   cleanPub,
	}
	passes.Set(pid.Binary(), rec)
	activePassesCount++
	totalDepositedUgnot = satAdd(totalDepositedUgnot, sent)

	chain.Emit(
		"PassOpened",
		"pass_id", strconv.FormatUint(rec.id, 10),
		"service_id", strconv.FormatUint(serviceID, 10),
		"buyer", buyer.String(),
		"deposit_ugnot", strconv.FormatInt(sent, 10),
		"expiry_height", strconv.FormatInt(rec.expiryHeight, 10),
	)
	return rec.id
}

// TopUpPass adds more ugnot and optionally extends expiry of an active pass.
func TopUpPass(cur realm, passID uint64, extendBlocks int64) {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	if !cur.Previous().IsUserCall() {
		panic("tollgate: payment must be a direct user call")
	}
	sent := readDirectUgnot(cur)
	p := getPassRecord(passID)
	if p == nil {
		panic("tollgate: pass not found")
	}
	if p.closed {
		panic("tollgate: pass is closed")
	}
	if cur.Previous().Address() != p.buyer {
		panic("tollgate: only pass buyer may top up")
	}
	if extendBlocks < 0 || extendBlocks > maxExpiryBlocks {
		panic("tollgate: invalid extendBlocks")
	}
	if p.depositUgnot > maxInt64-sent {
		panic("tollgate: deposit overflow")
	}
	p.depositUgnot += sent
	if extendBlocks > 0 {
		base := p.expiryHeight
		if h := runtime.ChainHeight(); h > base {
			base = h
		}
		p.expiryHeight = base + extendBlocks
	}
	totalDepositedUgnot = satAdd(totalDepositedUgnot, sent)

	chain.Emit(
		"PassToppedUp",
		"pass_id", strconv.FormatUint(passID, 10),
		"added_ugnot", strconv.FormatInt(sent, 10),
		"expiry_height", strconv.FormatInt(p.expiryHeight, 10),
	)
}

// RequestEarlyClose shortens a pass expiry to height + service.challengeBlocks so
// the provider gets one bounded settlement window and cannot lock buyer funds.
func RequestEarlyClose(cur realm, passID uint64) int64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	p := getPassRecord(passID)
	if p == nil {
		panic("tollgate: pass not found")
	}
	if p.closed {
		panic("tollgate: pass already closed")
	}
	if cur.Previous().Address() != p.buyer {
		panic("tollgate: only pass buyer may request close")
	}
	svc := getServiceRecord(p.serviceID)
	target := runtime.ChainHeight() + svc.challengeBlocks
	if target < p.expiryHeight {
		p.expiryHeight = target
	}
	chain.Emit(
		"PassEarlyCloseRequested",
		"pass_id", strconv.FormatUint(passID, 10),
		"expiry_height", strconv.FormatInt(p.expiryHeight, 10),
	)
	return p.expiryHeight
}

// ClosePass refunds any unspent, non-pending ugnot back to the pass buyer once
// the pass has expired (or its service is paused) and no settlement is pending.
func ClosePass(cur realm, passID uint64) int64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	p := getPassRecord(passID)
	if p == nil {
		panic("tollgate: pass not found")
	}
	if p.closed {
		panic("tollgate: pass already closed")
	}
	if cur.Previous().Address() != p.buyer {
		panic("tollgate: only pass buyer may close pass")
	}
	svc := getServiceRecord(p.serviceID)
	height := runtime.ChainHeight()
	if height < p.expiryHeight && !svc.paused {
		panic("tollgate: pass not expired yet (call RequestEarlyClose first)")
	}
	if p.pendingUgnot > 0 {
		panic("tollgate: pending settlements must resolve before closing")
	}

	refund, err := ptollgate.ComputeAvailable(p.depositUgnot, p.spentUgnot, p.pendingUgnot)
	if err != nil {
		panic(err.Error())
	}
	p.closed = true
	if activePassesCount > 0 {
		activePassesCount--
	}
	if refund > 0 {
		totalRefundedUgnot = satAdd(totalRefundedUgnot, refund)
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(cur.Address(), p.buyer, chain.NewCoins(chain.NewCoin("ugnot", refund)))
	}

	chain.Emit(
		"PassClosed",
		"pass_id", strconv.FormatUint(passID, 10),
		"buyer", p.buyer.String(),
		"refund_ugnot", strconv.FormatInt(refund, 10),
	)
	return refund
}

// Subscribe purchases a fixed-window quota subscription, optionally binds a
// buyer Ed25519 voucher public key, and pays the service provider immediately.
func Subscribe(cur realm, serviceID uint64, voucherPubKeyHex string) uint64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	if !cur.Previous().IsUserCall() {
		panic("tollgate: payment must be a direct user call")
	}
	sent := readDirectUgnot(cur)
	svc := getServiceRecord(serviceID)
	if svc == nil {
		panic("tollgate: service not found")
	}
	if svc.paused {
		panic("tollgate: service is paused")
	}
	if svc.subPriceUgnot <= 0 {
		panic("tollgate: service does not offer subscriptions")
	}
	if sent < svc.subPriceUgnot {
		panic("tollgate: insufficient ugnot for subscription")
	}
	cleanPub := validateOptionalPubKey(voucherPubKeyHex)

	buyer := cur.Previous().Address()
	sessAddr, _, _, isSess := runtime.GetSessionInfo()
	height := runtime.ChainHeight()
	sid := nextSubID.Next()

	rec := &subRecord{
		id:             uint64(sid),
		serviceID:      serviceID,
		buyer:          buyer,
		paidUgnot:      svc.subPriceUgnot,
		quotaTotal:     svc.subQuota,
		quotaUsed:      0,
		startHeight:    height,
		expiryHeight:   height + svc.subBlocks,
		usedSessionKey: isSess,
		sessionKeyAddr: sessAddr,
		voucherPubKey:  cleanPub,
	}
	subs.Set(sid.Binary(), rec)
	svc.escrowedRevenue = satAdd(svc.escrowedRevenue, svc.subPriceUgnot)
	totalSubRevenueUgnot = satAdd(totalSubRevenueUgnot, svc.subPriceUgnot)

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), svc.payTo, chain.NewCoins(chain.NewCoin("ugnot", svc.subPriceUgnot)))
	if change := sent - svc.subPriceUgnot; change > 0 {
		b.SendCoins(cur.Address(), buyer, chain.NewCoins(chain.NewCoin("ugnot", change)))
	}

	chain.Emit(
		"Subscribed",
		"sub_id", strconv.FormatUint(rec.id, 10),
		"service_id", strconv.FormatUint(serviceID, 10),
		"buyer", buyer.String(),
		"paid_ugnot", strconv.FormatInt(svc.subPriceUgnot, 10),
		"quota", strconv.FormatInt(svc.subQuota, 10),
		"expiry_height", strconv.FormatInt(rec.expiryHeight, 10),
	)
	return rec.id
}

// ConsumeSubscription records metered quota usage against an active subscription.
// If the subscription registered a voucherPubKey, buyerSigHex MUST be a valid
// Ed25519 signature over VoucherMessage(...).
func ConsumeSubscription(
	cur realm,
	subID uint64,
	units int64,
	nonce string,
	resourceHash string,
	buyerSigHex string,
) uint64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	sub := getSubRecord(subID)
	if sub == nil {
		panic("tollgate: subscription not found")
	}
	svc := getServiceRecord(sub.serviceID)
	if cur.Previous().Address() != svc.owner {
		panic("tollgate: only service owner may consume subscription quota")
	}
	if runtime.ChainHeight() >= sub.expiryHeight {
		panic("tollgate: subscription expired")
	}
	// P0 #4: Overflow-safe quota check (never wraps negative).
	if units <= 0 || units > maxUnitsPerTx || units > sub.quotaTotal-sub.quotaUsed {
		panic("tollgate: subscription quota exceeded")
	}
	if !ptollgate.ValidateNonce(nonce) {
		panic("tollgate: invalid nonce")
	}
	if !ptollgate.IsValidHexDigest(resourceHash) {
		panic("tollgate: invalid resourceHash (expect 64-char lowercase sha256 hex)")
	}
	nk := nonceKey(sub.serviceID, nonce)
	if nonceUsed.Has(nk) {
		panic("tollgate: duplicate nonce")
	}

	buyerSigned := false
	if sub.voucherPubKey != "" {
		if !verifyPayWord(runtime.ChainID(), sub.voucherPubKey, buyerSigHex, units) {
			panic("tollgate: invalid PayWord SHA-256 buyer voucher preimage")
		}
		sub.voucherPubKey = buyerSigHex
		buyerSigned = true
	}

	sub.quotaUsed += units
	svc.totalCalls = satAdd(svc.totalCalls, units)

	commitment := ptollgate.ReceiptCommitment(
		runtime.ChainID(),
		sub.serviceID,
		0,
		sub.buyer.String(),
		svc.payTo.String(),
		units,
		0,
		nonce,
		resourceHash,
	)

	rid := nextReceiptID.Next()
	r := &receiptRecord{
		id:           uint64(rid),
		rail:         RailSubscription,
		serviceID:    sub.serviceID,
		subID:        sub.id,
		buyer:        sub.buyer,
		provider:     svc.payTo,
		units:        units,
		amountUgnot:  0,
		nonce:        nonce,
		resourceHash: resourceHash,
		commitment:   commitment,
		height:       runtime.ChainHeight(),
		buyerSigned:  buyerSigned,
	}
	receipts.Set(rid.Binary(), r)
	receiptHashIndex.Set(commitment, r.id)
	nonceUsed.Set(nk, r.id)

	chain.Emit(
		"SubscriptionUsageAnchored",
		"receipt_id", strconv.FormatUint(r.id, 10),
		"sub_id", strconv.FormatUint(subID, 10),
		"units", strconv.FormatInt(units, 10),
		"commitment", commitment,
	)
	return r.id
}

// ClaimSettlement lets the service provider submit a metered usage batch against
// a prepaid pass BEFORE pass expiry. If the pass bound an Ed25519 voucherPubKey,
// buyerSigHex is verified directly on-chain via crypto/ed25519.Verify.
func ClaimSettlement(
	cur realm,
	passID uint64,
	units int64,
	nonce string,
	resourceHash string,
	buyerSigHex string,
) uint64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	p := getPassRecord(passID)
	if p == nil {
		panic("tollgate: pass not found")
	}
	if p.closed {
		panic("tollgate: pass is closed")
	}
	// P0 #3: Provider cannot file new claims once pass has expired (protects ClosePass).
	if runtime.ChainHeight() >= p.expiryHeight {
		panic("tollgate: pass expired; claims closed")
	}
	svc := getServiceRecord(p.serviceID)
	if cur.Previous().Address() != svc.owner {
		panic("tollgate: only service owner may claim settlement")
	}
	if units <= 0 || units > maxUnitsPerTx {
		panic("tollgate: units out of bounds")
	}
	if !ptollgate.ValidateNonce(nonce) {
		panic("tollgate: invalid nonce")
	}
	if !ptollgate.IsValidHexDigest(resourceHash) {
		panic("tollgate: invalid resourceHash (expect 64-char lowercase sha256 hex)")
	}
	nk := nonceKey(svc.id, nonce)
	if nonceUsed.Has(nk) {
		panic("tollgate: duplicate nonce")
	}

	buyerSigned := false
	if p.voucherPubKey != "" {
		if !verifyPayWord(runtime.ChainID(), p.voucherPubKey, buyerSigHex, units) {
			panic("tollgate: invalid PayWord SHA-256 buyer voucher preimage")
		}
		p.voucherPubKey = buyerSigHex
		buyerSigned = true
	}

	charge, err := ptollgate.ComputeCharge(svc.unitPriceUgnot, units)
	if err != nil {
		panic(err.Error())
	}
	// Overflow-safe per-call ceiling check: netUgnot <= maxPerCallUgnot * units
	if p.maxPerCallUgnot <= maxInt64/units && charge.NetUgnot > p.maxPerCallUgnot*units {
		panic("tollgate: batch exceeds pass maxPerCallUgnot ceiling")
	}
	avail, err := ptollgate.ComputeAvailable(p.depositUgnot, p.spentUgnot, p.pendingUgnot)
	if err != nil {
		panic(err.Error())
	}
	if charge.NetUgnot > avail {
		panic("tollgate: insufficient available pass balance")
	}

	height := runtime.ChainHeight()
	commitment := ptollgate.ReceiptCommitment(
		runtime.ChainID(),
		svc.id,
		p.id,
		p.buyer.String(),
		svc.payTo.String(),
		units,
		charge.NetUgnot,
		nonce,
		resourceHash,
	)

	rid := nextReceiptID.Next()
	stID := nextSettlementID.Next()
	r := &receiptRecord{
		id:           uint64(rid),
		rail:         RailMeteredPass,
		serviceID:    svc.id,
		passID:       p.id,
		settlementID: uint64(stID),
		buyer:        p.buyer,
		provider:     svc.payTo,
		units:        units,
		amountUgnot:  charge.NetUgnot,
		nonce:        nonce,
		resourceHash: resourceHash,
		commitment:   commitment,
		height:       height,
		buyerSigned:  buyerSigned,
	}
	receipts.Set(rid.Binary(), r)
	receiptHashIndex.Set(commitment, r.id)
	nonceUsed.Set(nk, r.id)

	st := &settlementRecord{
		id:            uint64(stID),
		serviceID:     svc.id,
		passID:        p.id,
		buyer:         p.buyer,
		provider:      svc.payTo,
		units:         units,
		grossUgnot:    charge.GrossUgnot,
		discountBps:   charge.DiscountBps,
		netUgnot:      charge.NetUgnot,
		nonce:         nonce,
		resourceHash:  resourceHash,
		commitment:    commitment,
		claimedHeight: height,
		challengeEnd:  height + svc.challengeBlocks,
		status:        StatusPending,
		receiptID:     r.id,
		buyerSigned:   buyerSigned,
	}
	settlements.Set(stID.Binary(), st)
	p.pendingUgnot += charge.NetUgnot

	chain.Emit(
		"SettlementClaimed",
		"settlement_id", strconv.FormatUint(st.id, 10),
		"pass_id", strconv.FormatUint(p.id, 10),
		"receipt_id", strconv.FormatUint(r.id, 10),
		"net_ugnot", strconv.FormatInt(charge.NetUgnot, 10),
		"challenge_end", strconv.FormatInt(st.challengeEnd, 10),
		"commitment", commitment,
	)
	return st.id
}

// DisputeSettlement freezes a pending settlement inside its challenge window.
func DisputeSettlement(cur realm, settlementID uint64, reason string) {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	st := getSettlementRecord(settlementID)
	if st == nil {
		panic("tollgate: settlement not found")
	}
	if st.status != StatusPending {
		panic("tollgate: settlement is not pending")
	}
	if cur.Previous().Address() != st.buyer {
		panic("tollgate: only buyer may dispute settlement")
	}
	if runtime.ChainHeight() >= st.challengeEnd {
		panic("tollgate: challenge window has elapsed")
	}
	reason = strings.TrimSpace(sanitize.StripBidiAndZeroWidth(reason))
	if reason == "" || len(reason) > maxReasonLen {
		panic("tollgate: valid dispute reason required")
	}
	st.status = StatusDisputed
	st.disputeReason = reason

	chain.Emit(
		"SettlementDisputed",
		"settlement_id", strconv.FormatUint(settlementID, 10),
		"buyer", st.buyer.String(),
	)
}

// RefundDisputedSettlement lets the service owner concede a disputed or pending
// settlement, immediately releasing the locked ugnot back to the pass balance.
func RefundDisputedSettlement(cur realm, settlementID uint64) {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	st := getSettlementRecord(settlementID)
	if st == nil {
		panic("tollgate: settlement not found")
	}
	if st.status != StatusDisputed && st.status != StatusPending {
		panic("tollgate: settlement cannot be refunded")
	}
	svc := getServiceRecord(st.serviceID)
	if cur.Previous().Address() != svc.owner {
		panic("tollgate: only service owner may refund settlement")
	}
	p := getPassRecord(st.passID)
	p.pendingUgnot -= st.netUgnot
	st.status = StatusRefunded

	chain.Emit(
		"SettlementRefunded",
		"settlement_id", strconv.FormatUint(settlementID, 10),
		"pass_id", strconv.FormatUint(st.passID, 10),
		"amount_ugnot", strconv.FormatInt(st.netUgnot, 10),
	)
}

// ReclaimDisputedSettlement (P0 #2) lets the buyer unconditionally unlock funds
// from a disputed settlement if the provider does not refund within one additional
// challenge window (st.challengeEnd + svc.challengeBlocks), preventing pass lockup.
func ReclaimDisputedSettlement(cur realm, settlementID uint64) {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	st := getSettlementRecord(settlementID)
	if st == nil {
		panic("tollgate: settlement not found")
	}
	if st.status != StatusDisputed {
		panic("tollgate: settlement is not disputed")
	}
	if cur.Previous().Address() != st.buyer {
		panic("tollgate: only buyer may reclaim disputed settlement")
	}
	svc := getServiceRecord(st.serviceID)
	if runtime.ChainHeight() < st.challengeEnd+svc.challengeBlocks {
		panic("tollgate: provider response window still active")
	}
	p := getPassRecord(st.passID)
	p.pendingUgnot -= st.netUgnot
	st.status = StatusRefunded

	chain.Emit(
		"SettlementReclaimed",
		"settlement_id", strconv.FormatUint(settlementID, 10),
		"pass_id", strconv.FormatUint(st.passID, 10),
		"amount_ugnot", strconv.FormatInt(st.netUgnot, 10),
	)
}

// FinalizeSettlement releases an undisputed settlement's locked ugnot to the
// service payTo address once the challenge window has passed.
func FinalizeSettlement(cur realm, settlementID uint64) {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	st := getSettlementRecord(settlementID)
	if st == nil {
		panic("tollgate: settlement not found")
	}
	if st.status != StatusPending {
		panic("tollgate: settlement is not pending")
	}
	if runtime.ChainHeight() < st.challengeEnd {
		panic("tollgate: challenge window still active")
	}

	p := getPassRecord(st.passID)
	svc := getServiceRecord(st.serviceID)

	p.pendingUgnot -= st.netUgnot
	p.spentUgnot += st.netUgnot
	p.settledCalls = satAdd(p.settledCalls, st.units)
	svc.totalCalls = satAdd(svc.totalCalls, st.units)
	svc.escrowedRevenue = satAdd(svc.escrowedRevenue, st.netUgnot)
	totalSettledUgnot = satAdd(totalSettledUgnot, st.netUgnot)
	st.status = StatusFinalized

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), svc.payTo, chain.NewCoins(chain.NewCoin("ugnot", st.netUgnot)))

	chain.Emit(
		"SettlementFinalized",
		"settlement_id", strconv.FormatUint(settlementID, 10),
		"pay_to", svc.payTo.String(),
		"net_ugnot", strconv.FormatInt(st.netUgnot, 10),
	)
}

// RecordX402Receipt anchors an external gnolang/x402 direct bank-send HTTP 402
// settlement on chain (provider-attested, tracked separately from escrowed TVL).
func RecordX402Receipt(
	cur realm,
	serviceID uint64,
	buyer address,
	units int64,
	amountUgnot int64,
	nonce string,
	resourceHash string,
	txHash string,
) uint64 {
	if !cur.IsCurrent() {
		panic("tollgate: spoofed realm capability")
	}
	svc := getServiceRecord(serviceID)
	if svc == nil {
		panic("tollgate: service not found")
	}
	if cur.Previous().Address() != svc.owner {
		panic("tollgate: only service owner may anchor x402 receipts")
	}
	if !buyer.IsValid() {
		panic("tollgate: invalid buyer address")
	}
	// P0 #4: Bound units & amountUgnot to prevent telemetry overflow vandalism.
	if units <= 0 || units > maxUnitsPerTx || amountUgnot <= 0 || amountUgnot > maxAmountPerTx {
		panic("tollgate: units or amountUgnot out of bounds")
	}
	if !ptollgate.ValidateNonce(nonce) {
		panic("tollgate: invalid nonce")
	}
	if !ptollgate.IsValidHexDigest(resourceHash) {
		panic("tollgate: invalid resourceHash")
	}
	txHash = strings.TrimSpace(sanitize.StripBidiAndZeroWidth(txHash))
	if len(txHash) < 8 || len(txHash) > 128 {
		panic("tollgate: invalid txHash")
	}
	nk := nonceKey(serviceID, nonce)
	if nonceUsed.Has(nk) {
		panic("tollgate: duplicate nonce")
	}

	commitment := ptollgate.ReceiptCommitment(
		runtime.ChainID(),
		svc.id,
		0,
		buyer.String(),
		svc.payTo.String(),
		units,
		amountUgnot,
		nonce,
		resourceHash,
	)

	rid := nextReceiptID.Next()
	r := &receiptRecord{
		id:           uint64(rid),
		rail:         RailX402Direct,
		serviceID:    svc.id,
		buyer:        buyer,
		provider:     svc.payTo,
		units:        units,
		amountUgnot:  amountUgnot,
		nonce:        nonce,
		resourceHash: resourceHash,
		commitment:   commitment,
		txHash:       txHash,
		height:       runtime.ChainHeight(),
	}
	receipts.Set(rid.Binary(), r)
	receiptHashIndex.Set(commitment, r.id)
	nonceUsed.Set(nk, r.id)
	svc.totalCalls = satAdd(svc.totalCalls, units)
	svc.x402AttestedRevenue = satAdd(svc.x402AttestedRevenue, amountUgnot)
	totalX402AnchoredUgnot = satAdd(totalX402AnchoredUgnot, amountUgnot)

	chain.Emit(
		"X402ReceiptAnchored",
		"receipt_id", strconv.FormatUint(r.id, 10),
		"service_id", strconv.FormatUint(serviceID, 10),
		"buyer", buyer.String(),
		"amount_ugnot", strconv.FormatInt(amountUgnot, 10),
		"tx_hash", txHash,
		"commitment", commitment,
	)
	return r.id
}

// --- Read-only query surface (value copies only, zero mutable pointers) ---

func GetService(serviceID uint64) (ServiceView, bool) {
	svc := getServiceRecord(serviceID)
	if svc == nil {
		return ServiceView{}, false
	}
	return ServiceView{
		ID:                  svc.id,
		Slug:                svc.slug,
		Name:                svc.name,
		Description:         svc.description,
		EndpointURL:         svc.endpointURL,
		Owner:               svc.owner,
		PayTo:               svc.payTo,
		UnitPriceUgnot:      svc.unitPriceUgnot,
		SubPriceUgnot:       svc.subPriceUgnot,
		SubBlocks:           svc.subBlocks,
		SubQuota:            svc.subQuota,
		ChallengeBlocks:     svc.challengeBlocks,
		Paused:              svc.paused,
		CreatedHeight:       svc.createdHeight,
		TotalCalls:          svc.totalCalls,
		EscrowedRevenue:     svc.escrowedRevenue,
		X402AttestedRevenue: svc.x402AttestedRevenue,
	}, true
}

func GetServiceBySlug(slug string) (ServiceView, bool) {
	v := slugIndex.Get(slug)
	if v == nil {
		return ServiceView{}, false
	}
	return GetService(v.(uint64))
}

func GetPass(passID uint64) (PassView, bool) {
	p := getPassRecord(passID)
	if p == nil {
		return PassView{}, false
	}
	avail, _ := ptollgate.ComputeAvailable(p.depositUgnot, p.spentUgnot, p.pendingUgnot)
	return PassView{
		ID:              p.id,
		ServiceID:       p.serviceID,
		Buyer:           p.buyer,
		DepositUgnot:    p.depositUgnot,
		SpentUgnot:      p.spentUgnot,
		PendingUgnot:    p.pendingUgnot,
		AvailableUgnot:  avail,
		MaxPerCallUgnot: p.maxPerCallUgnot,
		ExpiryHeight:    p.expiryHeight,
		OpenedHeight:    p.openedHeight,
		Closed:          p.closed,
		UsedSessionKey:  p.usedSessionKey,
		SessionKeyAddr:  p.sessionKeyAddr,
		VoucherPubKey:   p.voucherPubKey,
		SettledCalls:    p.settledCalls,
	}, true
}

func GetSubscription(subID uint64) (SubscriptionView, bool) {
	s := getSubRecord(subID)
	if s == nil {
		return SubscriptionView{}, false
	}
	rem := s.quotaTotal - s.quotaUsed
	active := runtime.ChainHeight() <= s.expiryHeight && rem > 0
	return SubscriptionView{
		ID:             s.id,
		ServiceID:      s.serviceID,
		Buyer:          s.buyer,
		PaidUgnot:      s.paidUgnot,
		QuotaTotal:     s.quotaTotal,
		QuotaUsed:      s.quotaUsed,
		QuotaRemaining: rem,
		StartHeight:    s.startHeight,
		ExpiryHeight:   s.expiryHeight,
		Active:         active,
		VoucherPubKey:  s.voucherPubKey,
	}, true
}

func GetSettlement(settlementID uint64) (SettlementView, bool) {
	st := getSettlementRecord(settlementID)
	if st == nil {
		return SettlementView{}, false
	}
	return SettlementView{
		ID:            st.id,
		ServiceID:     st.serviceID,
		PassID:        st.passID,
		Buyer:         st.buyer,
		Provider:      st.provider,
		Units:         st.units,
		GrossUgnot:    st.grossUgnot,
		DiscountBps:   st.discountBps,
		NetUgnot:      st.netUgnot,
		Nonce:         st.nonce,
		ResourceHash:  st.resourceHash,
		Commitment:    st.commitment,
		ClaimedHeight: st.claimedHeight,
		ChallengeEnd:  st.challengeEnd,
		Status:        st.status,
		DisputeReason: st.disputeReason,
		ReceiptID:     st.receiptID,
		BuyerSigned:   st.buyerSigned,
	}, true
}

func receiptSettlementStatus(r *receiptRecord) string {
	if r.settlementID > 0 {
		if st := getSettlementRecord(r.settlementID); st != nil {
			return st.status
		}
	}
	if r.rail == RailX402Direct {
		return "provider-attested"
	}
	return "recorded"
}

func GetReceipt(receiptID uint64) (ReceiptView, bool) {
	r := getReceiptRecord(receiptID)
	if r == nil {
		return ReceiptView{}, false
	}
	return ReceiptView{
		ID:               r.id,
		Rail:             r.rail,
		ServiceID:        r.serviceID,
		PassID:           r.passID,
		SubID:            r.subID,
		SettlementID:     r.settlementID,
		SettlementStatus: receiptSettlementStatus(r),
		Buyer:            r.buyer,
		Provider:         r.provider,
		Units:            r.units,
		AmountUgnot:      r.amountUgnot,
		Nonce:            r.nonce,
		ResourceHash:     r.resourceHash,
		Commitment:       r.commitment,
		TxHash:           r.txHash,
		Height:           r.height,
		BuyerSigned:      r.buyerSigned,
	}, true
}

// VerifyReceiptByCommitment checks whether a canonical SHA-256 receipt digest
// is anchored on chain AND has NOT been refunded/invalidated by a dispute.
func VerifyReceiptByCommitment(commitmentHex string) (uint64, bool) {
	if !ptollgate.IsValidHexDigest(commitmentHex) {
		return 0, false
	}
	v := receiptHashIndex.Get(commitmentHex)
	if v == nil {
		return 0, false
	}
	rid := v.(uint64)
	r := getReceiptRecord(rid)
	if r == nil {
		return 0, false
	}
	if receiptSettlementStatus(r) == StatusRefunded {
		return rid, false
	}
	return rid, true
}

// CheckPassQuota is a fast read-only helper for HTTP gateways (via vm/qeval).
func CheckPassQuota(passID uint64, units int64) bool {
	p := getPassRecord(passID)
	if p == nil || p.closed || units <= 0 || units > maxUnitsPerTx {
		return false
	}
	if runtime.ChainHeight() >= p.expiryHeight {
		return false
	}
	svc := getServiceRecord(p.serviceID)
	if svc == nil || svc.paused {
		return false
	}
	charge, err := ptollgate.ComputeCharge(svc.unitPriceUgnot, units)
	if err != nil {
		return false
	}
	if p.maxPerCallUgnot <= maxInt64/units && charge.NetUgnot > p.maxPerCallUgnot*units {
		return false
	}
	avail, err := ptollgate.ComputeAvailable(p.depositUgnot, p.spentUgnot, p.pendingUgnot)
	if err != nil {
		return false
	}
	return avail >= charge.NetUgnot
}

// CheckSubscriptionActive verifies via vm/qeval whether a subscription has
// remaining quota and has not expired (overflow-safe).
func CheckSubscriptionActive(subID uint64, units int64) bool {
	s := getSubRecord(subID)
	if s == nil || units <= 0 || units > maxUnitsPerTx {
		return false
	}
	if runtime.ChainHeight() > s.expiryHeight {
		return false
	}
	return units <= s.quotaTotal-s.quotaUsed
}

// VaultBalanceUgnot returns the live ugnot locked in this realm using O(1) GetCoin.
func VaultBalanceUgnot() int64 {
	pkgAddr := chain.PackageAddress("gno.land/r/g1zt8w45ecxhlsdse7hd5gwr6xzcaxy9zsej6hl2/tollgate/v2")
	return banker.NewReadonlyBanker().GetCoin(pkgAddr, "ugnot")
}

package hat

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"strconv"
)

// PickShufflers picks who shuffles, from the draw seed alone, so nobody can
// hand-pick them. Rosters of up to four use everyone, in a seed-derived
// order. Larger rosters get three distinct shufflers, never exclude.
func PickShufflers(seed []byte, n, exclude int) []int {
	pool := make([]int, 0, n)
	for i := 0; i < n; i++ {
		if n <= 4 || i != exclude {
			pool = append(pool, i)
		}
	}
	k := len(pool)
	if n > 4 {
		k = Shufflers
	}
	// Partial Fisher-Yates driven by sha256(seed || "pick" || j).
	for j := 0; j < k; j++ {
		r := j + int(draw(seed, j)%uint64(len(pool)-j))
		pool[j], pool[r] = pool[r], pool[j]
	}
	return pool[:k]
}

func draw(seed []byte, j int) uint64 {
	buf := append(append([]byte{}, seed...), []byte("pick")...)
	var ctr [4]byte
	binary.BigEndian.PutUint32(ctr[:], uint32(j))
	sum := sha256.Sum256(append(buf, ctr[:]...))
	return binary.BigEndian.Uint64(sum[:8])
}

// Circle arranges slot keys in one circle: sorted by sha256(seed || slot).
// The order is fixed by the realm, not by the last shuffler. Slot k gives to
// slot k+1, wrapping round, so with three or more slots nobody draws
// themselves and everyone is in one single loop.
func Circle(seed []byte, slots [][]byte) [][]byte {
	type keyed struct{ key, slot []byte }
	ks := make([]keyed, len(slots))
	for i, s := range slots {
		sum := sha256.Sum256(append(append([]byte{}, seed...), s...))
		ks[i] = keyed{sum[:], s}
	}
	// Insertion sort: at most MaxPeople items.
	for i := 1; i < len(ks); i++ {
		for j := i; j > 0 && bytes.Compare(ks[j].key, ks[j-1].key) < 0; j-- {
			ks[j], ks[j-1] = ks[j-1], ks[j]
		}
	}
	out := make([][]byte, len(ks))
	for i, k := range ks {
		out[i] = k.slot
	}
	return out
}

// Receiver returns the circle position slot k gives to.
func Receiver(k, n int) int { return (k + 1) % n }

// Santa returns the circle position that gives to slot k.
func Santa(k, n int) int { return (k + n - 1) % n }

// CheckMix compares one shuffle turn's output with its input. It returns ""
// if the output is a plausible shuffle (same count, every item exactly
// size bytes, all distinct), or a plain-words reason why it is not.
// It cannot tell whether each layer was peeled honestly; the phones check
// that afterwards.
func CheckMix(in, out [][]byte, size int) string {
	if len(out) != len(in) {
		return "slip count changed from " + strconv.Itoa(len(in)) + " to " + strconv.Itoa(len(out))
	}
	seen := map[string]bool{}
	for _, b := range out {
		if len(b) != size || len(b) > MaxBlob {
			return "a slip has the wrong size"
		}
		if seen[string(b)] {
			return "a slip is duplicated"
		}
		seen[string(b)] = true
	}
	return ""
}

// MatchSlips takes the last round-two output, where each item is a 32-byte
// slot key followed by a sealed slip, and lines the slips up with the circle.
// Every slot must get exactly one slip.
func MatchSlips(slots, out [][]byte) ([][]byte, string) {
	pos := map[string]int{}
	for k, s := range slots {
		pos[string(s)] = k
	}
	slips := make([][]byte, len(slots))
	for _, b := range out {
		k, ok := pos[string(b[:KeySize])]
		if !ok {
			return nil, "a slip is addressed to no slot"
		}
		if slips[k] != nil {
			return nil, "a slot got two slips"
		}
		slips[k] = b[KeySize:]
	}
	return slips, ""
}

// Fingerprint is the short public name of a key: its first 6 hex chars.
func Fingerprint(b []byte) string {
	const hexdigits = "0123456789abcdef"
	out := make([]byte, 0, 6)
	for i := 0; i < 3 && i < len(b); i++ {
		out = append(out, hexdigits[b[i]>>4], hexdigits[b[i]&15])
	}
	return string(out)
}

package hat

import (
	"bytes"
	"crypto/sha256"
	"errors"
	"strconv"
	"time"
)

// Size limits keep gas and storage small.
const (
	MinPeople = 3    // a circle of fewer than three is not a draw
	MaxPeople = 30   // upper bound on the roster
	MaxBlob   = 1024 // upper bound on any single onion or slip, in bytes

	KeySize      = 32 // slot keys, box keys, commitments and seeds
	SealOverhead = 48 // bytes crypto_box_seal adds per layer (ephemeral key + MAC)

	// Shufflers is how many shufflers a roster of five or more gets.
	// Rosters of three or four use everyone.
	Shufflers = 3
)

var (
	ErrPhase       = errors.New("hat: not allowed in this phase")
	ErrMember      = errors.New("hat: unknown member")
	ErrFull        = errors.New("hat: roster is full")
	ErrTooFew      = errors.New("hat: need at least 3 people")
	ErrDuplicate   = errors.New("hat: already done")
	ErrNotYourTurn = errors.New("hat: not your shuffle turn")
	ErrSize        = errors.New("hat: wrong size")
	ErrKeyTaken    = errors.New("hat: key already in this draw")
	ErrCommit      = errors.New("hat: seed does not match commitment")
	ErrExpired     = errors.New("hat: phase deadline has passed")
	ErrConfirmed   = errors.New("hat: everyone already confirmed")
)

// Options configure a hat.
type Options struct {
	// Rounds is 2 for a gift exchange (slots, then slips) or 1 when only the
	// anonymous slots are needed, as in a role deal.
	Rounds int
	// Slip is the size, in bytes, of each item the last shuffler of round two
	// outputs: a 32-byte slot key followed by an opaque sealed payload.
	// Ignored when Rounds is 1.
	Slip int
	// Step is how long each phase, and each shuffle turn, may take.
	Step time.Duration
	// JoinWindow is how long the roster stays open.
	JoinWindow time.Duration
}

type member struct {
	box    []byte // X25519 public key shufflers are reached with
	commit []byte // sha256 of the seed revealed in Locked
	seed   []byte
	done   bool // has acted in the current Ready, Seal or Confirm phase
}

// Hat is the full state of one draw, minus identities: members are numbered
// in join order and the caller (a realm) maps them to people and keys.
// A Hat never stores which slot belongs to which member.
type Hat struct {
	opts      Options
	phase     Phase
	deadline  time.Time
	members   []*member
	exclude   int // member never picked as shuffler in rosters of 5+, or -1
	seed      []byte
	shufflers []int
	turn      int      // shuffle turns done in the current mix phase
	contents  [][]byte // what is in the hat during Seal and Mix
	slots     [][]byte // the circle, after Mix1
	slips     [][]byte // after Mix2, slips[k] is addressed to slots[k]
	confirmed int      // confirmations in Check or Revealed
	reason    string   // why it was voided
}

// New opens a hat for joining at block time now.
func New(opts Options, now time.Time) *Hat {
	if opts.Rounds != 1 {
		opts.Rounds = 2
	}
	return &Hat{opts: opts, phase: Join, deadline: now.Add(opts.JoinWindow), exclude: -1}
}

// Phase returns the current phase.
func (h *Hat) Phase() Phase { return h.phase }

// Rounds returns 1 or 2.
func (h *Hat) Rounds() int { return h.opts.Rounds }

// Deadline returns the block time by which the current phase or turn must end.
func (h *Hat) Deadline() time.Time { return h.deadline }

// Size returns the number of members.
func (h *Hat) Size() int { return len(h.members) }

// BoxKey returns the box public key of member i.
func (h *Hat) BoxKey(i int) []byte { return h.members[i].box }

// Shufflers returns the members picked to shuffle, in turn order.
func (h *Hat) Shufflers() []int { return h.shufflers }

// Turn returns how many shuffle turns are done in the current mix phase.
func (h *Hat) Turn() int { return h.turn }

// Expected returns the member whose shuffle turn it is, or -1.
func (h *Hat) Expected() int {
	if (h.phase == Mix1 || h.phase == Mix2) && h.turn < len(h.shufflers) {
		return h.shufflers[h.turn]
	}
	return -1
}

// Contents returns what is in the hat right now: the onions waiting for the
// next shuffler during a mix phase.
func (h *Hat) Contents() [][]byte {
	if h.phase == Mix1 || h.phase == Mix2 {
		return h.contents
	}
	return nil
}

// Slots returns the circle: slot k gives to slot k+1, wrapping round.
func (h *Hat) Slots() [][]byte { return h.slots }

// Slips returns the sealed slips; Slips()[k] is addressed to Slots()[k].
func (h *Hat) Slips() [][]byte { return h.slips }

// Seed returns the draw seed fixed when the last phone checked in.
func (h *Hat) Seed() []byte { return h.seed }

// Done reports whether member i has acted in the current phase.
func (h *Hat) Done(i int) bool { return i >= 0 && i < len(h.members) && h.members[i].done }

// Count returns how many members have acted in the current phase.
func (h *Hat) Count() int {
	if h.phase == Check || h.phase == Revealed {
		return h.confirmed
	}
	c := 0
	for _, m := range h.members {
		if m.done {
			c++
		}
	}
	return c
}

// Completed reports whether every phone confirmed its slip after the reveal.
func (h *Hat) Completed() bool { return h.phase == Revealed && h.confirmed == len(h.members) }

// Reason returns why the hat was voided.
func (h *Hat) Reason() string { return h.reason }

// OnionSize returns how long an onion must be before shuffle turn t of the
// current or coming round (t == 0 is what phones seal).
func (h *Hat) OnionSize(round, t int) int {
	inner := KeySize
	if round == 2 {
		inner = h.opts.Slip
	}
	return inner + SealOverhead*(len(h.shufflers)-t)
}

// Add puts a new member in the hat and returns its number.
func (h *Hat) Add(box, commit []byte, now time.Time) (int, error) {
	if err := h.live(now, Join); err != nil {
		return -1, err
	}
	if len(h.members) >= MaxPeople {
		return -1, ErrFull
	}
	if len(box) != KeySize || len(commit) != KeySize {
		return -1, ErrSize
	}
	for _, m := range h.members {
		if bytes.Equal(m.box, box) {
			return -1, ErrKeyTaken
		}
	}
	h.members = append(h.members, &member{box: box, commit: commit})
	return len(h.members) - 1, nil
}

// Lock freezes the roster. exclude is the member who locked it (the
// organiser), or -1; in rosters of five or more it is never picked to shuffle.
func (h *Hat) Lock(exclude int, now time.Time) error {
	if err := h.live(now, Join); err != nil {
		return err
	}
	if len(h.members) < MinPeople {
		return ErrTooFew
	}
	h.exclude = exclude
	h.move(Locked, now)
	return nil
}

// Ready reveals member i's seed. When the last seed is in, the draw seed is
// fixed as sha256 of the roster digest and every member's key, commitment
// and seed, the shufflers are picked from it, and sealing starts.
// The roster digest lets the caller bind data the hat does not see, such as
// names and signing keys.
func (h *Hat) Ready(i int, seed, roster []byte, now time.Time) error {
	m, err := h.actor(i, now, Locked)
	if err != nil {
		return err
	}
	if len(seed) != KeySize {
		return ErrSize
	}
	sum := sha256.Sum256(seed)
	if !bytes.Equal(sum[:], m.commit) {
		return ErrCommit
	}
	m.seed = seed
	m.done = true
	if h.Count() < len(h.members) {
		return nil
	}
	buf := []byte("hat/seed/v1")
	buf = append(buf, roster...)
	for _, m := range h.members {
		buf = append(buf, m.box...)
		buf = append(buf, m.commit...)
		buf = append(buf, m.seed...)
	}
	s := sha256.Sum256(buf)
	h.seed = s[:]
	h.shufflers = PickShufflers(h.seed, len(h.members), h.exclude)
	h.move(Seal1, now)
	return nil
}

// Seal takes member i's onion for the current seal phase. Once every member
// has sealed, the onions go into the hat in member order and mixing starts.
func (h *Hat) Seal(i int, onion []byte, now time.Time) error {
	want := Seal1
	round := 1
	if h.phase == Seal2 {
		want, round = Seal2, 2
	}
	m, err := h.actor(i, now, want)
	if err != nil {
		return err
	}
	if len(onion) != h.OnionSize(round, 0) || len(onion) > MaxBlob {
		return ErrSize
	}
	if h.contents == nil {
		h.contents = make([][]byte, len(h.members))
	}
	h.contents[i] = onion
	m.done = true
	if h.Count() == len(h.members) {
		h.move(h.phase.next(h.opts.Rounds), now)
	}
	return nil
}

// Mix takes shuffle turn output from member i. Only the expected shuffler may
// act, in order; anyone else gets ErrNotYourTurn and nothing changes.
// Output that shows tampering (a slip dropped, added or duplicated, or the
// wrong size) is not rejected: it voids the hat, for everyone, so the
// shuffler's own signed transaction is the public record of what went wrong.
func (h *Hat) Mix(i int, out [][]byte, now time.Time) error {
	if h.phase != Mix1 && h.phase != Mix2 {
		return ErrPhase
	}
	if h.Expire(now) {
		return ErrExpired
	}
	if i < 0 || i >= len(h.members) {
		return ErrMember
	}
	if i != h.Expected() {
		return ErrNotYourTurn
	}
	round := 1
	if h.phase == Mix2 {
		round = 2
	}
	turnName := h.phase.String() + " turn " + strconv.Itoa(h.turn+1)
	if reason := CheckMix(h.contents, out, h.OnionSize(round, h.turn+1)); reason != "" {
		h.void(turnName+": "+reason, now)
		return nil
	}
	h.contents = out
	h.turn++
	h.deadline = now.Add(h.opts.Step)
	if h.turn < len(h.shufflers) {
		return nil
	}
	// Last turn of the round.
	if round == 1 {
		h.slots = Circle(h.seed, out)
		h.contents = nil
		h.move(Check, now)
		return nil
	}
	slips, reason := MatchSlips(h.slots, out)
	if reason != "" {
		h.void(turnName+": "+reason, now)
		return nil
	}
	h.slips = slips
	h.contents = nil
	h.move(Revealed, now)
	return nil
}

// Confirm records that member i's phone checked its own slot (in Check) or
// its own slip (in Revealed) and found it right.
func (h *Hat) Confirm(i int, now time.Time) error {
	if h.phase != Check && h.phase != Revealed {
		return ErrPhase
	}
	m, err := h.actor(i, now, h.phase)
	if err != nil {
		return err
	}
	m.done = true
	h.confirmed++
	if h.phase == Check && h.confirmed == len(h.members) {
		h.move(h.phase.next(h.opts.Rounds), now)
	}
	return nil
}

// Void calls the draw off on member i's claim that its slot (in Check) or
// its slip (in Revealed) is missing, duplicated or forged.
func (h *Hat) Void(i int, reason string, now time.Time) error {
	if h.phase != Check && h.phase != Revealed {
		return ErrPhase
	}
	if h.Completed() {
		return ErrConfirmed
	}
	if h.Expire(now) {
		return ErrExpired
	}
	if i < 0 || i >= len(h.members) {
		return ErrMember
	}
	h.void(reason, now)
	return nil
}

// Expire voids the hat if the current phase or turn has run out of time and
// reports whether it did. A Revealed hat whose deadline passes is left as it
// is: every slip was delivered, only some confirmations are missing.
func (h *Hat) Expire(now time.Time) bool {
	if h.phase.Terminal() || !now.After(h.deadline) {
		return false
	}
	h.void("timed out in "+h.phase.String()+h.waitingFor(), now)
	return true
}

func (h *Hat) waitingFor() string {
	if h.phase == Join {
		return " (the roster was never locked)"
	}
	if h.Expected() >= 0 {
		return " waiting for shuffler " + strconv.Itoa(h.turn+1) + " of " + strconv.Itoa(len(h.shufflers))
	}
	return " waiting for " + strconv.Itoa(len(h.members)-h.Count()) + " phone(s)"
}

// actor checks that member i may act in phase p right now and has not yet.
func (h *Hat) actor(i int, now time.Time, p Phase) (*member, error) {
	if err := h.live(now, p); err != nil {
		return nil, err
	}
	if i < 0 || i >= len(h.members) {
		return nil, ErrMember
	}
	m := h.members[i]
	if m.done {
		return nil, ErrDuplicate
	}
	return m, nil
}

func (h *Hat) live(now time.Time, p Phase) error {
	if h.phase != p {
		return ErrPhase
	}
	// Revealed has no deadline: a late phone may still confirm or void.
	if p != Revealed && now.After(h.deadline) {
		return ErrExpired
	}
	return nil
}

func (h *Hat) move(to Phase, now time.Time) {
	if !CanMove(h.phase, to, h.opts.Rounds) {
		panic("hat: illegal move " + h.phase.String() + " -> " + to.String())
	}
	h.phase = to
	h.turn = 0
	h.confirmed = 0
	h.deadline = now.Add(h.opts.Step)
	for _, m := range h.members {
		m.done = false
	}
}

func (h *Hat) void(reason string, now time.Time) {
	h.move(Voided, now)
	h.reason = reason
	h.contents = nil
}

package hat

// Phase is a step of a draw. Phases only move forward, in the order they are
// declared here, except that any phase before Revealed may end in Voided.
type Phase uint8

const (
	Join     Phase = iota // people join; the roster is open
	Locked                // roster frozen; every phone reveals its seed
	Seal1                 // every phone posts an onion holding a fresh slot key
	Mix1                  // the shufflers peel and shuffle, one turn each
	Check                 // every phone confirms its slot made it through
	Seal2                 // every phone posts an onion holding a slip for its Santa
	Mix2                  // the shufflers peel and shuffle again
	Revealed              // each phone opens the one slip addressed to its slot
	Voided                // the draw was called off, for everyone
)

var phaseNames = [...]string{"Join", "Locked", "Seal1", "Mix1", "Check", "Seal2", "Mix2", "Revealed", "Voided"}

func (p Phase) String() string {
	if int(p) < len(phaseNames) {
		return phaseNames[p]
	}
	return "Unknown"
}

// Terminal reports whether no further phase can follow p in the normal flow.
// A Revealed draw can still be voided until every phone has confirmed its slip.
func (p Phase) Terminal() bool { return p == Revealed || p == Voided }

// next returns the phase that follows p in a draw with the given number of
// rounds. A one-round hat (rounds == 1) goes straight from Check to Revealed.
func (p Phase) next(rounds int) Phase {
	if p == Check && rounds == 1 {
		return Revealed
	}
	if p >= Revealed {
		return p
	}
	return p + 1
}

// CanMove reports whether the state machine allows moving from one phase to
// another in a hat with the given number of rounds (1 or 2).
func CanMove(from, to Phase, rounds int) bool {
	if from == Voided {
		return false
	}
	if to == Voided {
		return true
	}
	return from != Revealed && to == from.next(rounds)
}

package probe

// Minimal probe realm to test the offline deploy flow.
func Render(path string) string {
	return "probe ok\n"
}

// Bounty is a simple on-chain bounty board realm: anyone can post a bounty,
// another address can claim it, and only the creator can mark it done.
// Submission for Gnome Tavern Hackathon | Gno.land.
package bounty

import (
	"errors"
	"strconv"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Status is the lifecycle state of a bounty.
type Status int

const (
	StatusOpen Status = iota
	StatusClaimed
	StatusDone
)

func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusClaimed:
		return "claimed"
	case StatusDone:
		return "done"
	default:
		return "unknown"
	}
}

type bounty struct {
	id          int
	creator     address
	claimer     address
	title       string
	description string
	reward      string
	status      Status
}

var bounties []bounty

// PostBounty creates a new open bounty and returns its id.
// The reward is informational (e.g. "100ugnot"); no tokens are escrowed
// by this realm version — the on-chain record tracks who claimed it and
// whether the creator marked it done.
func PostBounty(cur realm, title, description, reward string) (int, error) {
	if title == "" {
		return -1, errors.New("title must not be empty")
	}
	if reward == "" {
		return -1, errors.New("reward must not be empty")
	}
	id := len(bounties)
	bounties = append(bounties, bounty{
		id:          id,
		creator:     cur.Previous().Address(),
		title:       title,
		description: description,
		reward:      reward,
		status:      StatusOpen,
	})
	return id, nil
}

// ClaimBounty lets an address claim an open bounty. The creator cannot
// claim their own bounty, and a bounty can only be claimed once.
func ClaimBounty(cur realm, id int) error {
	if id < 0 || id >= len(bounties) {
		return errors.New("bounty not found")
	}
	b := &bounties[id]
	if b.status != StatusOpen {
		return errors.New("bounty is not open")
	}
	caller := cur.Previous().Address()
	if caller == b.creator {
		return errors.New("creator cannot claim their own bounty")
	}
	b.claimer = caller
	b.status = StatusClaimed
	return nil
}

// CompleteBounty marks a claimed bounty as done. Only the bounty creator
// can do this, and only after someone has claimed it.
func CompleteBounty(cur realm, id int) error {
	if id < 0 || id >= len(bounties) {
		return errors.New("bounty not found")
	}
	b := &bounties[id]
	if cur.Previous().Address() != b.creator {
		return errors.New("only the creator can complete this bounty")
	}
	if b.status != StatusClaimed {
		return errors.New("bounty must be claimed before it can be completed")
	}
	b.status = StatusDone
	return nil
}

// BountyCount returns how many bounties have been posted.
func BountyCount() int {
	return len(bounties)
}

// GetBounty returns a human-readable summary of one bounty.
func GetBounty(id int) (string, error) {
	if id < 0 || id >= len(bounties) {
		return "", errors.New("bounty not found")
	}
	b := bounties[id]
	return formatBounty(b), nil
}

// ListBounties returns a one-line-per-bounty summary of all bounties.
func ListBounties() string {
	if len(bounties) == 0 {
		return "No bounties posted yet."
	}
	out := ""
	for _, b := range bounties {
		out += "#" + strconv.Itoa(b.id) + " [" + b.status.String() + "] " +
			sanitize.InlineText(b.title) + " — " + sanitize.InlineText(b.reward) + "\n"
	}
	return out
}

// Render shows the bounty board as markdown. User-supplied title and
// description are sanitized so they cannot break out of their markdown slot.
func Render(path string) string {
	open, claimed, done := 0, 0, 0
	for _, b := range bounties {
		switch b.status {
		case StatusOpen:
			open++
		case StatusClaimed:
			claimed++
		case StatusDone:
			done++
		}
	}
	out := "# Bounty Board\n\n"
	out += strconv.Itoa(len(bounties)) + " bount(y/ies): " +
		strconv.Itoa(open) + " open, " +
		strconv.Itoa(claimed) + " claimed, " +
		strconv.Itoa(done) + " done.\n\n"
	for _, b := range bounties {
		out += "## #" + strconv.Itoa(b.id) + " " + sanitize.InlineText(b.title) +
			" [" + b.status.String() + "]\n\n"
		out += formatBounty(b) + "\n\n"
	}
	return out
}

func formatBounty(b bounty) string {
	out := "Title: " + sanitize.InlineText(b.title) + "\n"
	if b.description != "" {
		out += "Description: " + sanitize.InlineText(b.description) + "\n"
	}
	out += "Reward: " + sanitize.InlineText(b.reward) + "\n"
	out += "Creator: " + b.creator.String() + "\n"
	if b.status != StatusOpen {
		out += "Claimer: " + b.claimer.String() + "\n"
	}
	out += "Status: " + b.status.String()
	return out
}

package bounty

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
)

func alice() address { return testutils.TestAddress("alice") }

func bob() address { return testutils.TestAddress("bob") }

func carol() address { return testutils.TestAddress("carol") }

// resetState clears the shared realm state. gno test runs all tests in
// one machine, so globals persist across tests in a file.
func resetState() {
	bounties = nil
}

// NOTE: testing.SetRealm and the crossing calls (PostBounty/ClaimBounty/
// CompleteBounty with cross(cur)) must be made directly in the test
// function body. Routing them through a helper breaks caller identity:
// SetRealm only overrides the calling frame (lost when the helper
// returns), and cross(cur) from inside a helper makes cur.Previous()
// return the wrong address.

func TestPostBountySingle(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))
	id, err := PostBounty(cross(cur), "Fix the README", "fix the docs", "100ugnot")
	if err != nil {
		t.Fatalf("PostBounty failed: %v", err)
	}
	if id != 0 {
		t.Fatalf("expected first bounty id 0, got %d", id)
	}
	if BountyCount() != 1 {
		t.Fatalf("expected 1 bounty, got %d", BountyCount())
	}
	got, err := GetBounty(0)
	if err != nil {
		t.Fatalf("GetBounty failed: %v", err)
	}
	for _, want := range []string{"Fix the README", "100ugnot", "open", alice().String()} {
		if !strings.Contains(got, want) {
			t.Fatalf("GetBounty missing %q: %s", want, got)
		}
	}
}

func TestPostBountyEmptyTitle(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))
	_, err := PostBounty(cross(cur), "", "desc", "100ugnot")
	if err == nil {
		t.Fatalf("expected error for empty title, got nil")
	}
	if BountyCount() != 0 {
		t.Fatalf("expected 0 bounties, got %d", BountyCount())
	}
}

func TestClaimBountyValid(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))
	if _, err := PostBounty(cross(cur), "Fix the README", "fix the docs", "100ugnot"); err != nil {
		t.Fatalf("PostBounty failed: %v", err)
	}
	testing.SetRealm(testing.NewUserRealm(bob()))
	if err := ClaimBounty(cross(cur), 0); err != nil {
		t.Fatalf("ClaimBounty failed: %v", err)
	}
	got, _ := GetBounty(0)
	for _, want := range []string{"claimed", bob().String()} {
		if !strings.Contains(got, want) {
			t.Fatalf("GetBounty missing %q after claim: %s", want, got)
		}
	}
	rendered := Render("")
	if !strings.Contains(rendered, "Fix the README") || !strings.Contains(rendered, "claimed") {
		t.Fatalf("Render missing bounty/claimed status: %s", rendered)
	}
}

func TestClaimBountyTwice(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))
	if _, err := PostBounty(cross(cur), "Fix the README", "fix the docs", "100ugnot"); err != nil {
		t.Fatalf("PostBounty failed: %v", err)
	}
	testing.SetRealm(testing.NewUserRealm(bob()))
	if err := ClaimBounty(cross(cur), 0); err != nil {
		t.Fatalf("first claim failed: %v", err)
	}
	testing.SetRealm(testing.NewUserRealm(carol()))
	if err := ClaimBounty(cross(cur), 0); err == nil {
		t.Fatalf("expected error for second claim, got nil")
	}
	got, _ := GetBounty(0)
	if !strings.Contains(got, bob().String()) {
		t.Fatalf("claimer changed after rejected second claim: %s", got)
	}
}

func TestClaimOwnBounty(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))
	if _, err := PostBounty(cross(cur), "Fix the README", "fix the docs", "100ugnot"); err != nil {
		t.Fatalf("PostBounty failed: %v", err)
	}
	// Alice is already the caller; claiming her own bounty must fail.
	if err := ClaimBounty(cross(cur), 0); err == nil {
		t.Fatalf("expected error for self-claim, got nil")
	}
	got, _ := GetBounty(0)
	if !strings.Contains(got, "open") {
		t.Fatalf("bounty should still be open after rejected self-claim: %s", got)
	}
